import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { db } from "./db";
import { ovh, ovhApi, ovhConfigured } from "./ovh";
import { hetznerApi, hetznerConfigured } from "./hetzner";
import { SANDBOX, sandboxIp, sandboxMac } from "./sandbox";
import { getSettingInt } from "./settings";
import { agentHasLiveDnatRule } from "./node-agent";
import type { NodeProvider } from "@prisma/client";

const execFileP = promisify(execFile);

/**
 * Is this address already the target of a live DNAT rule on ITS OWN node?
 * Some infrastructure (the shared-hosting node, VM 200) reaches its dedicated
 * IP entirely through a whole-IP DNAT rule to an internal address — it has no
 * OVH Virtual MAC at all, so the MAC-based check above cannot see it. A real
 * incident: this exact IP was one query away from being handed to a game
 * server because "no Virtual MAC bound" was mistaken for "free" — it was
 * actively carrying production hosting traffic via `iptables -t nat`. Treat
 * any address with a live DNAT target as claimed, unconditionally.
 *
 * Dispatches by node: the primary's own local iptables (unchanged), or the
 * owning node's agent for anyone else — this used to always check the LOCAL
 * host regardless of which node `address` actually belongs to, which for a
 * non-primary node's pool checks the wrong machine's kernel entirely and
 * could double-allocate an address that's actually already claimed there.
 */
async function hasLiveDnatRule(node: NodeRow, address: string): Promise<boolean> {
  if (!node.isPrimary) {
    try {
      return await agentHasLiveDnatRule(node, address);
    } catch {
      // Agent unreachable/not configured — same fail-open reasoning as the
      // local case below: a false "not claimed" is recoverable (the Virtual
      // MAC check and the existing DB row are the other guards), a sync that
      // silently no-ops for an entire node's pool forever is not.
      return false;
    }
  }
  try {
    const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"]);
    return stdout.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
  } catch {
    // iptables unreadable (permissions, not present, sandboxed test env) — fail
    // closed is wrong here (it would make every sync a no-op); fail to "not
    // claimed by this specific check" and rely on the Virtual MAC check plus
    // the existing DB row remaining authoritative for anything already tracked.
    return false;
  }
}

/**
 * What OVH actually bills per additional/failover IPv4 in the pool, in cents.
 * Single source of truth for both the IP-pool page's "OVH cost" stat and the
 * admin Accounting dashboard's auto-pulled infrastructure expense line — before
 * this it existed only as a copy of the same number hardcoded on the IP page.
 */
export const OVH_IP_UNIT_COST_CENTS = 239;

/** Hetzner's "additional IP" rate, confirmed live in the Robot panel 2026-09-15. */
export const HETZNER_IP_UNIT_COST_CENTS = 200;

/**
 * Fallback monthly price for a dedicated IPv4. Defaults to 0 — a dedicated IP is
 * INCLUDED on every plan (its cost is folded into plan pricing, as the marketing
 * pages state). The admin `dedicated_ip_price_cents` setting is the source of
 * truth; use `dedicatedIpMonthlyCents()` in billing paths, not this constant.
 */
export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 0);

/**
 * The monthly dedicated-IP surcharge actually charged, from the admin setting
 * (`dedicated_ip_price_cents`, default 0 = included). Single source of truth for
 * every order/renewal/display path so they can never disagree.
 *
 * NORMALISED to a non-negative whole number of cents, exactly as
 * `extraDiskPerGbCents` (lib/disk-expand.ts) already does for the other
 * admin-priced add-on. `getSettingInt` is a raw `Number()` of whatever string sits
 * in the `Setting` row, so it happily returns 2.5 or -500. This value is multiplied
 * by the term length straight into `chargeCents` (lib/order.ts orderQuote) and into
 * `renewalCharge`, and from there into `debitWallet`, `unit_amount` and an Invoice
 * row — every one of which is integer cents. A fractional setting produced a
 * fractional charge that failed at Stripe or Prisma AFTER the customer had agreed
 * to it; a negative one silently discounted the plan.
 */
export async function dedicatedIpMonthlyCents(): Promise<number> {
  const v = await getSettingInt("dedicated_ip_price_cents", DEDICATED_IP_PRICE_CENTS);
  return Math.max(0, Math.round(v));
}
/** Keep this many spare IPs in the pool; auto-order/release aims to stay near it. */
export const DEDICATED_IP_BUFFER = Number(process.env.DEDICATED_IP_BUFFER ?? 2);

/** OVH failover gateway = the host's /24 gateway (…​.254). OVH-specific — every
 *  additional/failover IP on an OVH dedicated server shares this one convention. */
function ovhGatewayFor(nodePublicIp: string): string {
  const parts = nodePublicIp.split(".");
  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
}

/** Back-compat wrapper for any caller still expecting the old single-node signature. */
export function ovhGateway(): string {
  return ovhGatewayFor(process.env.PUBLIC_IP ?? "51.79.162.96");
}

type NodeRow = {
  id: string;
  name: string;
  provider: NodeProvider;
  publicIp: string;
  providerServerId: string | null;
  isPrimary: boolean;
  agentPort: number;
  agentTokenEnc: string | null;
};

const NODE_ROW_SELECT = {
  id: true,
  name: true,
  provider: true,
  publicIp: true,
  providerServerId: true,
  isPrimary: true,
  agentPort: true,
  agentTokenEnc: true,
} as const;

/** Resolve the Node a dedicated-IP operation should act against: the id passed
 *  in explicitly, else the primary node — same fallback shape as
 *  worker/index.ts's nodeFor(), so single-node callers need no changes at all. */
async function resolveNode(nodeId?: string): Promise<NodeRow | null> {
  if (nodeId) {
    return db.node.findUnique({ where: { id: nodeId }, select: NODE_ROW_SELECT });
  }
  return db.node.findFirst({ where: { isPrimary: true }, select: NODE_ROW_SELECT });
}

/** Is the right provider API even configured for this node? Dispatches by
 *  provider so a Hetzner-hosted server never silently falls through to
 *  checking whether OVH happens to be configured (the real bug this fixes —
  return null;
}

/**
 * Claim a free IP for a server and set it up so the VM can use it — an OVH
 * Virtual MAC for an OVH-node IP, or nothing extra for a Hetzner-node IP
 * (Hetzner additional IPs route straight to the server's real MAC, no
 * separate MAC object to create). Returns the address + a MAC (OVH only,
 * empty string for Hetzner) + gateway, or null if none available.
 *
 * `nodeId` should be the server's OWN node — pass it explicitly from a
 * caller that already resolved it (e.g. worker/index.ts's `nodeFor(server)`);
 * omitted, this falls back to the primary node, identical to this file's
 * pre-multi-node behavior.
 */
export async function allocateDedicatedIp(
  serverId: string,
  vmid: number,
  nodeId?: string,
): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
  if (SANDBOX) {
    // Hand out a synthetic dedicated IP without any provider call or pool mutation.
    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
  }
  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
  // server already holds a fully-allocated dedicated IP, return it instead of
  // claiming a second pool IP — re-claiming would leak an IP and P2002 on the
  // unique DedicatedIp.serverId. An OVH row also needs a bound Virtual MAC to
  // count as "done"; a Hetzner row is done once ASSIGNED (no MAC step).
  const mine = await db.dedicatedIp.findUnique({ where: { serverId }, include: { node: true } });
  if (mine && mine.status === "ASSIGNED" && (mine.node.provider === "HETZNER" || mine.virtualMac)) {
    return { address: mine.address, virtualMac: mine.virtualMac ?? "", gateway: await gatewayFor(mine.node, mine.address) };
  }

  const node = await resolveNode(nodeId);
  if (!node) return null;
  if (!(await dedicatedIpProviderConfigured(node.id))) return null;

  // Atomically claim a FREE ip belonging to THIS node's pool. Excluding
  // purpose: INTERNAL here is a second, independent guard (alongside the
  // sync-time checks above) against ever handing an admin-marked internal IP
  // to a customer server.
  const claim = await db.$transaction(async (tx) => {
    const ip = await tx.dedicatedIp.findFirst({
      where: { status: "FREE", purpose: "CUSTOMER", nodeId: node.id },
      orderBy: { createdAt: "asc" },
    });
    if (!ip) return null;
    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
    return ip;
  });
  if (!claim) return null;

  try {
    if (node.provider === "HETZNER") {
      // Hetzner DOES require a registered virtual MAC per single additional
      // IP (corrected 2026-09-29 — see this file's header comment for the
      // real incident: any other MAC on the guest triggers Hetzner's own
      // network-abuse filtering). Robot's endpoint is rate-limited to 10
      // PUT/DELETE calls per hour, so ALWAYS check for an existing MAC via
      // GET first and only PUT when nothing is assigned yet — this must
      // never "refresh" a MAC that's already registered.
      let hetznerMac = "";
      try {
        // GET 404s ("mac not found") when nothing is registered yet — that's
        // the ordinary first-allocation case, not a failure; only create then.
        try {
          const info = await hetznerApi.macInfo(claim.address);
          hetznerMac = info?.mac?.mac ?? "";
        } catch (e) {
          if (!/-> 404/.test(String((e as Error)?.message))) throw e;
        }
        if (!hetznerMac) {
          const created = await hetznerApi.createMac(claim.address);
          hetznerMac = created?.mac?.mac ?? "";
        }
      } catch (e) {
        console.error(`[dedicated-ip] Hetzner virtual MAC lookup/create failed for ${claim.address} — provisioning will fall back to no explicit MAC (Hetzner may filter this as abuse)`, e);
      }
      await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: hetznerMac || null } });
      return { address: claim.address, virtualMac: hetznerMac, gateway: await gatewayFor(node, claim.address) };
    }
    // OVH branch — unchanged mechanics, just keyed off this node's own service name.
    const SERVER = node.providerServerId!;
    let mac = await findVirtualMacForIp(SERVER, claim.address);
    if (!mac) {
      // Creation is asynchronous (returns a task) — kick it off then poll.
      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
      for (let i = 0; i < 40 && !mac; i++) {
        await new Promise((r) => setTimeout(r, 3000));
        mac = await findVirtualMacForIp(SERVER, claim.address);
      }
    }
    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
    return { address: claim.address, virtualMac: mac, gateway: ovhGatewayFor(node.publicIp) };
  } catch (e) {
    // Roll the claim back to FREE on failure
    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
    throw e;
  }
}

/**
 * The gateway a VM should use for this IP. OVH: the well-known "/24 -> .254"
 * convention, same for every additional IP on that node. Hetzner: NOT a
 * fixed formula — Hetzner assigns a distinct gateway per single additional
 * IP (confirmed against Hetzner's own docs this session: additional IP
 * SUBNETS route via the server's main IP with no separate gateway, but
 * single additional IPs each come with their own gateway address) — read it
 * from Hetzner's own `/ip/{ip}` response rather than guessing a formula.
 * NOTE: the exact response field name below (`gateway`) hasn't been verified
 * against a real Hetzner additional IP yet (none exist in the pool at the
 * time this was written) — confirm it the first time this path actually
 * runs, before trusting it for a real customer's network config.
 */
async function gatewayFor(node: NodeRow, address: string): Promise<string> {
  if (node.provider === "OVH") return ovhGatewayFor(node.publicIp);
  try {
    const info = await hetznerApi.ipInfo(address);
    if (info?.ip?.gateway) return info.ip.gateway as string;
  } catch {
    /* fall through */
  }
  return node.publicIp; // best-effort fallback; see doc comment above
}

/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual
 *  MAC for an OVH-node IP). A Hetzner-node IP's registered MAC is
 *  DELIBERATELY left in place — it's registered per-IP, not per-customer, so
 *  the next allocation of this same address just finds it via `macInfo` and
 *  reuses it (allocateDedicatedIp already checks before creating). Hetzner
 *  rate-limits PUT/DELETE on this endpoint to 10/hour; there is no benefit
 *  to spending that budget tearing a MAC down just to recreate the same one
 *  again shortly after. */
export async function releaseDedicatedIp(serverId: string): Promise<void> {
  if (SANDBOX) return;
  const ip = await db.dedicatedIp.findUnique({ where: { serverId }, include: { node: true } });
  if (!ip) return;
  if (ip.node.provider === "OVH" && ovhConfigured() && ip.virtualMac && ip.node.providerServerId) {
    const SERVER = ip.node.providerServerId;
    try {
      // Remove the IP from the vMAC, then delete the vMAC.
      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
    } catch {
      /* best-effort */
    }
  }
  await db.dedicatedIp.update({
    where: { id: ip.id },
    data: { status: "FREE", serverId: null, virtualMac: null },
  });
  // `Server.ipAddress` is UNIQUE and separate from this pool table — every
  // caller used to have to remember to clear it themselves, and one (the
  // admin "release IP" action) didn't, which left a FREE pool row while a
  // live server still held that exact address in `Server.ipAddress`. The next
  // server to claim the pool row then failed provisioning with a P2002 on
  // every retry, deterministically, since the failed-provision cleanup just
  // re-freed the same already-stuck row. Clearing it here — for every caller,
  // guarded to only touch the row that still holds THIS address, since the
  // column also holds ordinary NAT IPs for other servers — closes that class
  // of bug for good instead of relying on each call site to remember.
  await db.server.updateMany({
    where: { id: serverId, ipAddress: ip.address },
    data: { ipAddress: null, ipv6: null },
  });
}

/** Set reverse DNS (PTR) for a dedicated IP — dispatches to the owning node's provider. */
export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
  const ip = await db.dedicatedIp.findUnique({ where: { address }, include: { node: true } });
  if (!ip) return;
  if (ip.node.provider === "HETZNER") {
    if (!hetznerConfigured()) return;
    await hetznerApi.setReverse(address, reverse);
  } else {
    if (!ovhConfigured()) return;
    await ovhApi.setReverse(`${address}/32`, address, reverse);
  }
  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
}

  await notify(server.userId, `Server ${server.hostname} resized to ${resizedToName}`,
    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
    `/dashboard/servers/${server.id}`);
}

/**
 * ASSIGN_DEDICATED_IP — deliver a dedicated public IPv4 to an ALREADY-
 * provisioned server (VPS or game) that just paid for one
 * (lib/dedicated-ip-purchase.ts applyDedicatedIpPurchase). Payment already
 * happened at enqueue time; this handler is responsible only for claiming the
 * IP and reconfiguring the VM's network.
 *
 * Reuses the EXACT same allocate + reconfigure sequence `suspend(job, true)`
 * (UNSUSPEND) already runs to re-give a server its dedicated IP after it comes
 * back — see that function's `wantDedicated` branch above. Nothing here
 * invents new Proxmox/iptables behavior:
 *   1. `allocateDedicatedIp` claims a FREE pool IP + creates the OVH Virtual
 *      MAC (idempotent — a retry after a partial failure returns the same
 *      already-ASSIGNED IP rather than claiming a second one).
 *   2. The VM's `net0`/`ipconfig0` are pointed at it.
 *   3. `Server.ipAddress`/`sshPort` are updated (`sshPort: null` — dedicated
 *      servers own every port directly, and NULL is how a NAT slot is
 *      released back to the pool; `syncPortForwards`'s query already excludes
 *      any server with `sshPort: null`, so the old NAT/SSH forward rules are
 *      torn down on the very next sync below).
 *   4. `wantsDedicatedIp` is persisted so a LATER suspend/unsuspend cycle
 *      re-allocates this server a dedicated IP instead of silently dropping
 *      it back to NAT — `suspend(job, true)`'s game branch reads exactly this
 *      flag with no other fallback.
 *
 * A power cycle is required for the new net0/ipconfig0 to take effect (cloud-
 * init only re-applies network config at boot), so a running VM is stopped and
 * started, mirroring `resize()`'s own CPU/RAM power-cycle above. Listed in
 * VM_STATE_FAILURE_JOBS (like RESIZE) since a failure here can leave the VM
 * mid-power-cycle; `reconcileFailedDedicatedIp` below refunds the charge and
 * releases any IP this run managed to claim.
 */
async function assignDedicatedIp(job: Job) {
  const server = await loadServer(job);
  const existing = await db.dedicatedIp.findUnique({ where: { serverId: server.id } });
  if (existing) {
    // Already has one — a previous attempt at this same job must have
    // completed the DB/network side before failing on a later step (or this is
    // a harmless re-run). Nothing left to deliver.
    return;
  }

  if (SANDBOX) {
    // Sandbox: synthesize a dedicated IP without any OVH/Proxmox call, but
    // still create the real DedicatedIp row (unlike provision()'s SANDBOX
    // path) — this is a customer-facing PAID purchase, and `server.dedicatedIp`
    // must actually reflect it so the dashboard, billing and a later
    // suspend/unsuspend cycle all see a real dedicated IP.
    const address = sandboxIp(server.vmid ?? 0);
    const sandboxNodeId = server.nodeId ?? (await db.node.findFirst({ where: { isPrimary: true }, select: { id: true } }))?.id;
    if (!sandboxNodeId) throw new Error("assignDedicatedIp (sandbox): no node available to attribute the synthetic IP to");
    await db.$transaction([
      db.dedicatedIp.create({
        data: { address, ovhBlock: `${address}/32`, nodeId: sandboxNodeId, status: "ASSIGNED", serverId: server.id, purpose: "CUSTOMER" },
      }),
      db.server.update({
        where: { id: server.id },
        data: { ipAddress: address, sshPort: null, wantsDedicatedIp: true },
      }),
    ]);
    await notify(server.userId, `Dedicated IP added to ${server.hostname} (sandbox)`,
      `Your server now connects on ${address} (no real network was touched).`,
      `/dashboard/servers/${server.id}`);
    return;
  }

  if (!server.vmid) throw new Error("assign dedicated ip: server has no VM yet");
  const d = await allocateDedicatedIp(server.id, server.vmid, server.nodeId ?? undefined);
  if (!d) throw new Error("assign dedicated ip: no free IP available in this server's node pool (or its provider isn't configured)");

  const { conn } = await nodeFor(server);
  const wasRunning = server.status === "RUNNING";
  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
    // Hetzner returns virtualMac: "" (no Virtual-MAC mechanism, unlike OVH) —
    // see the identical fix + comment in provision() above. ALWAYS set net0
    // (not just when a MAC exists) — the clone's template may sit on a
    // node-local NAT-only bridge with no path to a real public IP at all;
    // omitting net0 here left a real dedicated IP wired to a bridge that
    // could never deliver it (confirmed live 2026-09-29). No MAC needed for
    // Hetzner; Proxmox assigns one when none is given.
    net0: d.virtualMac ? `virtio=${d.virtualMac},bridge=vmbr0` : `virtio,bridge=vmbr0`,
    ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
  });
  await db.server.update({
    where: { id: server.id },
    data: { ipAddress: d.address, sshPort: null, wantsDedicatedIp: true },
  });
  if (wasRunning) {
    try {
      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
      await conn.waitForTask(stopUpid, 120_000);
    } catch {
      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
      await conn.waitForTask(stopUpid);
    }
    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
    await conn.waitForTask(startUpid);
  }
  // The server no longer holds a NAT SSH port (sshPort is now null) — reconcile
  // the shared DNAT chain so its old port-forward/SSH rules are removed.
  await syncPortForwardsBestEffort(`assign dedicated ip ${server.hostname}`);
