    `Your server now connects on ${d.address}.`,
    `/dashboard/servers/${server.id}`);
}

async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
  const server = await loadServer(job);
  const payload = (job.payload ?? {}) as { name?: string };
  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
  if (!name) throw new Error("snapshot: invalid name");
  if (SANDBOX) {
    await notify(
      server.userId,
      `Snapshot ${op} (sandbox): ${name}`,
      `Sandbox snapshot ${op} completed (no real VM was touched).`,
      `/dashboard/servers/${server.id}`
    );
    return;
  }
  const { conn } = await nodeFor(server);
  let upid: string;
  if (op === "create") {
    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
  } else if (op === "delete") {
    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
  } else {
    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
  }
  await conn.waitForTask(upid, 600_000);
  if (op === "rollback") {
    // rollback leaves the VM stopped; bring it back if the server should be running
    const current = await db.server.findUnique({ where: { id: server.id } });
    if (current?.status === "RUNNING") {
      try {
        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
        await conn.waitForTask(startUpid);
      } catch { /* may already be running */ }

      // Resync the root password. `rollback` puts the snapshot's OLD disk
      // content back — including whatever /etc/shadow existed when it was
      // taken — which can hold an older password than Server.rootPasswordEnc
      // if a PASSWORD_RESET (or anything else) changed it since the snapshot
      // was created. Left alone, every later SSH from the platform would
      // authenticate with the DB's (now wrong) password against the guest's
      // reverted (now correct-for-the-snapshot) one — the exact "All
      // configured authentication methods failed" divergence documented on
      // applyPasswordToGuest (lib/proxmox.ts) and on provision()'s password-
      // reuse fix above. Best-effort: a failure here does not fail the
      // rollback itself (the VM genuinely is back at the requested restore
      // point) but is logged loudly since a stale password can otherwise look
      // exactly like an unrelated SSH outage.
      const pw = serverRootPassword(current ?? server);
      if (pw && server.vmid) {
        const ready = await waitForGuestAgent(conn, conn.node, server.vmid);
        if (ready) {
          const applied = await applyPasswordToGuest(conn, server.vmid, pw);
          if (!applied) {
            console.error(
              `[worker] snapshot rollback: could not resync guest password for server ${server.id} (vmid ${server.vmid})`
            );
          }
        } else {
          console.error(
            `[worker] snapshot rollback: guest agent never answered for server ${server.id} (vmid ${server.vmid}) — password may now be stale`
          );
        }
      }
    }
  }
}

async function passwordReset(job: Job) {
  const server = await loadServer(job);
  if (SANDBOX) {
    // Sandbox: rotate the stored password only — never touch a real VM.
    const password = generatePassword();
    await db.server.update({ where: { id: server.id }, data: { rootPassword: null, rootPasswordEnc: encryptSecret(password) } });
    await notify(
      server.userId,
      `Root password reset (sandbox) for ${server.hostname}`,
      "Your new root password is on the server's Overview tab (no real VM was touched).",
      `/dashboard/servers/${server.id}`
    );
    return;
  }
  if (!server.vmid) throw new Error("password reset: server has no VM yet");
  const { conn } = await nodeFor(server);
  const password = generatePassword();

  // Preferred path: set it live via the qemu-guest-agent (no reboot needed).
  // Shared with SNAPSHOT_ROLLBACK/BACKUP_RESTORE's post-revert resync — see
  // applyPasswordToGuest's doc-comment (lib/proxmox.ts) for why this exact

  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
  // EVERY disk the vmid owns, including attached block-storage Volume disks
  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
  // by that vmid, and both purge and the default destroy (which removes disks
  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
  // can be re-attached after the reinstall. This runs BEFORE any status change or
  // destructive call, so a blocked reinstall touches nothing.
  //
  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
  // let the worst path through: fill a volume, Detach (the UI says "Data is
  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
  // Detaching is therefore NOT sufficient protection, and telling the customer to
  // detach was wrong advice; they must delete the volume (which destroys just
  // that disk, deliberately) or move it to another server first.
  const pinnedVolumes = await db.volume.findMany({
    where: { serverId: server.id },
  });
  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
  const realPinned = pinnedVolumes.filter(
    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
  );
  if (realPinned.length > 0) {
    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
    throw new Error(
      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
        `Reinstalling purges every disk this server owns — including detached volumes ` +
        `that are still assigned to it — and that cannot be undone.`
    );
  }

  const { conn } = await nodeFor(server);
  // Clear the stored root password BEFORE destroying the VM. `provision()`
  // below reuses `serverRootPassword(server)` instead of minting a fresh one
  // whenever `server.vmid` is already set — that reuse exists for a RETRY
  // (cloud-init's password module is once-per-instance, so a retry must not
  // overwrite Server.rootPasswordEnc with a value the already-booted guest
  // never saw; see provision()'s own comment on this line). A REINSTALL is not
  // a retry: `destroyVm` just above genuinely deletes the VM, so the guest
  // that "already saw" the old password no longer exists — the next one is a
  // brand-new instance that has never seen ANY password yet. Without this,
  // reinstall silently kept the customer's old root password forever (found
  // in the 2026-09-24 audit) — the one operation a customer expects to rotate
  // credentials (e.g. after a suspected compromise) quietly didn't. Nulling
  // both columns here makes `serverRootPassword(server)` return null once
  // provision() reloads the row, so its existing `?? generatePassword()`
  // fallback mints a real fresh one — same code path a first-ever provision
  // takes, no new logic needed there.
  await db.server.update({
    where: { id: server.id },
    data: { status: "REINSTALLING", rootPassword: null, rootPasswordEnc: null },
  });
  if (server.vmid) await destroyVm(conn, server.vmid);
  await provision(job);
}

