 *  - ark, arkasa, tf2, l4d2, projectzomboid: native Source RCON, each verified
 *    2026-09-24 against the platform's real docker image/entrypoint (see each
 *    entry's own comment) — read from the docker CONTAINER's own env
 *    (`source: "docker-env"`), not a file: ARK/ARK:ASA never write the
 *    password to disk at all (arkmanager launch-arg only), and reading all
 *    five the same way avoids guessing at five different community images'
 *    on-disk config layouts.
 *  - rust:      RCON is WebSocket (rcon.web) — a DIFFERENT protocol; deferred.
 *  - squad:     genuine Source RCON exists, but this platform's image ships it
 *    DISABLED (no password ever configured) — a provisioning gap, not a
 *    protocol gap; see squad's own comment below.
 *  - kf2:       has a real remote admin surface (WebAdmin), but it's HTTP, not
 *    the Source RCON binary wire this file speaks — different transport, out
 *    of scope this pass.
 *  - valheim:   no native RCON (needs a BepInEx mod) — console disabled.
 *  - terraria:  vanilla has only a local stdin console — console disabled.
 *  - nightingale, spaceengineers, barotrauma, sandstorm, dst, vintagestory,
 *    necesse, soulmask, and every other family not listed above: no confirmed
 *    Source-RCON wire (soulmask's is confirmed DEAD — loopback-bound inside
 *    its own container, see its comment below) — genuinely "none", not a gap
 *    left unresearched by default assumption.
 */
export type LogResult = { ok: true; lines: string[]; unit: string | null } | { ok: false; error: string };

/**
 * Tail the game service's recent logs. Resolves the unit from the family hints
 * (compile-time constants), then reads the last `n` journal lines; if journald has
 * nothing, falls back to a `.log` file under the data roots. Read-only.
 */
export async function readGameLogs(conn: Client, spec: GameControlSpec, n = 200): Promise<LogResult> {
  const lines = Math.min(Math.max(Math.trunc(n) || 200, 20), 500);
  const hints = spec.serviceHints.map(shq).join(" ");
  const roots = spec.dataRoots.map(shq).join(" ");
  const script = [
    `unit=""`,
    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
    `echo "NXLOG:UNIT:${"$"}{unit:-none}"`,
    `if [ -n "$unit" ]; then journalctl -u "$unit" -n ${lines} --no-pager 2>/dev/null; fi`,
    // Fallback: newest *.log under the data roots (bounded).
    `f=""; for r in ${roots}; do [ -d "$r" ] && f=$(find "$r" -maxdepth 4 -type f -name '*.log' 2>/dev/null | head -1) && [ -n "$f" ] && break; done`,
    `if [ -n "$f" ]; then echo "NXLOG:FILE:$f"; tail -n ${lines} "$f" 2>/dev/null; fi`,
  ].join("\n");
  const { stdout } = await exec(conn, script, QUICK_TIMEOUT_MS);
  const all = stdout.split(/\r?\n/);
  let unit: string | null = null;
  const out: string[] = [];
  for (const l of all) {
    const m = /^NXLOG:UNIT:(.*)$/.exec(l);
    if (m) {
      unit = m[1] === "none" ? null : m[1];
      continue;
    }
    if (/^NXLOG:FILE:/.test(l)) continue;
    out.push(l);
  }
  while (out.length && out[out.length - 1].trim() === "") out.pop();
  return { ok: true, lines: out.slice(-lines), unit };
}

  return [
    `unit=""`,
    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
    `if [ -z "$unit" ]; then echo "NXGP:UNIT:NONE"; exit 0; fi`,
    `echo "NXGP:UNIT:$unit"`,
    `systemctl ${action} "$unit" >/dev/null 2>&1; echo "NXGP:RC:$?"`,
    `st=$(systemctl is-active "$unit" 2>/dev/null); echo "NXGP:STATE:${"$"}{st:-unknown}"`,
    `echo "NXGP:END"`,
  ].join("\n");
}

/** GAME_POWER — start/stop/restart the game SERVICE (not the VM). */
export async function gamePower(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("game power: missing serverId");
  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  const spec = resolveSpec(server);

  const p = (job.payload ?? {}) as { action?: string; announce?: boolean };
  const action = String(p.action ?? "");
  if (!isPowerAction(action)) throw new Error(`unsupported power action: ${action}`);
  const href = `/dashboard/servers/${server.id}?tab=manage`;

  if (SANDBOX) {
    await notify(
      server.userId,
      `Game service ${action} (sandbox) on ${server.hostname}`,
      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
      href
    );
    return;
  }
  if (server.status !== "RUNNING") throw new Error("game power: VM is not running");

  // Optional pre-restart announce over RCON (best-effort; never fails the action).
  if (action === "restart" && p.announce && spec.rcon === "source") {
    try {
      await withServerSsh(server as SftpServer, (conn) =>
        runRcon(conn, spec, "say Server is restarting now (scheduled/maintenance).")
      );
    } catch (e) {
      console.error("[game-control] restart announce failed (continuing)", e);
    }
  }

  const out = await withServerSsh(server as SftpServer, (conn) => exec(conn, powerScript(spec, action), SETUP_TIMEOUT_MS));
  const text = out.stdout;
  if (/NXGP:UNIT:NONE/.test(text)) {
    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `No game service unit was found on ${server.hostname}.`, href);
    throw new Error("game power: no service unit found");
  }
  const rc = Number(/NXGP:RC:(-?\d+)/.exec(text)?.[1] ?? "1");
  const state = /NXGP:STATE:(\w+)/.exec(text)?.[1] ?? "unknown";
  if (!/NXGP:END/.test(text) || rc !== 0) {
    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `The ${action} did not complete on ${server.hostname} (state: ${state}).`, href);
    throw new Error(`game power: ${action} failed rc=${rc} state=${state}`);
  }

  // FOUND LIVE 2026-09-20: this used to notify success on rc===0 + an END
  // marker alone, without ever checking `state` — so a unit that restarted
  // straight into "failed" (or stayed "activating"/crash-looping) was still
  // reported to the customer as "restarted (now failed)", i.e. success. A
  // `Restart=always` unit around a crash-looping container (exactly what a
  // wrong-Java-version Minecraft image produces — see
  // lib/game-config.ts's MINECRAFT_JAVA_CUTOVERS) reports "active" between
  // crashes just as readily as a genuinely healthy server, so `systemctl`
  // alone was never going to be enough either way.
  if (action !== "stop" && state !== "active") {
    await notify(
      server.userId,
      `Could not ${action} the ${spec.label} service`,
      `${spec.label} on ${server.hostname} is "${state}" after the ${action}, not active. ` +
        `Diagnose with: systemctl status <unit> ; journalctl -u <unit> -n 50`,
      href
    );
    throw new Error(`game power: ${action} left service in state=${state}`);
  }

  // Real port-bound check — the same in-guest positive-confirmation path
  // PROVISION uses (worker/provision-health.ts's checkGamePortOpen +
  // gamePortBoundInGuest), reused here for the other place this class of bug
  // hid: a systemd unit reporting "active" proves the OBJECT exists, never
  // that the game process inside actually bound its port. Best-effort and
  // deliberately short (GAME_POWER_PORT_CHECK_TIMEOUT_MS) — families with no
  // GAME_PORT entry, or a NAT server whose game port isn't forwarded, skip
  // this silently rather than block or falsely fail on a check that can't
  // mean anything for them.
  if (action !== "stop" && state === "active") {
    const game = gamePortForServer(server);
    const checkHost = server.dedicatedIp?.address ?? server.node?.publicIp ?? null;
    if (game && checkHost) {
      const portCheck = await checkGamePortOpen(checkHost, game.port, game.protocol, {
        timeoutMs: spec.powerStartTimeoutMs ?? GAME_POWER_PORT_CHECK_TIMEOUT_MS,
        intervalMs: GAME_POWER_PORT_CHECK_INTERVAL_MS,
        verifyBound: () => gamePortBoundInGuest(server as SftpServer, game.port, game.protocol),
      });
      if (!portCheck.ok) {
        await notify(
          server.userId,
          `${spec.label} service ${action}ed, but the game never came online`,
          `systemd reports ${server.hostname} as active, but nothing is actually answering on ` +
            `${game.port}/${game.protocol}: ${portCheck.error ?? "no further detail"}. Check the game's own logs — ` +
            `this usually means the server process itself failed to start even though its service is "running".`,
          href
        );
        throw new Error(`game power: ${action} reported active but port ${game.port}/${game.protocol} never bound: ${portCheck.error ?? ""}`);
      }
    }
  }

  await notify(
    server.userId,
    `${spec.label} service ${action}ed on ${server.hostname}`,
    action === "stop" ? "The game service was stopped." : `The game service was ${action}ed (now ${state}).`,
    href
  );

  // Persist the real systemd state so the dashboard's status dot can reflect
  // it. GAME_POWER only ever touches the game SERVICE inside the VM, never
  // `Server.status` (the VM's own power state) — those are genuinely
  // different things, but the panel's "Online/Offline" label was reading
  // `Server.status` alone, so a customer who stopped just their game service
  // (VM still up) kept seeing "Online" no matter what they did. Found live
  // 2026-09-09 via a real customer confused why "Status: Online" never
  // changed after repeated stop/start attempts. `_serviceState` follows the
  // same gameConfig-internal-marker convention as `_real`/`_realOk`/
  // `_appliedAt` elsewhere in this file's siblings — no schema migration
  // needed for what's fundamentally transient, best-effort runtime state.
  try {
    const fresh = await db.server.findUnique({ where: { id: server.id }, select: { gameConfig: true } });
    const gameConfig = { ...(fresh?.gameConfig as Record<string, unknown> | null ?? {}), _serviceState: state };
    await db.server.update({ where: { id: server.id }, data: { gameConfig } });
  } catch (e) {
    console.error(`[game-control] could not persist _serviceState for ${server.hostname}`, e);
  }
}

