/**
 * Where the deploy wizard's region cards measure latency TO.
 *
 * The number on a region card ("Singapore · Asia · 38 ms") is a real round-trip
 * measured by the visitor's own browser (components/nx/useRegionLatency.ts) —
 * never a nominal or estimated figure (lib/nx/catalog.ts's `Region.ms` is
 * nominal and is deliberately NOT what the card shows). A browser can only
 * time a request to something it can actually reach over HTTPS, so each
 * region needs a small endpoint physically served FROM that region. This file
 * says which URL that is, per region code, and returns nothing for a region
 * that has none — the card then shows a neutral "— ms", not a guess.
 *
 * Sources, in order:
 *  1. `REGION_PROBE_URLS` (env), e.g.
 *       REGION_PROBE_URLS="sgp1=/api/tools/ping,fsn1=https://fsn1-probe.example/ping"
 *     Only same-origin paths ("/...") or absolute https:// URLs are accepted.
 *     Cross-origin probes are fetched `no-cors`, so any tiny static file with
 *     `Cache-Control: no-store` works — no CORS headers needed.
 *  2. Default when the env var is unset: the portal itself is served from the
 *     PRIMARY node (nginx → nxeon-web on the same box — see CLAUDE.md), so the
 *     app's own `/api/tools/ping` (the endpoint the public Latency Test tool
 *     already uses) is a genuine probe of the primary node's region. No other
 *     node serves anything a browser can reach over HTTPS today — node-2
 *     (fsn1) exposes only its Proxmox API / node-agent on self-signed certs and
 *     the NAT'd game/VM ports, none of which a browser can or should time.
 *
 * Server-only (reads process.env); the resolved map is handed to the client as
 * plain data on each `Region`.
 */

export function parseRegionProbeUrls(raw: string | undefined | null): Record<string, string> | null {
  if (!raw || !raw.trim()) return null;
  const out: Record<string, string> = {};
  for (const pair of raw.split(",")) {
    const eq = pair.indexOf("=");
    if (eq <= 0) continue;
    const code = pair.slice(0, eq).trim();
    const url = pair.slice(eq + 1).trim();
    if (!/^[a-z0-9-]{2,16}$/i.test(code)) continue;
    // Same-origin path or absolute https only — never http (mixed content on
    // the https portal), never javascript:/data: or anything else.
    if (!(url.startsWith("/") && !url.startsWith("//")) && !/^https:\/\/[^\s"'<>]+$/i.test(url)) continue;
    out[code] = url;
  }
  return out;
}

export function regionProbeUrls(
  nodes: { region: string; isPrimary: boolean }[],
  env: string | undefined = process.env.REGION_PROBE_URLS,
): Record<string, string> {
  const explicit = parseRegionProbeUrls(env);
  if (explicit) return explicit;
  const primary = nodes.find((n) => n.isPrimary);
  return primary ? { [primary.region]: "/api/tools/ping" } : {};
}

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { logError } from "../lib/log";
import { upsertMinecraftSubdomainDns, deleteMinecraftSubdomainDns } from "../lib/game-subdomain-dns";
import { gameFamilyForServer } from "./provision-health";
import { joinPortFor, HOSTNAME_CONNECT_FAMILIES, type GameFamily } from "../lib/games";

export type DnsTargetInput = {
  status: string;
  dedicatedIp: { address: string } | null;
  portForwards: { guestPort: number; publicPort: number; protocol: string }[];
  nodePublicIp: string | null | undefined;
  publicIpEnv: string | undefined;
  gamePort: number;
  gameProtocol: "tcp" | "udp";
};

/**
 * Pure resolution of "what ip:port should this server's subdomain point at
 * right now" — no I/O, fully unit-testable. Extracted out of syncGameServerDns
 * so the branching (dedicated vs. NAT-with-forward vs. NAT-without-forward vs.
 * suspended/deleting) can be tested directly.
 *
 * Matches on BOTH guestPort and protocol, not guestPort alone. Several
 * families (cs2/tf2/l4d2/gmod/sdtd — see GAME_JOIN_PORT_OVERRIDE in
 * lib/games.ts) bind the identical port NUMBER for two different services —
 * RCON on tcp, the actual game on udp — so a server can legitimately hold two
 * PortForward rows with the same guestPort and different protocol. Matching
 * on guestPort alone would non-deterministically resolve to whichever forward
 * happens to come first, sometimes handing out the RCON port as the "connect"
 * address — the exact class of bug already found and fixed for the dashboard's
 * raw-IP display 2026-09-06/07 (see joinPortFor's own doc comment). The
 * caller MUST pass the join port+protocol (via `joinPortFor`), not the raw
 * GAME_PORT/health-check port, for the same reason.
 */
export function resolveGameServerDnsTarget(input: DnsTargetInput): { ip: string; port: number } | null {
  if (input.status === "SUSPENDED" || input.status === "DELETING") return null;
  if (input.dedicatedIp) return { ip: input.dedicatedIp.address, port: input.gamePort };
  const forward = input.portForwards.find((f) => f.guestPort === input.gamePort && f.protocol === input.gameProtocol);
  const ip = input.nodePublicIp ?? input.publicIpEnv;
  return forward && ip ? { ip, port: forward.publicPort } : null;
}

/**
 * Single idempotent choke point for keeping a paid Minecraft server's DNS
 * (`<subdomain>.play.nxeon.cloud`, see lib/game-subdomain-dns.ts) in sync with
 * its actual reachable ip:port. Called from every place that can change that
 * ip:port: provision() (dedicated-IP servers only — see below), addPortForward/
 * deletePortForward (NAT servers), and suspend()/unsuspend().
 *
 * Never throws — a DNS hiccup must not fail provisioning, a port-forward save,
 * or a suspend/unsuspend cycle. Callers fire-and-forget via the SYNC_GAME_DNS
 * job (see worker/index.ts) rather than awaiting this inline.
 */
/**
 * Pure: which families get a managed subdomain, and whether it includes an
 * SRV record. Java gets the full A+SRV pair (no port to remember); Bedrock
 * and everything in `HOSTNAME_CONNECT_FAMILIES` (lib/games.ts — the single
 * source of truth shared with checkout/dashboard, so the family list can't
 * drift between call sites) get an A record only — a friendly hostname is
 * the most a subdomain can offer there (see game-subdomain-dns.ts). Every
 * other family either rejects hostnames outright (rust, palworld,
 * spaceengineers, sandstorm, arkasa — confirmed, not assumed) or has no
 * meaningful direct-connect flow at all (server browser/matchmaking only),
 * or is simply unverified. Extracted for the same reason
 * `resolveGameServerDnsTarget` was: fully unit-testable without touching
 * `syncGameServerDns`'s DB/HTTP I/O.
 */
export function dnsSupportForFamily(family: string | null): { managed: false } | { managed: true; includeSrv: boolean } {
  if (family === "minecraft") return { managed: true, includeSrv: true };
  if (family === "bedrock" || (family && HOSTNAME_CONNECT_FAMILIES.has(family as GameFamily))) return { managed: true, includeSrv: false };
  return { managed: false };
}

export async function syncGameServerDns(serverId: string): Promise<void> {
  if (SANDBOX) return;
  try {
    const server = await db.server.findUnique({
      where: { id: serverId },
      include: {
        osTemplate: { select: { family: true } },
        gamePlan: { select: { gameFamily: true } },
        node: { select: { publicIp: true } },
        dedicatedIp: { select: { address: true } },
        portForwards: true,
      },
    });
    if (!server || !server.subdomain) return;

    const familyLike = server as unknown as { gamePlan?: { gameFamily?: string | null } | null; osTemplate?: { family?: string | null } | null };
    const family = gameFamilyForServer(familyLike);
    const support = dnsSupportForFamily(family);
    if (!support.managed) return;
    const includeSrv = support.includeSrv;
    // The JOIN port, not the RCON/health-check GAME_PORT — see this file's own
    // resolveGameServerDnsTarget doc comment for why that distinction matters.
    const join = joinPortFor(family as GameFamily);

    const target = resolveGameServerDnsTarget({
      status: server.status,
      dedicatedIp: server.dedicatedIp,
      portForwards: server.portForwards,
      nodePublicIp: server.node?.publicIp,
      publicIpEnv: process.env.PUBLIC_IP,
      gamePort: join.port,
      gameProtocol: join.protocol,
    });

    if (target) {
      await upsertMinecraftSubdomainDns({ subdomain: server.subdomain, ip: target.ip, port: target.port, includeSrv });
    } else {
      await deleteMinecraftSubdomainDns(server.subdomain);
    }
  } catch (e) {
    logError("game-subdomain-sync", e, { serverId });
  }
}
  return String(process.env.CLOUDFLARE_DNS_API_TOKEN ?? "").trim();
}

async function zoneId(): Promise<string | null> {
  if (cachedZoneId !== undefined) return cachedZoneId;
  cachedZoneId = await cfFindZoneId(token(), "nxeon.cloud");
  return cachedZoneId;
}

/** The shared base domain both free and paid Minecraft subdomains live under. */
export async function gameSubdomainBase(): Promise<string> {
  return getSetting("free_minecraft_domain", "play.nxeon.cloud");
}

type SrvRecord = { id: string; type: string; name: string; data?: { priority: number; weight: number; port: number; target: string } };

async function upsertA(zone: string, name: string, ip: string): Promise<void> {
  const existing = await cfRequest<{ id: string }[]>(token(), "GET", `/zones/${zone}/dns_records?type=A&name=${encodeURIComponent(name)}&per_page=5`);
  const body = { type: "A", name, content: ip, ttl: 1, proxied: false };
  if (existing[0]) {
    await cfRequest(token(), "PUT", `/zones/${zone}/dns_records/${existing[0].id}`, body);
  } else {
    await cfRequest(token(), "POST", `/zones/${zone}/dns_records`, body);
  }
}

/**
 * `host` is the bare `<subdomain>.<base>` name. Confirmed live against the
 * Cloudflare API (2026-08-30, throwaway test record, deleted immediately
 * after): unlike A/MX/TXT, Cloudflare wants the FULL prefixed name
 * (`_minecraft._tcp.<host>`) as the top-level `name`, with `data` holding
 * ONLY `{priority, weight, port, target}` — `service`/`proto`/`name` inside
 * `data` (a shape that's floated around in various docs/examples) is
 * REJECTED with "DNS name is invalid" (code 9000). `target` is the A
 * record's own name (`host`), matching the pattern established above.
 */
async function upsertSrv(zone: string, host: string, target: string, port: number): Promise<void> {
  const srvName = `_minecraft._tcp.${host}`;
  const existing = await cfRequest<SrvRecord[]>(token(), "GET", `/zones/${zone}/dns_records?type=SRV&name=${encodeURIComponent(srvName)}&per_page=5`);
  const body = { type: "SRV", name: srvName, data: { priority: 0, weight: 5, port, target } };
  if (existing[0]) {
    await cfRequest(token(), "PUT", `/zones/${zone}/dns_records/${existing[0].id}`, body);
  } else {
    await cfRequest(token(), "POST", `/zones/${zone}/dns_records`, body);
  }
}

/**
 * Create or update the A record (and, for Java, the SRV record too) for
 * `<subdomain>.<base>` -> `ip:port`. Silent no-op if the platform Cloudflare
 * token isn't configured.
 *
 * `includeSrv` defaults true (every existing Java caller is unaffected).
 * Bedrock Edition has NO SRV support at all — confirmed against Bedrock's own
 * protocol behavior 2026-09-08, unchanged for years and not a Nxeon gap: a
 * Bedrock client never performs the `_minecraft._tcp` SRV lookup Java does,
 * so publishing one for a Bedrock server would just be a dead record. Bedrock
 * players still get a friendly `<subdomain>.<base>` hostname via the A
 * record — they just have to type the port alongside it, same as they would
 * for any host that isn't on Bedrock's (nonexistent) default-port lookup.
 */
export async function upsertMinecraftSubdomainDns(
  opts: { subdomain: string; ip: string; port: number; includeSrv?: boolean },
): Promise<void> {
  if (!token()) return;
  const zone = await zoneId();
  if (!zone) return;
  const base = await gameSubdomainBase();
  const host = `${opts.subdomain}.${base}`;
  await upsertA(zone, host, opts.ip);
  if (opts.includeSrv ?? true) await upsertSrv(zone, host, host, opts.port);
}

/**
 * Delete both records for `<subdomain>.<base>`, if present. Idempotent —
 * tolerant of records already missing (nothing to clean up).
 */
export async function deleteMinecraftSubdomainDns(subdomain: string): Promise<void> {
