/**
 * "Diagnose server" — the PURE half: facts in, verdict + ranked probable
 * causes + one-click fixes out. No I/O at all, so every rule below is covered
 * by test/admin-ops-diagnose.test.ts.
 *
 * worker/admin-ops.ts gathers the facts (DB, Proxmox, node NAT chain, guest
 * over SSH, an external probe, public DNS) — the exact checks a human or an
 * AI session used to run by hand for every "customer can't connect" ticket —
 * and this module turns them into the same conclusion that session would
 * reach. A fact that could not be gathered is `null` ("unknown"), never
 * `false`: an unreachable guest must never be reported as "service down".
 */

export type CheckStatus = "ok" | "warn" | "fail" | "skip";

export type DiagnosisCheck = {
  key: string;
  label: string;
  status: CheckStatus;
  detail: string;
};

/** One-click remedies the UI can offer. Each maps to an existing, audited path. */
export type FixKey =
  | "start_vm"
  | "reboot_vm"
  | "reconcile_status"
  | "restart_game_service"
  | "sync_forwards"
  | "sync_game_dns"
  | "retry_provision"
  | "clear_stuck_job"
  | "open_guest_logs";

export const FIX_LABELS: Record<FixKey, string> = {
  start_vm: "Start the VM",
  reboot_vm: "Reboot the VM",
  reconcile_status: "Reconcile DB status from Proxmox",
  restart_game_service: "Restart the game service",
  sync_forwards: "Re-sync NAT port forwards",
  sync_game_dns: "Re-sync subdomain DNS (A/SRV)",
  retry_provision: "Retry provisioning",
  clear_stuck_job: "Open the job queue (stuck job)",
  open_guest_logs: "Tail the game/guest logs",
};

export type ProbableCause = {
  key: string;
  title: string;
  /** 0-100. Ranking key — highest first. */
  confidence: number;
  evidence: string[];
  fixes: FixKey[];
  /** True when the fix is on the CUSTOMER's side (their domain, their client). */
  customerSide?: boolean;
};

export type Verdict = "healthy" | "degraded" | "down" | "unknown";

export type DiagnosisFacts = {
  sandbox: boolean;
  server: {
    id: string;
    hostname: string;
    status: string;
    vmid: number | null;
    isGame: boolean;
    gameFamily: string | null;
    provisionError: string | null;
    provisioningStep: string | null;
    ipAddress: string | null;
    sshPort: number | null;
    dedicatedIp: string | null;
    /** Public address customers connect to (dedicated IP or node public IP). */
    publicHost: string | null;
  };
  node: {
    name: string | null;
    /** Proxmox API answered. null = not attempted. */
    apiReachable: boolean | null;
    cpuPct: number | null;
    memPct: number | null;
  };
  vm: {
    /** Proxmox status string: running | stopped | paused | ... ; null = unknown. */
    pveStatus: string | null;
    /** True if the VM exists on the recorded node; false = 404 there; null = unknown. */
    existsOnNode: boolean | null;
    agentResponding: boolean | null;
    /** ipconfig0's address part (e.g. 10.20.3.120). */
    configuredIp: string | null;
    memPct: number | null;
    cpuPct: number | null;
    uptimeSec: number | null;
  };
  guest: {
    sshReachable: boolean | null;
    sshError: string | null;
    diskPct: number | null;
    memPct: number | null;
    load1: number | null;
    cpuCount: number | null;
    failedUnits: string[] | null;
    oomKillsRecent: number | null;
    serviceUnit: string | null;
    /** systemctl is-active of the game unit. */
    serviceState: string | null;
    /** Docker container restart count, when the family runs in docker. */
    containerRestarts: number | null;
    /** Is the game JOIN port bound inside the guest (any netns)? */
    portBound: boolean | null;
    /** Interesting log lines (errors/exceptions) from the game unit. */
    logHighlights: string[];
  };
  network: {
    /** NAT server: the expected DNAT rules, rendered (e.g. "tcp/20005->10.20.0.12:22"). */
    expectedRules: string[];
    /** Of those, which are missing from the node's chain. null = could not read the chain. */
    missingRules: string[] | null;
    /** NAT game server: does a PortForward row exist for the join port? */
    joinForwardConfigured: boolean | null;
    /** The ip:port a player/customer should connect to, if we can compute it. */
    connectAddress: string | null;
    joinProtocol: "tcp" | "udp" | null;
  };
  external: {
    /** SSH banner seen on the public address from the worker host. */
    sshOpen: boolean | null;
    /** Game join port reachable on the public address. */
    gamePortOpen: boolean | null;
    gamePortError: string | null;
    /** True when the probe source is the SAME box as the target (hairpin, weaker evidence). */
    hairpin: boolean;
  };
  dns: {
    /** Managed subdomain FQDN, if the server has one. */
    subdomainHost: string | null;
    expectedA: string | null;
    actualA: string[] | null;
    expectedSrvPort: number | null;
    actualSrvPort: number | null;
    customDomain: string | null;
    customDomainA: string[] | null;
  };
  jobs: {
    /** In-flight job, if any. */
    active: { id: string; type: string; status: string; ageMin: number } | null;
    /** Most recent FAILED jobs (newest first). */
    recentFailures: { id: string; type: string; error: string; ageMin: number }[];
  };
};

export type DiagnosisResult = {
  verdict: Verdict;
  headline: string;
  checks: DiagnosisCheck[];
  causes: ProbableCause[];
  connectAddress: string | null;
  generatedAt: string;
  sandbox: boolean;
};

/** A job running/queued this long is treated as wedged. */
export const STUCK_JOB_MIN = 30;
export const HIGH_PCT = 92;

const pct = (n: number | null) => (n == null ? "?" : `${Math.round(n)}%`);

function arrEq(a: string[] | null, want: string | null): boolean | null {
  if (!want || a == null) return null;
  return a.length > 0 && a.every((x) => x === want);
}

export function evaluateDiagnosis(f: DiagnosisFacts, now: Date = new Date()): DiagnosisResult {
  const checks: DiagnosisCheck[] = [];
  const causes: ProbableCause[] = [];
  const s = f.server;
  const add = (key: string, label: string, status: CheckStatus, detail: string) =>
    checks.push({ key, label, status, detail });
  const cause = (c: ProbableCause) => causes.push(c);

  // ---- DB / lifecycle -----------------------------------------------------
  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status);
  add(
    "db_status",
    "Platform status",
    s.status === "RUNNING" ? "ok" : s.status === "ERROR" || s.status === "SUSPENDED" ? "fail" : "warn",
    `DB status ${s.status}${s.provisioningStep ? ` — step: ${s.provisioningStep}` : ""}`,
  );
  if (s.status === "SUSPENDED") {
    cause({
      key: "suspended",
      title: "Server is suspended",
      confidence: 98,
      evidence: ["Server.status = SUSPENDED (unpaid or admin hold) — the VM is stopped by design."],
      fixes: [],
    });
  }
  if (s.provisionError) {
    cause({
      key: "provision_error",
      title: "Provisioning reported an error",
      confidence: s.status === "ERROR" ? 85 : 50,
      evidence: [s.provisionError.slice(0, 300)],
      fixes: f.vm.pveStatus === "running" ? ["reconcile_status"] : ["retry_provision"],
    });
  }

  // ---- Jobs ----------------------------------------------------------------
  const aj = f.jobs.active;
  if (aj) {
    const stuck = aj.ageMin >= STUCK_JOB_MIN;
    add("jobs_active", "In-flight job", stuck ? "fail" : "warn", `${aj.type} ${aj.status.toLowerCase()} for ${aj.ageMin} min`);
    if (stuck) {
      cause({
        key: "stuck_job",
        title: `A ${aj.type} job has been ${aj.status.toLowerCase()} for ${aj.ageMin} minutes`,
        confidence: 80,
        evidence: [
          `Job ${aj.id} is still ${aj.status}. Every other action on this server (power, config, IP) waits behind it.`,
        ],
        fixes: ["clear_stuck_job"],
      });
    }
  } else {
    add("jobs_active", "In-flight job", "ok", "None");
  }
  if (f.jobs.recentFailures.length) {
    const j = f.jobs.recentFailures[0];
    add("jobs_failed", "Recent failed jobs", "warn", `${f.jobs.recentFailures.length} — latest ${j.type} ${j.ageMin} min ago: ${j.error.slice(0, 140)}`);
  } else {
    add("jobs_failed", "Recent failed jobs", "ok", "None in the last 7 days");
  }

  // ---- Node ------------------------------------------------------------------
  if (f.node.apiReachable === false) {
    add("node_api", "Node API", "fail", `${f.node.name ?? "node"} Proxmox API did not answer`);
    cause({
      key: "node_down",
      title: `Node ${f.node.name ?? ""} is unreachable`,
      confidence: 90,
      evidence: ["The Proxmox API on the owning node did not respond — every server on it is likely affected."],
      fixes: [],
    });
  } else if (f.node.apiReachable) {
    const hot = (f.node.memPct ?? 0) >= HIGH_PCT || (f.node.cpuPct ?? 0) >= HIGH_PCT;
    add("node_api", "Node health", hot ? "warn" : "ok", `${f.node.name}: CPU ${pct(f.node.cpuPct)} · RAM ${pct(f.node.memPct)}`);
    if (hot) {
      cause({
        key: "node_hot",
        title: `Node ${f.node.name} is under heavy load`,
        confidence: 45,
        evidence: [`Host CPU ${pct(f.node.cpuPct)}, RAM ${pct(f.node.memPct)} — guests may be starved (lag, timeouts).`],
        fixes: [],
      });
    }
  } else {
    add("node_api", "Node health", "skip", "Not checked");
  }

  // ---- VM --------------------------------------------------------------------
  if (s.vmid == null) {
    add("vm", "VM", transitional ? "warn" : "fail", "No VM id recorded yet");
    if (!transitional && s.status !== "SUSPENDED") {
      cause({
        key: "no_vm",
        title: "No VM was ever created for this server",
        confidence: 85,
        evidence: ["Server.vmid is empty while the server is not provisioning."],
        fixes: ["retry_provision"],
      });
    }
  } else if (f.vm.existsOnNode === false) {
    add("vm", "VM", "fail", `vmid ${s.vmid} not found on ${f.node.name ?? "its node"}`);
    cause({
      key: "vm_missing",
      title: `VM ${s.vmid} does not exist on ${f.node.name ?? "the recorded node"}`,
      confidence: 92,
      evidence: ["Proxmox returned no such VM on the node the database points at — deleted, or recorded against the wrong node (run Drift scan)."],
      fixes: [],
    });
  } else if (f.vm.pveStatus) {
    const running = f.vm.pveStatus === "running";
    add("vm", "VM power", running ? "ok" : "fail", `Proxmox: ${f.vm.pveStatus}${f.vm.uptimeSec != null ? ` · up ${Math.round(f.vm.uptimeSec / 60)} min` : ""}`);
    if (!running && s.status !== "SUSPENDED" && !transitional) {
      cause({
        key: "vm_off",
        title: "The VM is not running",
        confidence: 95,
        evidence: [`Proxmox reports "${f.vm.pveStatus}" while the platform shows ${s.status}.`],
        fixes: s.status === "STOPPED" ? ["start_vm"] : ["start_vm", "reconcile_status"],
      });
    }
    if (running && (s.status === "ERROR" || s.status === "STOPPED")) {
      cause({
        key: "status_stale",
        title: `Platform status ${s.status} is stale — the VM is actually running`,
        confidence: 75,
        evidence: ["Proxmox says running; the DB row disagrees, so the dashboard shows the wrong state and power buttons misbehave."],
        fixes: ["reconcile_status"],
      });
    }
  } else {
    add("vm", "VM power", "skip", "Not checked");
  }

  if (f.vm.pveStatus === "running") {
    if (f.vm.agentResponding === false) {
      add("agent", "Guest agent", "warn", "qemu-guest-agent not answering");
    } else if (f.vm.agentResponding) {
      add("agent", "Guest agent", "ok", "Responding");
    }
    if (f.vm.configuredIp && s.ipAddress && f.vm.configuredIp !== s.ipAddress) {
      add("vm_ip", "VM network config", "fail", `ipconfig0 has ${f.vm.configuredIp}, DB has ${s.ipAddress}`);
      cause({
        key: "ip_drift",
        title: "VM network config does not match the platform's record",
        confidence: 88,
        evidence: [
          `Proxmox ipconfig0 = ${f.vm.configuredIp}, Server.ipAddress = ${s.ipAddress}. Forwards and DNS are built from the DB value, so traffic goes to an address the VM doesn't hold.`,
        ],
        fixes: [],
      });
    } else if (f.vm.configuredIp) {
      add("vm_ip", "VM network config", "ok", `ipconfig0 ${f.vm.configuredIp}`);
    }
  }

  // ---- Guest -----------------------------------------------------------------
  const g = f.guest;
  if (g.sshReachable === false) {
    add("guest_ssh", "Guest SSH (platform)", "fail", g.sshError ?? "Could not log in");
    if (f.vm.pveStatus === "running") {
      const hung = f.vm.agentResponding === false;
      cause({
        key: hung ? "guest_hung" : "guest_ssh_fail",
        title: hung ? "Guest OS is hung or still booting" : "Platform cannot log into the guest",
        confidence: hung ? 80 : 55,
        evidence: [
          `SSH from the platform failed: ${g.sshError ?? "unknown error"}.`,
          hung ? "The guest agent is not answering either — the OS itself is unresponsive." : "The guest agent answers, so the OS is up: likely sshd stopped, a changed root password/key, or a guest firewall.",
        ],
        fixes: hung ? ["reboot_vm"] : [],
      });
    }
  } else if (g.sshReachable) {
    add("guest_ssh", "Guest SSH (platform)", "ok", "Logged in");
  }

  if (g.diskPct != null) {
    const full = g.diskPct >= 95;
    add("guest_disk", "Guest disk", full ? "fail" : g.diskPct >= 85 ? "warn" : "ok", `/ ${pct(g.diskPct)} used`);
    if (full) {
      cause({
        key: "disk_full",
        title: "Guest disk is full",
        confidence: 82,
        evidence: [`Root filesystem at ${pct(g.diskPct)} — games fail to save/start and services crash when the disk fills.`],
        fixes: ["open_guest_logs"],
      });
    }
  }
  const memPct = g.memPct ?? f.vm.memPct;
  if (memPct != null) {
    const oom = (g.oomKillsRecent ?? 0) > 0;
    add("guest_mem", "Guest memory", memPct >= 97 || oom ? "fail" : memPct >= HIGH_PCT ? "warn" : "ok", `${pct(memPct)} used${oom ? ` · ${g.oomKillsRecent} OOM kill(s) in 24h` : ""}`);
    if (oom) {
      cause({
        key: "oom",
        title: "The guest is running out of memory (OOM kills)",
        confidence: 78,
        evidence: [`Kernel log shows ${g.oomKillsRecent} out-of-memory kill(s) in the last 24h; RAM ${pct(memPct)}.`],
        fixes: s.isGame ? ["restart_game_service", "open_guest_logs"] : ["open_guest_logs"],
      });
    }
  }
  if (g.load1 != null && g.cpuCount) {
    const ratio = g.load1 / g.cpuCount;
    add("guest_load", "Guest load", ratio >= 2 ? "warn" : "ok", `load ${g.load1.toFixed(2)} on ${g.cpuCount} vCPU`);
  }
  if (g.failedUnits && g.failedUnits.length) {
    add("guest_units", "Failed systemd units", "warn", g.failedUnits.slice(0, 6).join(", "));
  } else if (g.failedUnits) {
    add("guest_units", "Failed systemd units", "ok", "None");
  }

  // ---- Game service ----------------------------------------------------------
  if (s.isGame) {
    if (g.serviceState) {
      const active = g.serviceState === "active";
      const looping = (g.containerRestarts ?? 0) >= 3;
      add(
        "game_service",
        "Game service",
        active && !looping ? "ok" : "fail",
        `${g.serviceUnit ?? "unit"} is ${g.serviceState}${g.containerRestarts != null ? ` · container restarts ${g.containerRestarts}` : ""}`,
      );
      if (!active) {
        cause({
          key: "game_service_down",
          title: `The game service is ${g.serviceState}`,
          confidence: 90,
          evidence: [
            `systemctl reports ${g.serviceUnit ?? "the game unit"} as "${g.serviceState}".`,
            ...g.logHighlights.slice(0, 3),
          ],
          fixes: ["restart_game_service", "open_guest_logs"],
        });
      } else if (looping) {
        cause({
          key: "game_crash_loop",
          title: "The game container is crash-looping",
          confidence: 85,
          evidence: [
            `The unit is "active" but the container has restarted ${g.containerRestarts} times — systemd's Restart=always hides the crash.`,
            ...g.logHighlights.slice(0, 3),
          ],
          fixes: ["open_guest_logs", "restart_game_service"],
        });
      }
    } else if (g.sshReachable) {
      add("game_service", "Game service", "warn", "No game unit found in the guest");
      cause({
        key: "game_unit_missing",
        title: "No game service is installed in the guest",
        confidence: 60,
        evidence: ["None of the family's systemd unit names resolve — the setup script may never have finished."],
        fixes: ["open_guest_logs"],
      });
    }

    if (g.portBound === false && g.serviceState === "active") {
      add("game_port_bound", "Game port bound in guest", "fail", `Nothing listening on ${f.network.joinProtocol ?? ""} join port`);
      cause({
        key: "game_not_listening",
        title: "The game process isn't listening on its port",
        confidence: 72,
        evidence: [
          "The service is active but no socket is bound to the join port — still loading a world, or crashed inside its wrapper.",
          ...g.logHighlights.slice(0, 3),
        ],
        fixes: ["open_guest_logs", "restart_game_service"],
      });
    } else if (g.portBound) {
      add("game_port_bound", "Game port bound in guest", "ok", "Listening");
    }
  }

  // ---- NAT / forwarding --------------------------------------------------------
  const n = f.network;
  if (!s.dedicatedIp) {
    if (n.missingRules == null) {
      add("nat", "NAT rules on node", "skip", n.expectedRules.length ? "Could not read the node's chain" : "No forwards expected");
    } else if (n.missingRules.length) {
      add("nat", "NAT rules on node", "fail", `${n.missingRules.length} missing: ${n.missingRules.slice(0, 4).join(", ")}`);
      cause({
        key: "nat_missing",
        title: "Port-forward rules are missing on the node",
        confidence: 90,
        evidence: [`Expected DNAT rule(s) not in the node's chain: ${n.missingRules.slice(0, 6).join(", ")}.`],
        fixes: ["sync_forwards"],
      });
    } else {
      add("nat", "NAT rules on node", "ok", `${n.expectedRules.length} rule(s) present`);
    }
    if (s.isGame && n.joinForwardConfigured === false) {
      add("join_forward", "Game port forward", "fail", "No PortForward row for the game's join port");
      cause({
        key: "no_join_forward",
        title: "The game's join port is not forwarded",
        confidence: 86,
        evidence: ["This NAT game server has no PortForward for its join port, so players have nothing to connect to."],
        fixes: [],
      });
    }
  } else {
    add("nat", "NAT rules on node", "skip", `Dedicated IP ${s.dedicatedIp} — no NAT involved`);
  }

  // ---- External reachability ----------------------------------------------------
  const x = f.external;
  const hairpinNote = x.hairpin ? " (probed from the same host — hairpin, weaker evidence)" : "";
  if (x.sshOpen != null) add("ext_ssh", "SSH reachable from outside", x.sshOpen ? "ok" : "fail", (x.sshOpen ? "Banner received" : "No SSH banner") + hairpinNote);
  if (s.isGame && x.gamePortOpen != null) {
    add("ext_game", "Game port reachable from outside", x.gamePortOpen ? "ok" : "fail", (x.gamePortOpen ? `Open at ${n.connectAddress ?? "?"}` : x.gamePortError ?? "Closed") + hairpinNote);
    const alreadyExplained = causes.some((c) =>
      ["vm_off", "game_service_down", "game_crash_loop", "game_not_listening", "nat_missing", "no_join_forward", "guest_hung", "node_down", "suspended", "ip_drift"].includes(c.key),
    );
    if (!x.gamePortOpen && !alreadyExplained && g.portBound) {
      cause({
        key: "blocked_path",
        title: "Game is listening but unreachable from outside",
        confidence: 62,
        evidence: [
          "The port is bound in the guest and the DNAT rule exists, yet the outside probe fails — check the server's firewall rules, the guest firewall (ufw/iptables), or a FORWARD-chain drop on the node.",
        ],
        fixes: ["sync_forwards"],
      });
    }
  }

  // ---- DNS ------------------------------------------------------------------------
  const d = f.dns;
  if (d.subdomainHost) {
    const aOk = arrEq(d.actualA, d.expectedA);
    const srvOk = d.expectedSrvPort == null ? true : d.actualSrvPort === d.expectedSrvPort;
    const status: CheckStatus = aOk === null ? "skip" : aOk && srvOk ? "ok" : "fail";
    add(
      "dns_sub",
      "Subdomain DNS",
      status,
      `${d.subdomainHost} → A ${d.actualA?.join(", ") || "none"} (want ${d.expectedA ?? "?"})` +
        (d.expectedSrvPort != null ? ` · SRV port ${d.actualSrvPort ?? "none"} (want ${d.expectedSrvPort})` : ""),
    );
    if (status === "fail") {
      cause({
        key: "dns_wrong",
        title: "The server's subdomain points at the wrong address",
        confidence: 80,
        evidence: [`Public DNS for ${d.subdomainHost} does not match the server's current ip:port.`],
        fixes: ["sync_game_dns"],
      });
    }
  }
  if (d.customDomain) {
    const want = s.dedicatedIp ?? s.publicHost;
    const ok = arrEq(d.customDomainA, want);
    add("dns_custom", "Customer's own domain", ok === null ? "skip" : ok ? "ok" : "warn", `${d.customDomain} → ${d.customDomainA?.join(", ") || "no A record"} (want ${want ?? "?"})`);
    if (ok === false) {
      cause({
        key: "custom_domain_wrong",
        title: "The customer's own domain doesn't point at this server",
        confidence: 65,
        evidence: [`${d.customDomain} resolves to ${d.customDomainA?.join(", ") || "nothing"}; it should be ${want}.${s.dedicatedIp ? "" : " (Without a dedicated IP the domain alone can't carry the port — an SRV record or ip:port is required.)"}`],
        fixes: [],
        customerSide: true,
      });
    }
  }

  // ---- Verdict --------------------------------------------------------------------
  causes.sort((a, b) => b.confidence - a.confidence);
  const fails = checks.filter((c) => c.status === "fail").length;
  const warns = checks.filter((c) => c.status === "warn").length;
  const reachable = s.isGame ? x.gamePortOpen : x.sshOpen;
  let verdict: Verdict;
  if (f.sandbox && fails === 0 && warns === 0 && causes.length === 0) verdict = "healthy";
  else if (causes.some((c) => c.confidence >= 85 && !c.customerSide) || reachable === false) verdict = "down";
  else if (fails > 0 || warns > 0 || causes.length) verdict = "degraded";
  else if (reachable === true) verdict = "healthy";
  else verdict = "unknown";

  let headline: string;
  if (verdict === "healthy") {
    headline = n.connectAddress
      ? `Healthy and reachable at ${n.connectAddress}. If the customer still can't connect, it's client-side: wrong address/port, game version or mods mismatch, or their network.`
      : "Healthy — every check passed.";
  } else if (causes[0]) {
    headline = causes[0].title;
  } else if (verdict === "unknown") {
    headline = "Not enough could be checked to reach a verdict — see the skipped checks.";
  } else {
    headline = "Some checks are not clean — see below.";
  }

  return {
    verdict,
    headline,
    checks,
    causes,
    connectAddress: n.connectAddress,
    generatedAt: now.toISOString(),
    sandbox: f.sandbox,
  };
}

/**
 * Pick the interesting lines out of a log tail: errors, exceptions, Java
 * version mismatches, port-in-use, crash markers. Bounded and de-duplicated.
 */
export function logHighlights(lines: string[], max = 6): string[] {
  const re = /(error|exception|fatal|failed|crash|unsupportedclassversion|address already in use|out of memory|oom|segfault|panic|could not|cannot|denied|missing)/i;
  const out: string[] = [];
  const seen = new Set<string>();
  for (let i = lines.length - 1; i >= 0 && out.length < max; i--) {
    const l = lines[i].trim();
    if (!l || !re.test(l)) continue;
    const key = l.replace(/^\S+\s+\S+\s+\S+\s+/, "").slice(0, 160);
    if (seen.has(key)) continue;
    seen.add(key);
    out.unshift(l.slice(0, 240));
  }
  return out;
}

/** Parse `ipconfig0` ("ip=10.20.0.5/24,gw=10.20.0.1") → "10.20.0.5". */
export function ipFromIpconfig(ipconfig0: unknown): string | null {
  const m = /(?:^|,)ip=(\d{1,3}(?:\.\d{1,3}){3})\//.exec(String(ipconfig0 ?? ""));
  return m ? m[1] : null;
}

