/**
 * The WHITELISTED guest diagnostic command set for the Admin Ops console.
 *
 * This is deliberately NOT a shell. An admin picks a command KEY; the only
 * values that can vary are typed parameters, each validated against a
 * shell-inert allowlist (lib/ssh-exec.ts's discipline: reject, never
 * sanitize) and then single-quoted anyway. Every command is read-only —
 * nothing here writes, restarts, installs or deletes. Restarting a game
 * service goes through the existing GAME_POWER job instead.
 *
 * Pure (no I/O) so test/admin-ops-guest-commands.test.ts can prove every
 * builder rejects hostile input.
 */
import { SERVICE_RE, PATH_RE, shellQuote } from "../ssh-exec";

export type GuestParamSpec = {
  name: string;
  label: string;
  kind: "lines" | "unit" | "container" | "path";
  /** Default used when the param is omitted. */
  default?: string | number;
  optional?: boolean;
};

export type GuestCommand = {
  key: string;
  label: string;
  description: string;
  params: GuestParamSpec[];
  /** Seconds before the remote command is cut off. */
  timeoutSec: number;
  build: (p: Record<string, string>) => string;
};

/** docker container name: same charset docker itself allows. */
export const CONTAINER_RE = /^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,63}$/;
export const LINES_MIN = 10;
export const LINES_MAX = 500;
/** Every command's output is capped at this many bytes before it is stored. */
export const OUTPUT_CAP_BYTES = 64 * 1024;

function lines(raw: string | undefined, def = 100): number {
  const n = Number(raw ?? def);
  if (!Number.isInteger(n)) throw new Error("lines must be a whole number");
  return Math.min(Math.max(n, LINES_MIN), LINES_MAX);
}

function unit(raw: string | undefined): string {
  const v = String(raw ?? "");
  if (!SERVICE_RE.test(v)) throw new Error(`Unsupported unit name: ${v.slice(0, 40)}`);
  return v;
}

function container(raw: string | undefined): string {
  const v = String(raw ?? "");
  if (!CONTAINER_RE.test(v)) throw new Error(`Unsupported container name: ${v.slice(0, 40)}`);
  return v;
}

function path(raw: string | undefined, def: string): string {
  const v = String(raw ?? def);
  if (!PATH_RE.test(v) || v.includes("..") || v.includes("//")) throw new Error(`Unsupported path: ${v.slice(0, 60)}`);
  return v;
}

const T = 20;

export const GUEST_COMMANDS: GuestCommand[] = [
  {
    key: "overview",
    label: "System overview",
    description: "uptime, load, kernel, memory and root disk in one shot",
    params: [],
    timeoutSec: T,
    build: () => "uptime; echo; uname -srm; echo; free -m; echo; df -hT / 2>/dev/null",
  },
  {
    key: "disk",
    label: "Disk usage",
    description: "All real filesystems (tmpfs hidden)",
    params: [],
    timeoutSec: T,
    build: () => "df -hT -x tmpfs -x devtmpfs -x squashfs -x overlay 2>/dev/null",
  },
  {
    key: "largest_files",
    label: "Largest files",
    description: "The 25 biggest files over 50 MB under a path (same filesystem only)",
    params: [{ name: "path", label: "Path", kind: "path", default: "/" }],
    timeoutSec: 60,
    build: (p) =>
      `find ${shellQuote(path(p.path, "/"))} -xdev -type f -size +50M -printf '%s\\t%p\\n' 2>/dev/null | sort -nr | head -25 | awk -F'\\t' '{printf "%8.1f MB  %s\\n", $1/1048576, $2}'`,
  },
  {
    key: "top_cpu",
    label: "Top processes (CPU)",
    description: "15 busiest processes by CPU",
    params: [],
    timeoutSec: T,
    build: () => "ps -eo pid,user,pcpu,pmem,rss,etime,comm --sort=-pcpu | head -16",
  },
  {
    key: "top_mem",
    label: "Top processes (RAM)",
    description: "15 biggest processes by resident memory",
    params: [],
    timeoutSec: T,
    build: () => "ps -eo pid,user,pcpu,pmem,rss,etime,comm --sort=-rss | head -16",
  },
  {
    key: "listening",
    label: "Listening sockets",
    description: "Every TCP/UDP socket in LISTEN/bound state, with owning process",
    params: [],
    timeoutSec: T,
    build: () => "ss -lntup 2>/dev/null || netstat -lntup 2>/dev/null",
  },
  {
    key: "failed_units",
    label: "Failed services",
    description: "systemd units in the failed state",
    params: [],
    timeoutSec: T,
    build: () => "systemctl --failed --no-legend --no-pager 2>/dev/null; echo; systemctl is-system-running 2>/dev/null",
  },
  {
    key: "unit_status",
    label: "Service status",
    description: "systemctl status for one unit",
    params: [{ name: "unit", label: "Unit", kind: "unit" }],
    timeoutSec: T,
    build: (p) => `systemctl status ${shellQuote(unit(p.unit))} --no-pager -l 2>&1 | head -60`,
  },
  {
    key: "journal_unit",
    label: "Service journal",
    description: "Last N journal lines for one unit",
    params: [
      { name: "unit", label: "Unit", kind: "unit" },
      { name: "lines", label: "Lines", kind: "lines", default: 150 },
    ],
    timeoutSec: T,
    build: (p) => `journalctl -u ${shellQuote(unit(p.unit))} -n ${lines(p.lines, 150)} --no-pager 2>&1`,
  },
  {
    key: "docker_ps",
    label: "Containers",
    description: "All docker containers with status and restart count",
    params: [],
    timeoutSec: T,
    build: () =>
      `docker ps -a --format '{{.Names}}\\t{{.Status}}\\t{{.Image}}' 2>&1; echo; for c in $(docker ps -aq 2>/dev/null); do docker inspect -f '{{.Name}} restarts={{.RestartCount}} oom={{.State.OOMKilled}} exit={{.State.ExitCode}}' "$c" 2>/dev/null; done`,
  },
  {
    key: "docker_logs",
    label: "Container logs",
    description: "Last N lines from one docker container",
    params: [
      { name: "container", label: "Container", kind: "container" },
      { name: "lines", label: "Lines", kind: "lines", default: 150 },
    ],
    timeoutSec: T,
    build: (p) => `docker logs --tail ${lines(p.lines, 150)} ${shellQuote(container(p.container))} 2>&1`,
  },
  {
    key: "kernel_oom",
    label: "OOM kills (24h)",
    description: "Kernel out-of-memory kills in the last day",
    params: [],
    timeoutSec: T,
    build: () =>
      "journalctl -k --since '-24h' --no-pager 2>/dev/null | grep -iE 'out of memory|oom-kill|killed process' | tail -30; echo \"total: $(journalctl -k --since '-24h' --no-pager 2>/dev/null | grep -ciE 'oom-kill|killed process')\"",
  },
  {
    key: "network",
    label: "Network config",
    description: "Addresses, routes, resolver and gateway reachability",
    params: [],
    timeoutSec: 30,
    build: () =>
      "ip -br addr; echo; ip route; echo; cat /etc/resolv.conf 2>/dev/null | grep -v '^#'; echo; gw=$(ip route | awk '/default/ {print $3; exit}'); [ -n \"$gw\" ] && ping -c 3 -W 2 \"$gw\" 2>&1 | tail -3; echo; getent hosts nxeon.cloud || echo 'DNS resolution FAILED'",
  },
  {
    key: "guest_firewall",
    label: "Guest firewall",
    description: "ufw / iptables / nftables rules inside the guest (read-only)",
    params: [],
    timeoutSec: T,
    build: () =>
      "command -v ufw >/dev/null && ufw status verbose 2>&1; echo; iptables -S 2>/dev/null | head -80; echo; nft list ruleset 2>/dev/null | head -120",
  },
  {
    key: "cloud_init",
    label: "cloud-init status",
    description: "Did first-boot setup finish? Last lines of its output log",
    params: [],
    timeoutSec: T,
    build: () => "cloud-init status --long 2>&1; echo; tail -n 40 /var/log/cloud-init-output.log 2>/dev/null",
  },
  {
    key: "sshd",
    label: "SSH daemon",
    description: "sshd state, listening port and recent auth failures",
    params: [],
    timeoutSec: T,
    build: () =>
      "systemctl is-active ssh sshd 2>/dev/null; ss -lntp 2>/dev/null | grep -E 'sshd|:22 '; echo; journalctl -u ssh -u sshd -n 30 --no-pager 2>/dev/null | tail -30",
  },
];

const BY_KEY = new Map(GUEST_COMMANDS.map((c) => [c.key, c]));

export function guestCommand(key: string): GuestCommand | null {
  return BY_KEY.get(key) ?? null;
}

/**
 * Validate + render a command. Throws on an unknown key or any parameter that
 * fails its allowlist. The returned string contains only fixed text plus
 * allowlisted, single-quoted values.
 */
export function buildGuestCommand(key: string, params: Record<string, unknown> = {}): { command: GuestCommand; script: string } {
  const command = guestCommand(key);
  if (!command) throw new Error(`Unknown diagnostic command: ${String(key).slice(0, 40)}`);
  const clean: Record<string, string> = {};
  for (const spec of command.params) {
    const raw = params[spec.name];
    if (raw == null || raw === "") {
      if (spec.default == null && !spec.optional) throw new Error(`${spec.label} is required`);
      if (spec.default != null) clean[spec.name] = String(spec.default);
      continue;
    }
    if (typeof raw !== "string" && typeof raw !== "number") throw new Error(`${spec.label} has an invalid value`);
    clean[spec.name] = String(raw);
  }
  for (const k of Object.keys(params)) {
    if (!command.params.some((p) => p.name === k)) throw new Error(`Unexpected parameter: ${k.slice(0, 30)}`);
  }
  return { command, script: command.build(clean) };
}

/** Cap + scrub captured output before it is persisted to the job row. */
export function capOutput(s: string, secrets: (string | null | undefined)[] = []): { text: string; truncated: boolean } {
  let text = String(s ?? "");
  for (const sec of secrets) if (sec && sec.length >= 6) text = text.split(sec).join("***");
  const buf = Buffer.from(text, "utf8");
  if (buf.length <= OUTPUT_CAP_BYTES) return { text, truncated: false };
  return { text: buf.subarray(buf.length - OUTPUT_CAP_BYTES).toString("utf8"), truncated: true };
}

