/**
 * Job queue manager — PURE policy: which manual interventions are allowed on
 * which job, and why not. The server actions in lib/admin-ops/actions.ts call
 * these before touching a row, and the UI calls the same functions to decide
 * which buttons to render, so the two can never disagree.
 *
 * The rules encode real incidents:
 *  - Money-bearing job types (RESIZE, DISK_EXPAND, ASSIGN_DEDICATED_IP) are
 *    REFUNDED by worker/index.ts's reconcileFailedJob when they fail
 *    terminally. Re-queueing one of those would deliver the upgrade for free
 *    after the customer already got their money back — so they are never
 *    re-queueable here; the customer/admin re-runs the original flow.
 *  - PROVISION has its own recovery path (lib/actions-server-lifecycle.ts
 *    retryProvision) that also resets the server row; raw re-queue skips that.
 *  - Force-failing a RUNNING job is only allowed once it has been silent for
 *    STALE_RUNNING_MIN: the single worker process may genuinely still be
 *    executing it, and would then overwrite the row when it finishes.
 */

export type JobLike = {
  id: string;
  type: string;
  status: "QUEUED" | "RUNNING" | "DONE" | "FAILED" | string;
  attempts: number;
  createdAt: Date;
  updatedAt: Date;
  serverId: string | null;
};

export const NO_REQUEUE_TYPES: ReadonlySet<string> = new Set(["RESIZE", "DISK_EXPAND", "ASSIGN_DEDICATED_IP", "PROVISION"]);
/** A RUNNING job silent for this long is considered wedged. */
export const STALE_RUNNING_MIN = 30;
/** A QUEUED job waiting this long is flagged (something is blocking it). */
export const STALE_QUEUED_MIN = 15;

export type JobVerb = "requeue" | "cancel" | "force_fail";

export function ageMin(d: Date, now: Date = new Date()): number {
  return Math.max(0, Math.round((now.getTime() - d.getTime()) / 60_000));
}

export function jobHealth(j: JobLike, now: Date = new Date()): "ok" | "stale_running" | "stale_queued" | "failed" {
  if (j.status === "FAILED") return "failed";
  if (j.status === "RUNNING" && ageMin(j.updatedAt, now) >= STALE_RUNNING_MIN) return "stale_running";
  if (j.status === "QUEUED" && ageMin(j.createdAt, now) >= STALE_QUEUED_MIN) return "stale_queued";
  return "ok";
}

/** null = allowed; otherwise the human reason it is refused. */
export function whyNot(verb: JobVerb, j: JobLike, now: Date = new Date()): string | null {
  switch (verb) {
    case "requeue":
      if (j.status !== "FAILED") return "Only a FAILED job can be re-queued.";
      if (j.type === "PROVISION") return "Use Retry provisioning on the server instead — it also resets the server row.";
      if (NO_REQUEUE_TYPES.has(j.type)) return `${j.type} jobs are refunded when they fail; re-queueing would deliver it for free. Re-run the original flow.`;
      if (j.type === "ADMIN_OPS") return "Start a fresh admin operation instead of re-queueing an old one.";
      return null;
    case "cancel":
      if (j.status !== "QUEUED") return "Only a QUEUED job can be cancelled.";
      return null;
    case "force_fail":
      if (j.status !== "RUNNING") return "Only a RUNNING job can be force-failed.";
      if (ageMin(j.updatedAt, now) < STALE_RUNNING_MIN) {
        return `It last reported progress ${ageMin(j.updatedAt, now)} min ago — the worker is probably still executing it. Wait until it has been silent for ${STALE_RUNNING_MIN} min.`;
      }
      return null;
  }
}

/**
 * What the server row should become after cancelling/force-failing a job of
 * this type, or null to leave it alone. A DELETE flips the server to DELETING
 * at enqueue time (lib/actions.ts serverAction), so cancelling one must not
 * strand the row there; ERROR + a note makes the Reconcile button the obvious
 * next step instead of a server that looks mid-deletion forever.
 */
export function serverStatusAfterAbort(jobType: string, currentStatus: string): { status: "ERROR"; note: string } | null {
  if (jobType === "DELETE" && currentStatus === "DELETING") {
    return { status: "ERROR", note: "Delete was cancelled by an admin — use Reconcile to restore the real status." };
  }
  if ((jobType === "PROVISION" || jobType === "REINSTALL") && (currentStatus === "PROVISIONING" || currentStatus === "REINSTALLING" || currentStatus === "PENDING")) {
    return { status: "ERROR", note: `${jobType.toLowerCase()} was stopped by an admin — retry or reconcile.` };
  }
  return null;
}

