/**
 * Node drain / rebalance PLANNER — pure. Decides where each server on a node
 * would go if that node were emptied (drain) or brought under a RAM target
 * (rebalance). It plans only; executing a move is the VM move engine's job
 * (lib/admin-ops/vm-move.ts → requestVmMove, owned by the vm-node-migration
 * branch). Nothing here is ever applied automatically.
 *
 * Placement rules:
 *  - Same region first (a Singapore customer must not silently land in
 *    Germany); cross-region only when `allowCrossRegion` is set, and every
 *    such move is flagged.
 *  - Only enabled nodes that accept provisions are targets.
 *  - Committed RAM (sum of plan RAM), not instantaneous usage — the same
 *    "can it actually hold this when everyone is busy" basis the order path
 *    uses.
 *  - Largest servers first (first-fit-decreasing onto the target with the
 *    most remaining headroom), keeping `reservePct` of every target free.
 *  - A dedicated-IP server is flagged: a failover IP is bound to its node's
 *    provider account and must be re-routed (or swapped) as part of the move.
 */

export type PlanNode = {
  id: string;
  name: string;
  region: string;
  capacityRamMB: number;
  committedRamMB: number;
  enabled: boolean;
  acceptsProvisions: boolean;
};

export type PlanServer = {
  id: string;
  hostname: string;
  ramMB: number;
  diskGB: number;
  hasDedicatedIp: boolean;
  status: string;
};

export type PlannedMove = {
  serverId: string;
  hostname: string;
  ramMB: number;
  fromNodeId: string;
  toNodeId: string;
  toNodeName: string;
  crossRegion: boolean;
  needsIpWork: boolean;
};

export type DrainPlan = {
  mode: "drain" | "rebalance";
  sourceNodeId: string;
  moves: PlannedMove[];
  unplaceable: { serverId: string; hostname: string; ramMB: number; reason: string }[];
  /** Committed RAM % per node after the plan, for the preview table. */
  after: { nodeId: string; name: string; beforePct: number; afterPct: number }[];
};

export function planDrain(opts: {
  source: PlanNode;
  nodes: PlanNode[];
  servers: PlanServer[];
  mode?: "drain" | "rebalance";
  /** rebalance only: stop once the source is at/below this committed %. */
  targetPct?: number;
  reservePct?: number;
  allowCrossRegion?: boolean;
}): DrainPlan {
  const mode = opts.mode ?? "drain";
  const reserve = Math.min(Math.max(opts.reservePct ?? 10, 0), 50) / 100;
  const free = new Map<string, number>();
  const committed = new Map<string, number>();
  for (const n of opts.nodes) committed.set(n.id, n.committedRamMB);

  const targets = opts.nodes.filter((n) => n.id !== opts.source.id && n.enabled && n.acceptsProvisions);
  for (const t of targets) free.set(t.id, Math.floor(t.capacityRamMB * (1 - reserve)) - t.committedRamMB);

  const movable = opts.servers
    .filter((s) => !["DELETING", "PENDING", "PROVISIONING", "REINSTALLING"].includes(s.status))
    .sort((a, b) => b.ramMB - a.ramMB || a.hostname.localeCompare(b.hostname));

  const moves: PlannedMove[] = [];
  const unplaceable: DrainPlan["unplaceable"] = [];
  let sourceCommitted = opts.source.committedRamMB;
  const goalMB = mode === "rebalance" ? Math.floor(opts.source.capacityRamMB * ((opts.targetPct ?? 75) / 100)) : 0;

  for (const s of movable) {
    if (mode === "rebalance" && sourceCommitted <= goalMB) break;
    const pick = (crossRegion: boolean) =>
      targets
        .filter((t) => (crossRegion ? t.region !== opts.source.region : t.region === opts.source.region))
        .filter((t) => (free.get(t.id) ?? 0) >= s.ramMB)
        .sort((a, b) => (free.get(b.id) ?? 0) - (free.get(a.id) ?? 0) || a.name.localeCompare(b.name))[0];
    let target = pick(false);
    let cross = false;
    if (!target && opts.allowCrossRegion) {
      target = pick(true);
      cross = !!target;
    }
    if (!target) {
      unplaceable.push({
        serverId: s.id,
        hostname: s.hostname,
        ramMB: s.ramMB,
        reason: targets.length === 0 ? "No other enabled node accepts provisions." : `No ${opts.allowCrossRegion ? "" : "same-region "}node has ${s.ramMB} MB of headroom left.`,
      });
      continue;
    }
    free.set(target.id, (free.get(target.id) ?? 0) - s.ramMB);
    committed.set(target.id, (committed.get(target.id) ?? 0) + s.ramMB);
    sourceCommitted -= s.ramMB;
    committed.set(opts.source.id, sourceCommitted);
    moves.push({
      serverId: s.id,
      hostname: s.hostname,
      ramMB: s.ramMB,
      fromNodeId: opts.source.id,
      toNodeId: target.id,
      toNodeName: target.name,
      crossRegion: cross,
      needsIpWork: s.hasDedicatedIp,
    });
  }

  const pctOf = (mb: number, cap: number) => (cap > 0 ? Math.round((mb / cap) * 100) : 0);
  const after = opts.nodes.map((n) => ({
    nodeId: n.id,
    name: n.name,
    beforePct: pctOf(n.committedRamMB, n.capacityRamMB),
    afterPct: pctOf(committed.get(n.id) ?? n.committedRamMB, n.capacityRamMB),
  }));

  return { mode, sourceNodeId: opts.source.id, moves, unplaceable, after };
}

