    free.set(target.id, (free.get(target.id) ?? 0) - s.ramMB);
    committed.set(target.id, (committed.get(target.id) ?? 0) + s.ramMB);
    sourceCommitted -= s.ramMB;
    committed.set(opts.source.id, sourceCommitted);
    moves.push({
      serverId: s.id,
      hostname: s.hostname,
      ramMB: s.ramMB,
      fromNodeId: opts.source.id,
      toNodeId: target.id,
      toNodeName: target.name,
      crossRegion: cross,
      needsIpWork: s.hasDedicatedIp,
    });
  }

  const pctOf = (mb: number, cap: number) => (cap > 0 ? Math.round((mb / cap) * 100) : 0);
  const after = opts.nodes.map((n) => ({
    nodeId: n.id,
    name: n.name,
    beforePct: pctOf(n.committedRamMB, n.capacityRamMB),
    afterPct: pctOf(committed.get(n.id) ?? n.committedRamMB, n.capacityRamMB),
  }));

  return { mode, sourceNodeId: opts.source.id, moves, unplaceable, after };
}

