/**
 * Dedicated-IP admin operations — PURE preconditions + the human-readable
 * step plan shown as the dry-run preview before anything is enqueued. The
 * worker (worker/admin-ops.ts) re-checks every precondition itself at run
 * time; this is the same function, so preview and execution agree.
 *
 * Scope (per the ownership split with the vm-node-migration branch): moving
 * an IP between servers on the SAME node. Cross-node moves need the VM move
 * engine (a failover IP routes only to the node whose provider account owns
 * it) and are refused here with a pointer to it.
 */

export type IpOpServer = {
  id: string;
  hostname: string;
  status: string;
  vmid: number | null;
  nodeId: string | null;
  nodeName: string | null;
  isGame: boolean;
  wantsDedicatedIp: boolean;
  hasInflightJob: boolean;
  dedicatedIp: { id: string; address: string; status: string; nodeId: string } | null;
};

export type IpPlan = { ok: true; steps: string[]; warnings: string[] } | { ok: false; error: string };

const SETTLED = new Set(["RUNNING", "STOPPED"]);

function basic(s: IpOpServer, role: string): string | null {
  if (!s.vmid) return `${role} ${s.hostname} has no VM yet.`;
  if (!SETTLED.has(s.status)) return `${role} ${s.hostname} is ${s.status} — wait until it is RUNNING or STOPPED.`;
  if (s.hasInflightJob) return `${role} ${s.hostname} has a job in flight — wait for it to finish.`;
  return null;
}

export function planIpReassign(source: IpOpServer, target: IpOpServer): IpPlan {
  if (source.id === target.id) return { ok: false, error: "Source and target are the same server." };
  const e = basic(source, "Source") ?? basic(target, "Target");
  if (e) return { ok: false, error: e };
  if (!source.dedicatedIp) return { ok: false, error: `${source.hostname} has no dedicated IP to give.` };
  if (source.dedicatedIp.status !== "ASSIGNED") return { ok: false, error: `${source.dedicatedIp.address} is ${source.dedicatedIp.status}, not ASSIGNED.` };
  if (target.dedicatedIp) return { ok: false, error: `${target.hostname} already has ${target.dedicatedIp.address}. Release it first.` };
  const srcNode = source.nodeId;
  if (!srcNode || srcNode !== target.nodeId || source.dedicatedIp.nodeId !== target.nodeId) {
    return {
      ok: false,
      error: `${target.hostname} is on ${target.nodeName ?? "another node"}, the IP belongs to ${source.nodeName ?? "the source's node"}. A failover IP only routes to its own node — use Move server (VM move engine) for cross-node moves.`,
    };
  }
  const ip = source.dedicatedIp.address;
  const warnings: string[] = [];
  if (source.status === "RUNNING") warnings.push(`${source.hostname} is power-cycled and comes back on a NAT address (new ip:port for SSH and every forwarded port).`);
  if (target.status === "RUNNING") warnings.push(`${target.hostname} is power-cycled to pick up ${ip} (brief downtime).`);
  if (target.isGame) warnings.push(`${target.hostname} is a game server: the dedicated-IP add-on becomes billable on its next renewal.`);
  if (source.wantsDedicatedIp) warnings.push(`${source.hostname} stops being billed for a dedicated IP (it no longer has one).`);
  return {
    ok: true,
    warnings,
    steps: [
      `Stop ${source.hostname}${source.status === "RUNNING" ? "" : " (already stopped)"}.`,
      `Release ${ip} from ${source.hostname} (pool row → FREE, provider virtual MAC removed).`,
      `Give ${source.hostname} a NAT address + SSH port on ${source.nodeName} and point its net0/ipconfig0 at it.`,
      `Claim ${ip} for ${target.hostname} (new virtual MAC), set its net0/ipconfig0 to ${ip}.`,
      `Power-cycle ${target.hostname}${target.status === "RUNNING" ? "" : " (start skipped — it was stopped)"} so cloud-init applies the new address.`,
      `Start ${source.hostname} again${source.status === "RUNNING" ? "" : " — skipped, it was stopped"}.`,
      "Re-sync the node's NAT chain, then each server's subdomain DNS.",
      "Notify both owners in-app (optional email per the form).",
    ],
  };
}

export function planIpRelease(s: IpOpServer): IpPlan {
  const e = basic(s, "Server");
  if (e) return { ok: false, error: e };
  if (!s.dedicatedIp) return { ok: false, error: `${s.hostname} has no dedicated IP.` };
  return {
    ok: true,
    warnings: [
      `${s.hostname} moves to a NAT address — its public ip:port for SSH and every forwarded port changes.`,
      ...(s.status === "RUNNING" ? [`${s.hostname} is power-cycled.`] : []),
    ],
    steps: [
      `Stop ${s.hostname}${s.status === "RUNNING" ? "" : " (already stopped)"}.`,
      `Release ${s.dedicatedIp.address} to the free pool (virtual MAC removed).`,
      `Allocate a NAT address + SSH port on ${s.nodeName ?? "its node"}; set net0/ipconfig0.`,
      `Start ${s.hostname}${s.status === "RUNNING" ? "" : " — skipped, it was stopped"}; re-sync NAT + DNS.`,
    ],
  };
}

export function planIpAssign(s: IpOpServer, address: string | null, freeOnNode: string[]): IpPlan {
  const e = basic(s, "Server");
  if (e) return { ok: false, error: e };
  if (s.dedicatedIp) return { ok: false, error: `${s.hostname} already has ${s.dedicatedIp.address}.` };
  if (!freeOnNode.length) return { ok: false, error: `No FREE customer IPs in ${s.nodeName ?? "this node"}'s pool.` };
  if (address && !freeOnNode.includes(address)) return { ok: false, error: `${address} is not a FREE customer IP on ${s.nodeName ?? "this node"}.` };
  const ip = address ?? freeOnNode[0];
  return {
    ok: true,
    warnings: s.status === "RUNNING" ? [`${s.hostname} is power-cycled to pick up ${ip}.`] : [],
    steps: [
      `Claim ${ip} from ${s.nodeName ?? "the node"}'s pool (virtual MAC created).`,
      `Point net0/ipconfig0 at ${ip}; the NAT SSH port is released.`,
      `Power-cycle ${s.hostname}${s.status === "RUNNING" ? "" : " — skipped, it was stopped"}; re-sync NAT + DNS; notify the owner.`,
    ],
  };
}

