/**
 * Thin seam to the node-to-node VM move engine.
 *
 * OWNERSHIP: the move engine itself (lib/vm-move/*, worker/vm-move.ts, job
 * type VM_MOVE, dedicated-IP carry-over) belongs to the vm-node-migration
 * branch — this console never re-implements a cross-node move. Everything in
 * the Ops UI that wants to move a server (single "Move server", the drain
 * planner's "Execute") calls ONLY `requestVmMove` below.
 *
 * INTEGRATION: until that branch is merged this is a stub — dry runs return a
 * clear "engine not available" answer, real requests are refused. When the
 * engine lands, replace the body of `requestVmMove` with a call into it
 * (keep the signature; the UI depends only on `VmMoveResult`).
 */
export type VmMoveRequest = {
  serverId: string;
  targetNodeId: string;
  dryRun: boolean;
  reason: string;
  /** Admin user id, for the engine's own audit trail. */
  requestedBy?: string;
};

export type VmMoveResult =
  | { ok: true; dryRun: boolean; jobId?: string; steps?: string[]; warnings?: string[] }
  | { ok: false; error: string; engineMissing?: boolean };

export const VM_MOVE_ENGINE_AVAILABLE = false;

export async function requestVmMove(req: VmMoveRequest): Promise<VmMoveResult> {
  if (!req.serverId || !req.targetNodeId) return { ok: false, error: "serverId and targetNodeId are required." };
  return {
    ok: false,
    engineMissing: true,
    error:
      "The VM move engine (branch feature/vm-node-migration) is not merged into this build yet. " +
      "The drain plan above is accurate; execute the moves once the engine ships.",
  };
}

