/**
 * Bulk power / teardown across many servers — PURE eligibility rules and the
 * wave scheduler the worker's `bulk_power` op drives.
 *
 * Why waves instead of enqueueing everything at once: the worker runs up to
 * WORKER_CONCURRENCY jobs in parallel and a burst of START/REBOOT on one node
 * saturates that node's pveproxy + storage (see worker/index.ts's
 * concurrency note). The admin picks a concurrency (1-8); the bulk job keeps
 * at most that many of its children in flight and only then releases the
 * next one.
 *
 * Bulk DELETE is fenced to test infrastructure: servers owned by a staff
 * account or an account excluded from revenue (the owner's own/test
 * accounts). A paying customer's server is never in a bulk delete.
 */

export type BulkAction = "start" | "stop" | "reboot" | "game_restart" | "delete";
export const BULK_ACTIONS: BulkAction[] = ["start", "stop", "reboot", "game_restart", "delete"];
export const BULK_MAX_SERVERS = 200;
export const BULK_MAX_CONCURRENCY = 8;

export type BulkServer = {
  id: string;
  hostname: string;
  status: string;
  isGame: boolean;
  hasInflightJob: boolean;
  ownerIsStaff: boolean;
  ownerExcludedFromRevenue: boolean;
  isFree: boolean;
};

/** null = eligible; otherwise why this server is skipped. */
export function bulkIneligible(action: BulkAction, s: BulkServer): string | null {
  if (s.hasInflightJob) return "another job is in flight";
  switch (action) {
    case "start":
      return s.status === "STOPPED" ? null : `is ${s.status}, not STOPPED`;
    case "stop":
    case "reboot":
      return s.status === "RUNNING" ? null : `is ${s.status}, not RUNNING`;
    case "game_restart":
      if (!s.isGame) return "not a game server";
      return s.status === "RUNNING" ? null : `VM is ${s.status}, not RUNNING`;
    case "delete":
      if (!(s.ownerIsStaff || s.ownerExcludedFromRevenue)) return "owned by a real customer — bulk delete only covers staff/test accounts";
      if (s.status === "DELETING") return "already deleting";
      return null;
  }
}

export type ChildState = { serverId: string; jobId: string | null; skipped?: string; status?: string };

/**
 * Given current children (with their job status filled in), which serverIds
 * may be launched now? Children with a jobId and a non-terminal status count
 * against the concurrency budget.
 */
export function nextWave(children: ChildState[], concurrency: number): string[] {
  const c = Math.min(Math.max(Math.trunc(concurrency) || 1, 1), BULK_MAX_CONCURRENCY);
  const inflight = children.filter((ch) => ch.jobId && ch.status !== "DONE" && ch.status !== "FAILED").length;
  const budget = Math.max(0, c - inflight);
  return children.filter((ch) => !ch.jobId && !ch.skipped).slice(0, budget).map((ch) => ch.serverId);
}

export function bulkDone(children: ChildState[]): boolean {
  return children.every((ch) => ch.skipped || (ch.jobId && (ch.status === "DONE" || ch.status === "FAILED")));
}

/** Map a bulk action to the Job the child runs. */
export function childJobFor(action: BulkAction): { type: "START" | "STOP" | "REBOOT" | "DELETE" | "GAME_POWER"; payload?: Record<string, unknown> } {
  switch (action) {
    case "start":
      return { type: "START" };
    case "stop":
      return { type: "STOP" };
    case "reboot":
      return { type: "REBOOT" };
    case "delete":
      return { type: "DELETE" };
    case "game_restart":
      return { type: "GAME_POWER", payload: { action: "restart", announce: true } };
  }
}

