import { planIpReassign, planIpAssign, type IpOpServer } from "../lib/admin-ops/ip-ops.ts";
import { bulkIneligible, nextWave, bulkDone, type BulkServer } from "../lib/admin-ops/bulk.ts";
import { adminOpsLockKey, cleanReason } from "../lib/admin-ops/types.ts";

// ---------------------------------------------------------------------------
// Diagnose rules
// ---------------------------------------------------------------------------

function healthyFacts(over: Partial<DiagnosisFacts> = {}): DiagnosisFacts {
  const base: DiagnosisFacts = {
    sandbox: false,
    server: {
      id: "s1",
      hostname: "mc-1",
      status: "RUNNING",
