test("diagnose: missing DNAT rule is the top cause and suggests sync_forwards", () => {
  const f = healthyFacts();
  f.network = { ...f.network, missingRules: ["tcp/25601->10.20.0.120:25565"] };
  f.external = { ...f.external, gamePortOpen: false, gamePortError: "timed out" };
  const r = evaluateDiagnosis(f);
  assert.equal(r.causes[0].key, "nat_missing");
  assert.ok(r.causes[0].fixes.includes("sync_forwards"));
