test("guest commands: every catalog command builds with defaults or rejects missing required params", () => {
  for (const c of GUEST_COMMANDS) {
    const required = c.params.filter((p) => p.default == null && !p.optional);
    if (required.length) assert.throws(() => buildGuestCommand(c.key, {}), /required/);
    else assert.ok(buildGuestCommand(c.key, {}).script.length > 0);
  }
});

test("guest commands: hostile parameters are rejected, never sanitized", () => {
  const evil = ["x; rm -rf /", "a$(id)", "`id`", "a b", "../etc", "a|b", "a\nb", "-rf"];
  for (const v of evil) {
    assert.throws(() => buildGuestCommand("journal_unit", { unit: v }), undefined, `unit ${v}`);
    if (!/^[a-zA-Z0-9]/.test(v) || /[^a-zA-Z0-9_.-]/.test(v)) assert.throws(() => buildGuestCommand("docker_logs", { container: v }), undefined, `container ${v}`);
  }
  assert.throws(() => buildGuestCommand("largest_files", { path: "/var/../etc" }));
  assert.throws(() => buildGuestCommand("largest_files", { path: "/tmp;id" }));
  assert.throws(() => buildGuestCommand("overview", { extra: "1" }), /Unexpected/);
  assert.throws(() => buildGuestCommand("nope"), /Unknown/);
  assert.throws(() => buildGuestCommand("journal_unit", { unit: "ssh", lines: "5; id" }), /whole number/);
});

test("guest commands: lines are clamped and values single-quoted", () => {
  const { script } = buildGuestCommand("journal_unit", { unit: "minecraft.service", lines: 99999 });
  assert.match(script, /-n 500 /);
  assert.match(script, /'minecraft\.service'/);
  const d = buildGuestCommand("docker_logs", { container: "nx-game_1", lines: 1 }).script;
  assert.match(d, /--tail 10 'nx-game_1'/);
});

test("guest commands: capOutput scrubs secrets and caps size", () => {
  const r = capOutput("token=Sup3rSecret! done", ["Sup3rSecret!"]);
  assert.equal(r.text, "token=*** done");
  const big = capOutput("x".repeat(200_000));
  assert.ok(big.truncated);
  assert.ok(Buffer.byteLength(big.text) <= 64 * 1024);
});

