// Job queue policy
// ---------------------------------------------------------------------------

const t0 = new Date("2026-10-01T00:00:00Z");
const mins = (m: number) => new Date(t0.getTime() - m * 60_000);
const job = (o: Partial<Parameters<typeof whyNot>[1]>) => ({
  id: "j",
  type: "REBOOT",
  status: "FAILED",
  attempts: 3,
  createdAt: mins(60),
  updatedAt: mins(60),
  serverId: "s",
  ...o,
});

test("job queue: requeue only FAILED, never money-bearing or PROVISION", () => {
  assert.equal(whyNot("requeue", job({}), t0), null);
  assert.match(whyNot("requeue", job({ type: "RESIZE" }), t0)!, /refunded/);
  assert.match(whyNot("requeue", job({ type: "DISK_EXPAND" }), t0)!, /refunded/);
  assert.match(whyNot("requeue", job({ type: "ASSIGN_DEDICATED_IP" }), t0)!, /refunded/);
  assert.match(whyNot("requeue", job({ type: "PROVISION" }), t0)!, /Retry provisioning/);
  assert.match(whyNot("requeue", job({ status: "DONE" }), t0)!, /Only a FAILED/);
});

test("job queue: force-fail requires a silent RUNNING job", () => {
  assert.match(whyNot("force_fail", job({ status: "RUNNING", updatedAt: mins(5) }), t0)!, /still executing/);
  assert.equal(whyNot("force_fail", job({ status: "RUNNING", updatedAt: mins(45) }), t0), null);
  assert.equal(whyNot("cancel", job({ status: "QUEUED" }), t0), null);
  assert.match(whyNot("cancel", job({ status: "RUNNING" }), t0)!, /QUEUED/);
  assert.equal(jobHealth(job({ status: "RUNNING", updatedAt: mins(45) }), t0), "stale_running");
  assert.equal(jobHealth(job({ status: "QUEUED", createdAt: mins(20) }), t0), "stale_queued");
});

test("job queue: cancelling a DELETE un-strands the server row", () => {
  assert.equal(serverStatusAfterAbort("DELETE", "DELETING")?.status, "ERROR");
  assert.equal(serverStatusAfterAbort("REBOOT", "RUNNING"), null);
});

