test("drift: orphan detection respects tags, stopped state and templates", () => {
  const f = detectDrift(driftBase());
  const orphan150 = f.find((x) => x.kind === "orphan_vm" && x.vmid === 150);
  assert.ok(orphan150);
  assert.equal(orphan150!.fix, "orphan_vm_destroy");
  assert.match(orphan150!.detail, /old-mc/);
  const orphan151 = f.find((x) => x.kind === "orphan_vm" && x.vmid === 151);
  assert.equal(orphan151!.fix, undefined, "a RUNNING orphan is never one-click destroyable");
  assert.ok(!f.some((x) => x.vmid === 160 && x.kind === "orphan_vm"), "staging VMs are never orphans");
  assert.ok(f.some((x) => x.vmid === 200 && x.kind === "unmanaged_vm" && !x.fix));
  assert.ok(!f.some((x) => x.vmid === 9000));
});

test("drift: status mismatch, wrong node, missing vm, ip problems, templates", () => {
  const f = detectDrift(driftBase());
  assert.ok(f.some((x) => x.kind === "status_mismatch" && x.serverId === "a" && x.fix === "reconcile_status"));
  assert.ok(f.some((x) => x.kind === "wrong_node" && x.serverId === "b"));
  assert.ok(f.some((x) => x.kind === "missing_vm" && x.serverId === "c"));
  assert.ok(f.some((x) => x.kind === "ip_conflict" && x.ipId === "ip1"), "FREE row held by a live server");
  const orphanIp = f.find((x) => x.kind === "ip_orphan" && x.ipId === "ip2");
  assert.equal(orphanIp?.fix, "orphan_ip_release");
  assert.ok(f.some((x) => x.kind === "template_missing" && x.nodeId === "n1"));
});

test("drift: an orphaned IP still held by a live server is NOT offered for release", () => {
  const input = driftBase();
  input.dedicatedIps = [{ id: "ip3", address: "10.20.0.101", status: "ASSIGNED", serverId: "gone", nodeId: "n1", purpose: "CUSTOMER" }];
  const f = detectDrift(input).find((x) => x.ipId === "ip3");
  assert.equal(f?.fix, undefined);
});

test("drift: unreachable node is reported and its servers aren't called missing", () => {
  const input = driftBase();
  input.vmsByNode.n2 = null;
  const f = detectDrift(input);
  assert.ok(f.some((x) => x.kind === "node_unreachable" && x.nodeId === "n2"));
  assert.ok(!f.some((x) => x.serverId === "c"));
});

