test("ip reassign: refuses cross-node, busy, already-has-IP; plans same-node", () => {
  const src = ipServer({ id: "a", hostname: "a", dedicatedIp: { id: "i", address: "51.1.1.1", status: "ASSIGNED", nodeId: "n1" } });
  const tgt = ipServer({ id: "b", hostname: "b", isGame: true });
  const ok = planIpReassign(src, tgt);
  assert.ok(ok.ok);
  if (ok.ok) assert.ok(ok.warnings.some((w) => /billable/.test(w)));
  const cross = planIpReassign(src, { ...tgt, nodeId: "n3", nodeName: "node-3" });
  assert.ok(!cross.ok && /Move server/.test(cross.error));
  assert.ok(!planIpReassign(src, { ...tgt, hasInflightJob: true }).ok);
  assert.ok(!planIpReassign(src, { ...tgt, dedicatedIp: { id: "j", address: "51.1.1.2", status: "ASSIGNED", nodeId: "n1" } }).ok);
  assert.ok(!planIpReassign({ ...src, dedicatedIp: null }, tgt).ok);
  assert.ok(!planIpReassign(src, { ...tgt, status: "PROVISIONING" }).ok);
});

test("ip assign: specific address must be FREE on the node", () => {
  const s = ipServer({});
  assert.ok(planIpAssign(s, null, ["51.1.1.9"]).ok);
  assert.ok(!planIpAssign(s, "51.1.1.8", ["51.1.1.9"]).ok);
  assert.ok(!planIpAssign(s, null, []).ok);
});

