test("bulk: delete is fenced to staff/test accounts; waves respect concurrency", () => {
  const s: BulkServer = { id: "1", hostname: "h", status: "RUNNING", isGame: false, hasInflightJob: false, ownerIsStaff: false, ownerExcludedFromRevenue: false, isFree: false };
  assert.match(bulkIneligible("delete", s)!, /real customer/);
  assert.equal(bulkIneligible("delete", { ...s, ownerExcludedFromRevenue: true }), null);
  assert.equal(bulkIneligible("reboot", s), null);
  assert.match(bulkIneligible("start", s)!, /not STOPPED/);
  assert.match(bulkIneligible("game_restart", s)!, /not a game/);
  const kids = [
    { serverId: "a", jobId: "1", status: "RUNNING" },
    { serverId: "b", jobId: "2", status: "DONE" },
    { serverId: "c", jobId: null },
    { serverId: "d", jobId: null },
    { serverId: "e", jobId: null, skipped: "busy" },
  ];
  assert.deepEqual(nextWave(kids, 2), ["c"]);
  assert.deepEqual(nextWave(kids, 3), ["c", "d"]);
  assert.equal(bulkDone(kids), false);
  assert.equal(bulkDone([{ serverId: "a", jobId: "1", status: "FAILED" }, { serverId: "e", jobId: null, skipped: "x" }]), true);
});

test("lock key: read-only ops run in parallel, scans are singletons, other jobs untouched", () => {
  assert.equal(adminOpsLockKey({ id: "j1", type: "ADMIN_OPS", serverId: null, payload: { op: "diagnose" } }), "adminops:job:j1");
  assert.equal(adminOpsLockKey({ id: "j1", type: "ADMIN_OPS", serverId: null, payload: { op: "drift_scan" } }), "adminops:drift_scan");
  assert.equal(adminOpsLockKey({ id: "j1", type: "ADMIN_OPS", serverId: null, payload: { op: "ip_reassign", lockKey: "ip:n1" } }), "adminops:ip:n1");
  assert.equal(adminOpsLockKey({ id: "j1", type: "ADMIN_OPS", serverId: "s", payload: { op: "ip_release" } }), null);
  assert.equal(adminOpsLockKey({ id: "j1", type: "SYNC_FORWARDS", serverId: null, payload: null }), null);
  assert.equal(adminOpsLockKey({ id: "j1", type: "ADMIN_OPS", serverId: null, payload: { op: "x", lockKey: "bad key; drop" } }), "adminops:x");
});

