import { test } from "node:test";
import assert from "node:assert/strict";
import {
  evaluateDiagnosis,
  logHighlights,
  ipFromIpconfig,
  type DiagnosisFacts,
} from "../lib/admin-ops/diagnose-rules.ts";
import { buildGuestCommand, capOutput, GUEST_COMMANDS } from "../lib/admin-ops/guest-commands.ts";
import { whyNot, jobHealth, serverStatusAfterAbort } from "../lib/admin-ops/job-queue.ts";
import { detectDrift, type DriftInput } from "../lib/admin-ops/drift.ts";
import { planDrain } from "../lib/admin-ops/drain-planner.ts";
import { planIpReassign, planIpAssign, type IpOpServer } from "../lib/admin-ops/ip-ops.ts";
import { bulkIneligible, nextWave, bulkDone, type BulkServer } from "../lib/admin-ops/bulk.ts";
import { adminOpsLockKey, cleanReason } from "../lib/admin-ops/types.ts";

// ---------------------------------------------------------------------------
// Diagnose rules
// ---------------------------------------------------------------------------

function healthyFacts(over: Partial<DiagnosisFacts> = {}): DiagnosisFacts {
  const base: DiagnosisFacts = {
    sandbox: false,
    server: {
      id: "s1",
      hostname: "mc-1",
      status: "RUNNING",
      vmid: 120,
      isGame: true,
      gameFamily: "minecraft",
      provisionError: null,
      provisioningStep: null,
      ipAddress: "10.20.0.120",
      sshPort: 20005,
      dedicatedIp: null,
      publicHost: "51.79.162.96",
    },
    node: { name: "primary", apiReachable: true, cpuPct: 30, memPct: 60 },
    vm: { pveStatus: "running", existsOnNode: true, agentResponding: true, configuredIp: "10.20.0.120", memPct: 50, cpuPct: 10, uptimeSec: 3600 },
    guest: {
      sshReachable: true,
