test("drain: same-region first-fit-decreasing with reserve, cross-region only when allowed", () => {
  const nodes = [
    { id: "src", name: "sgp-1", region: "sgp1", capacityRamMB: 64000, committedRamMB: 30000, enabled: true, acceptsProvisions: true },
    { id: "sg2", name: "sgp-2", region: "sgp1", capacityRamMB: 64000, committedRamMB: 50000, enabled: true, acceptsProvisions: true },
    { id: "de", name: "fsn-1", region: "fsn1", capacityRamMB: 128000, committedRamMB: 0, enabled: true, acceptsProvisions: true },
    { id: "off", name: "off", region: "sgp1", capacityRamMB: 64000, committedRamMB: 0, enabled: true, acceptsProvisions: false },
  ];
  const servers = [
    { id: "a", hostname: "a", ramMB: 8192, diskGB: 50, hasDedicatedIp: true, status: "RUNNING" },
    { id: "b", hostname: "b", ramMB: 4096, diskGB: 40, hasDedicatedIp: false, status: "RUNNING" },
    { id: "c", hostname: "c", ramMB: 16384, diskGB: 80, hasDedicatedIp: false, status: "STOPPED" },
  ];
  const p = planDrain({ source: nodes[0], nodes, servers });
  // sgp-2 free = 64000*0.9 - 50000 = 7600 → only b (4096) fits; a and c unplaceable without cross-region
  assert.deepEqual(p.moves.map((m) => m.serverId), ["b"]);
  assert.deepEqual(p.unplaceable.map((u) => u.serverId).sort(), ["a", "c"]);
  assert.ok(!p.moves.some((m) => m.toNodeId === "off"));
  const p2 = planDrain({ source: nodes[0], nodes, servers, allowCrossRegion: true });
  assert.equal(p2.unplaceable.length, 0);
  assert.ok(p2.moves.find((m) => m.serverId === "a")!.crossRegion);
  assert.ok(p2.moves.find((m) => m.serverId === "a")!.needsIpWork);
});

test("drain: rebalance stops once the source is under target", () => {
  const nodes = [
    { id: "src", name: "s", region: "r", capacityRamMB: 10000, committedRamMB: 9000, enabled: true, acceptsProvisions: true },
    { id: "t", name: "t", region: "r", capacityRamMB: 100000, committedRamMB: 0, enabled: true, acceptsProvisions: true },
  ];
