class TerminalOpError extends Error {}

// ---------------------------------------------------------------------------
// Job-row helpers
// ---------------------------------------------------------------------------

async function patchPayload(job: Job, patch: Record<string, unknown>): Promise<void> {
  const fresh = await db.job.findUnique({ where: { id: job.id }, select: { payload: true } });
  const payload = { ...((fresh?.payload as Record<string, unknown> | null) ?? {}), ...patch };
  await db.job.update({ where: { id: job.id }, data: { payload: payload as Prisma.InputJsonValue } });
}

async function step(job: Job, text: string, progress?: number): Promise<void> {
  await db.job.update({ where: { id: job.id }, data: { step: text.slice(0, 190), ...(progress != null ? { progress } : {}) } }).catch(() => {});
}

async function finish(job: Job, result: unknown): Promise<void> {
  await patchPayload(job, { result });
  await db.job.update({ where: { id: job.id }, data: { progress: 100, step: "Done" } }).catch(() => {});
}

/** Fail without retry, recording a structured result for the UI. */
async function failTerminal(job: Job, message: string, result?: unknown): Promise<never> {
  await patchPayload(job, { result: result ?? { ok: false, error: message } }).catch(() => {});
  await db.job.update({ where: { id: job.id }, data: { attempts: NO_RETRY_ATTEMPTS } }).catch(() => {});
  throw new TerminalOpError(message);
}

