const SERVER_INCLUDE = {
  node: true,
  dedicatedIp: true,
  portForwards: true,
  gamePlan: { select: { gameFamily: true, ramMB: true } },
  osTemplate: { select: { family: true } },
  plan: { select: { ramMB: true } },
