function clientFor(n: { apiUrl: string; pveNode: string; tokenId: string; tokenSecret: string }): PveClient {
  return pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret });
}

function withTimeout<T>(p: Promise<T>, ms: number, what: string): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const t = setTimeout(() => reject(new Error(`${what} timed out after ${Math.round(ms / 1000)}s`)), ms);
    p.then(
      (v) => {
        clearTimeout(t);
        resolve(v);
      },
      (e) => {
        clearTimeout(t);
        reject(e);
      },
    );
  });
}

async function soft<T>(p: () => Promise<T>, ms = 15_000, what = "check"): Promise<T | null> {
  try {
    return await withTimeout(p(), ms, what);
  } catch {
    return null;
  }
}

function familyOf(s: LoadedServer): GameFamily | null {
  return gameFamilyForServer(s as unknown as { gamePlan?: { gameFamily?: string | null } | null; osTemplate?: { family?: string | null } | null });
}

// ---------------------------------------------------------------------------
// Probes
