const GUEST_DIAG_MARK = "NXD";

function guestDiagScript(hints: string[] | null, family: string | null): string {
  const lines = [
    `echo "${GUEST_DIAG_MARK}:LOAD:$(cut -d' ' -f1 /proc/loadavg)"`,
    `echo "${GUEST_DIAG_MARK}:CPUS:$(nproc 2>/dev/null)"`,
    `echo "${GUEST_DIAG_MARK}:MEM:$(awk '/MemTotal/{t=$2}/MemAvailable/{a=$2}END{if(t>0)printf "%d",(t-a)*100/t}' /proc/meminfo)"`,
    `echo "${GUEST_DIAG_MARK}:DISK:$(df -P / 2>/dev/null | awk 'NR==2{gsub("%","",$5);print $5}')"`,
    `echo "${GUEST_DIAG_MARK}:FAILED:$(systemctl --failed --no-legend --plain 2>/dev/null | awk '{print $1}' | tr '\\n' ' ')"`,
    `echo "${GUEST_DIAG_MARK}:OOM:$(journalctl -k --since '-24h' --no-pager 2>/dev/null | grep -ciE 'oom-kill|killed process')"`,
  ];
  if (hints && family) {
    const h = hints.map(shq).join(" ");
    lines.push(
      `unit=""`,
      `for c in ${h}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
      `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(family)} | head -1 | awk '{print $1}'); fi`,
      `echo "${GUEST_DIAG_MARK}:UNIT:\${unit:-none}"`,
      `if [ -n "$unit" ]; then echo "${GUEST_DIAG_MARK}:STATE:$(systemctl is-active "$unit" 2>/dev/null)"; fi`,
      `rc=$(for c in $(docker ps -aq 2>/dev/null); do docker inspect -f '{{.RestartCount}}' "$c" 2>/dev/null; done | sort -nr | head -1); echo "${GUEST_DIAG_MARK}:RESTARTS:\${rc:-}"`,
      `echo "${GUEST_DIAG_MARK}:LOGBEGIN"`,
      `if [ -n "$unit" ]; then journalctl -u "$unit" -n 80 --no-pager 2>/dev/null | tail -80; fi`,
      `echo "${GUEST_DIAG_MARK}:LOGEND"`,
    );
  }
  return lines.join("\n");
}

function parseGuestDiag(out: string) {
  const get = (k: string) => new RegExp(`^${GUEST_DIAG_MARK}:${k}:(.*)$`, "m").exec(out)?.[1]?.trim() ?? null;
  const num = (k: string) => {
    const v = get(k);
    const n = v == null || v === "" ? NaN : Number(v);
    return Number.isFinite(n) ? n : null;
  };
  const begin = out.indexOf(`${GUEST_DIAG_MARK}:LOGBEGIN`);
  const end = out.indexOf(`${GUEST_DIAG_MARK}:LOGEND`);
  const logLines = begin >= 0 && end > begin ? out.slice(begin + `${GUEST_DIAG_MARK}:LOGBEGIN`.length, end).split(/\r?\n/).filter(Boolean) : [];
  const unit = get("UNIT");
  return {
    load1: num("LOAD"),
    cpuCount: num("CPUS"),
    memPct: num("MEM"),
    diskPct: num("DISK"),
    failedUnits: (get("FAILED") ?? "").split(/\s+/).filter(Boolean),
    oom: num("OOM"),
    unit: unit && unit !== "none" ? unit : null,
    state: get("STATE"),
    restarts: num("RESTARTS"),
    logLines,
  };
}

async function readNatChain(node: NonNullable<Awaited<ReturnType<typeof nodeRowFor>>>): Promise<string | null> {
  try {
    if (node.isPrimary) {
      const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", node.natChain], { timeout: 10_000 });
      return stdout;
    }
    return await withTimeout(agentListChain(node, node.natChain), 15_000, "agent chain read");
  } catch {
    return null;
  }
}

export async function gatherDiagnosisFacts(server: LoadedServer, opts: { excludeJobId?: string } = {}): Promise<DiagnosisFacts> {
  const node = await nodeRowFor(server);
  const family = familyOf(server);
  const isGame = !!server.gamePlanId || !!family;
  const join = family ? joinPortFor(family) : null;
  const dedicated = server.dedicatedIp?.address ?? null;
  const publicHost = dedicated ?? node?.publicIp ?? process.env.PUBLIC_IP ?? null;
  const joinForward = join ? server.portForwards.find((f) => f.guestPort === join.port && f.protocol === join.protocol) ?? null : null;
