    ? dedicated
      ? `${dedicated}:${join.port}`
      : joinForward && publicHost
        ? `${publicHost}:${joinForward.publicPort}`
        : null
    : dedicated
      ? `${dedicated}:22`
      : publicHost && server.sshPort
        ? `${publicHost}:${server.sshPort}`
        : null;

  // Expected NAT rules for this one server (same planner the real sync uses).
  const src: ForwardSource = {
    serverId: server.id,
    hostname: server.hostname,
    ipAddress: server.ipAddress,
    sshPort: server.sshPort,
    portForwards: server.portForwards,
  };
  const expectedRules = dedicated ? [] : planNatRules([src]).rules.map(ruleKey);

  // Jobs
  const now = Date.now();
  const recent = await db.job.findMany({
    where: { serverId: server.id, createdAt: { gte: new Date(now - 7 * 86400_000) }, ...(opts.excludeJobId ? { id: { not: opts.excludeJobId } } : {}) },
    orderBy: { createdAt: "desc" },
    take: 30,
    select: { id: true, type: true, status: true, error: true, createdAt: true, updatedAt: true },
  });
  const activeJob = recent.find((j) => j.status === "QUEUED" || j.status === "RUNNING");
  const jobs: DiagnosisFacts["jobs"] = {
    active: activeJob
      ? { id: activeJob.id, type: activeJob.type, status: activeJob.status, ageMin: Math.round((now - (activeJob.status === "RUNNING" ? activeJob.updatedAt : activeJob.createdAt).getTime()) / 60_000) }
      : null,
    recentFailures: recent
      .filter((j) => j.status === "FAILED")
      .slice(0, 5)
      .map((j) => ({ id: j.id, type: j.type, error: (j.error ?? "").slice(0, 300), ageMin: Math.round((now - j.updatedAt.getTime()) / 60_000) })),
  };

  // DNS (real lookups even in sandbox would leak nothing, but skip there to stay offline)
  const dnsFacts: DiagnosisFacts["dns"] = {
    subdomainHost: null,
    expectedA: null,
    actualA: null,
    expectedSrvPort: null,
    actualSrvPort: null,
    customDomain: server.customDomain && HOST_RE.test(server.customDomain) ? server.customDomain : null,
    customDomainA: null,
  };
  if (server.subdomain) {
    const support = dnsSupportForFamily(family);
    if (support.managed && join) {
      const base = await soft(() => gameSubdomainBase(), 5000);
      if (base) {
        dnsFacts.subdomainHost = `${server.subdomain}.${base}`;
        const target = resolveGameServerDnsTarget({
          status: server.status,
          dedicatedIp: server.dedicatedIp ? { address: server.dedicatedIp.address } : null,
          portForwards: server.portForwards,
          nodePublicIp: node?.publicIp,
          publicIpEnv: process.env.PUBLIC_IP,
          gamePort: join.port,
          gameProtocol: join.protocol,
        });
        dnsFacts.expectedA = target?.ip ?? null;
        dnsFacts.expectedSrvPort = support.includeSrv && target ? target.port : null;
      }
    }
  }

  const base: DiagnosisFacts = {
    sandbox: SANDBOX,
    server: {
      id: server.id,
      hostname: server.hostname,
      status: server.status,
      vmid: server.vmid,
      isGame,
      gameFamily: family,
      provisionError: server.provisionError,
      provisioningStep: server.provisioningStep,
      ipAddress: server.ipAddress,
      sshPort: server.sshPort,
      dedicatedIp: dedicated,
      publicHost,
    },
    node: { name: node?.name ?? null, apiReachable: null, cpuPct: null, memPct: null },
    vm: { pveStatus: null, existsOnNode: null, agentResponding: null, configuredIp: null, memPct: null, cpuPct: null, uptimeSec: null },
    guest: {
      sshReachable: null,
      sshError: null,
      diskPct: null,
      memPct: null,
      load1: null,
      cpuCount: null,
      failedUnits: null,
      oomKillsRecent: null,
      serviceUnit: null,
      serviceState: null,
      containerRestarts: null,
      portBound: null,
      logHighlights: [],
    },
    network: {
      expectedRules,
      missingRules: null,
      joinForwardConfigured: isGame && join && !dedicated ? !!joinForward : null,
      connectAddress,
      joinProtocol: join?.protocol ?? null,
    },
    external: { sshOpen: null, gamePortOpen: null, gamePortError: null, hairpin: !!node?.isPrimary },
    dns: dnsFacts,
    jobs,
  };

  if (SANDBOX) return simulateFacts(base);
  if (!node) return base;

  // ---- Node + VM (Proxmox, read-only) ----
  const client = clientFor(node);
  const ns = await soft(() => client.get(`/nodes/${client.node}/status`), 10_000, "node status");
  base.node.apiReachable = ns != null;
  if (ns) {
    base.node.cpuPct = typeof ns.cpu === "number" ? ns.cpu * 100 : null;
    base.node.memPct = ns.memory?.total ? (ns.memory.used / ns.memory.total) * 100 : null;
  }
  if (server.vmid && ns) {
    try {
      const st = await withTimeout(client.vmStatus(server.vmid), 10_000, "vm status");
      base.vm.existsOnNode = true;
      base.vm.pveStatus = typeof st?.status === "string" ? st.status : null;
      base.vm.cpuPct = typeof st?.cpu === "number" ? st.cpu * 100 : null;
      base.vm.memPct = st?.maxmem ? (st.mem / st.maxmem) * 100 : null;
      base.vm.uptimeSec = typeof st?.uptime === "number" ? st.uptime : null;
    } catch (e) {
      base.vm.existsOnNode = isVmAbsentError(e, server.vmid) ? false : null;
    }
    if (base.vm.existsOnNode) {
      const cfg = await soft(() => client.get(`/nodes/${client.node}/qemu/${server.vmid}/config`), 10_000);
      base.vm.configuredIp = ipFromIpconfig(cfg?.ipconfig0);
      if (base.vm.pveStatus === "running") {
        const ping = await soft(() => client.post(`/nodes/${client.node}/qemu/${server.vmid}/agent/ping`, {}), 8_000);
        base.vm.agentResponding = ping != null;
      }
    }
  }

  // ---- NAT chain on the owning node ----
  if (!dedicated && expectedRules.length) {
    const chain = await readNatChain(node);
    if (chain != null) {
      const have = new Set(parseChainRules(node.natChain, chain).rules.map(ruleKey));
      base.network.missingRules = expectedRules.filter((r) => !have.has(r));
    }
  }

  // ---- Guest (SSH, read-only) ----
  const sftpServer = server as unknown as SftpServer;
  if (base.vm.pveStatus === "running" || base.vm.pveStatus == null) {
    const spec = family && isGameFamily(family) ? controlSpec(family) : null;
    try {
      const out = await withTimeout(
        withServerSsh(sftpServer, (conn) => exec(conn, guestDiagScript(spec?.serviceHints ?? null, spec ? family : null), 25_000)),
