/**
 * ADMIN_OPS job executor — the root-privileged half of the Admin Ops console
 * (app/admin/ops, lib/admin-ops/*).
 *
 * Registered in worker/index.ts's handler map as `ADMIN_OPS: adminOps`. One
 * job type, `payload.op` discriminates. Conventions every op follows:
 *  - The op re-validates its own preconditions from the DB at run time; the
 *    web side's dry-run preview is advisory, never trusted.
 *  - Results land in `payload.result` (JSON) so the UI can poll the row.
 *  - Mutating ops are NEVER auto-retried: a terminal failure sets attempts
 *    past MAX_ATTEMPTS before throwing, so worker/index.ts's runJob marks the
 *    job FAILED instead of re-running a half-finished network change. Each
 *    step is individually idempotent so an admin can safely re-run the op.
 *  - Secrets (root passwords, tokens) never reach `payload.result`; captured
 *    guest output is scrubbed and capped (lib/admin-ops/guest-commands.ts).
 *  - SANDBOX: nothing remote is touched. Diagnose returns a clearly-labelled
 *    simulation built from the DB row; IP ops perform the DB-side swap with
 *    synthetic addresses only; destroys are no-ops.
 */
import { execFile } from "node:child_process";
