} as const;

type LoadedServer = Prisma.ServerGetPayload<{ include: typeof SERVER_INCLUDE }>;

async function loadServer(id: string): Promise<LoadedServer | null> {
  return db.server.findUnique({ where: { id }, include: SERVER_INCLUDE });
}

async function nodeRowFor(server: { node: LoadedServer["node"] }) {
