function clientFor(n: { apiUrl: string; pveNode: string; tokenId: string; tokenSecret: string }): PveClient {
  return pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret });
}

function withTimeout<T>(p: Promise<T>, ms: number, what: string): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const t = setTimeout(() => reject(new Error(`${what} timed out after ${Math.round(ms / 1000)}s`)), ms);
    p.then(
      (v) => {
        clearTimeout(t);
        resolve(v);
      },
      (e) => {
        clearTimeout(t);
        reject(e);
      },
    );
  });
}

async function soft<T>(p: () => Promise<T>, ms = 15_000, what = "check"): Promise<T | null> {
  try {
    return await withTimeout(p(), ms, what);
  } catch {
    return null;
  }
}

function familyOf(s: LoadedServer): GameFamily | null {
  return gameFamilyForServer(s as unknown as { gamePlan?: { gameFamily?: string | null } | null; osTemplate?: { family?: string | null } | null });
}

// ---------------------------------------------------------------------------
// Probes
// ---------------------------------------------------------------------------

function tcpProbe(host: string, port: number, opts: { banner?: boolean; timeoutMs?: number } = {}): Promise<{ ok: boolean; detail: string }> {
  return new Promise((resolve) => {
    const sock = new net.Socket();
    let done = false;
    let buf = "";
    const end = (ok: boolean, detail: string) => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      sock.removeAllListeners();
      sock.destroy();
      resolve({ ok, detail });
    };
    const timer = setTimeout(() => end(false, "timed out"), opts.timeoutMs ?? 6000);
    sock.once("error", (e: NodeJS.ErrnoException) => end(false, e.code ?? e.message));
    sock.once("connect", () => {
      if (!opts.banner) end(true, "connected");
    });
    if (opts.banner) {
      sock.on("data", (c) => {
        buf += c.toString("utf8");
        if (buf.includes("\n") || buf.length > 200) end(buf.startsWith("SSH-"), buf.trim().slice(0, 80));
      });
    }
    sock.connect(port, host);
  });
}

function publicResolver(): dnsp.Resolver {
  const r = new dnsp.Resolver({ timeout: 4000, tries: 2 });
  // Never trust the local resolver for "what does the internet see" — see
  // MEMORY.md's DKIM incident. Ask two public resolvers.
  r.setServers(["1.1.1.1", "8.8.8.8"]);
  return r;
}

const HOST_RE = /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/i;

// ---------------------------------------------------------------------------
// op: diagnose
