    },
    node: { name: node?.name ?? null, apiReachable: null, cpuPct: null, memPct: null },
    vm: { pveStatus: null, existsOnNode: null, agentResponding: null, configuredIp: null, memPct: null, cpuPct: null, uptimeSec: null },
    guest: {
      sshReachable: null,
      sshError: null,
      diskPct: null,
      memPct: null,
      load1: null,
      cpuCount: null,
      failedUnits: null,
      oomKillsRecent: null,
      serviceUnit: null,
      serviceState: null,
      containerRestarts: null,
      portBound: null,
      logHighlights: [],
    },
    network: {
      expectedRules,
      missingRules: null,
      joinForwardConfigured: isGame && join && !dedicated ? !!joinForward : null,
      connectAddress,
      joinProtocol: join?.protocol ?? null,
    },
    external: { sshOpen: null, gamePortOpen: null, gamePortError: null, hairpin: !!node?.isPrimary },
    dns: dnsFacts,
    jobs,
  };

  if (SANDBOX) return simulateFacts(base);
  if (!node) return base;

  // ---- Node + VM (Proxmox, read-only) ----
  const client = clientFor(node);
  const ns = await soft(() => client.get(`/nodes/${client.node}/status`), 10_000, "node status");
  base.node.apiReachable = ns != null;
  if (ns) {
    base.node.cpuPct = typeof ns.cpu === "number" ? ns.cpu * 100 : null;
    base.node.memPct = ns.memory?.total ? (ns.memory.used / ns.memory.total) * 100 : null;
  }
  if (server.vmid && ns) {
    try {
      const st = await withTimeout(client.vmStatus(server.vmid), 10_000, "vm status");
      base.vm.existsOnNode = true;
      base.vm.pveStatus = typeof st?.status === "string" ? st.status : null;
      base.vm.cpuPct = typeof st?.cpu === "number" ? st.cpu * 100 : null;
      base.vm.memPct = st?.maxmem ? (st.mem / st.maxmem) * 100 : null;
      base.vm.uptimeSec = typeof st?.uptime === "number" ? st.uptime : null;
    } catch (e) {
      base.vm.existsOnNode = isVmAbsentError(e, server.vmid) ? false : null;
    }
    if (base.vm.existsOnNode) {
      const cfg = await soft(() => client.get(`/nodes/${client.node}/qemu/${server.vmid}/config`), 10_000);
      base.vm.configuredIp = ipFromIpconfig(cfg?.ipconfig0);
      if (base.vm.pveStatus === "running") {
        const ping = await soft(() => client.post(`/nodes/${client.node}/qemu/${server.vmid}/agent/ping`, {}), 8_000);
        base.vm.agentResponding = ping != null;
      }
    }
  }

  // ---- NAT chain on the owning node ----
  if (!dedicated && expectedRules.length) {
    const chain = await readNatChain(node);
    if (chain != null) {
      const have = new Set(parseChainRules(node.natChain, chain).rules.map(ruleKey));
      base.network.missingRules = expectedRules.filter((r) => !have.has(r));
    }
  }

  // ---- Guest (SSH, read-only) ----
  const sftpServer = server as unknown as SftpServer;
  if (base.vm.pveStatus === "running" || base.vm.pveStatus == null) {
    const spec = family && isGameFamily(family) ? controlSpec(family) : null;
    try {
      const out = await withTimeout(
        withServerSsh(sftpServer, (conn) => exec(conn, guestDiagScript(spec?.serviceHints ?? null, spec ? family : null), 25_000)),
        45_000,
        "guest diagnostics",
      );
      const g = parseGuestDiag(out.stdout);
      base.guest.sshReachable = true;
      base.guest.load1 = g.load1;
      base.guest.cpuCount = g.cpuCount;
      base.guest.memPct = g.memPct;
      base.guest.diskPct = g.diskPct;
      base.guest.failedUnits = g.failedUnits;
      base.guest.oomKillsRecent = g.oom;
      base.guest.serviceUnit = g.unit;
      base.guest.serviceState = g.unit ? g.state : null;
      base.guest.containerRestarts = g.restarts;
      const pw = serverRootPassword(server);
      base.guest.logHighlights = logHighlights(g.logLines).map((l) => (pw ? l.split(pw).join("***") : l));
    } catch (e) {
      base.guest.sshReachable = false;
      base.guest.sshError = String((e as Error)?.message ?? e).slice(0, 200);
    }
    if (join && base.guest.sshReachable) {
      base.guest.portBound = await soft(() => gamePortBoundInGuest(sftpServer as never, join.port, join.protocol), 25_000);
    }
  }

  // ---- External reachability ----
  const sshTarget = dedicated ? { host: dedicated, port: server.guestSshPort ?? 22 } : publicHost && server.sshPort ? { host: publicHost, port: server.sshPort } : null;
  if (sshTarget) base.external.sshOpen = (await tcpProbe(sshTarget.host, sshTarget.port, { banner: true })).ok;
  if (join && connectAddress) {
    const [h, p] = [connectAddress.slice(0, connectAddress.lastIndexOf(":")), Number(connectAddress.slice(connectAddress.lastIndexOf(":") + 1))];
    if (join.protocol === "tcp") {
      const r = await tcpProbe(h, p);
      base.external.gamePortOpen = r.ok;
      base.external.gamePortError = r.ok ? null : r.detail;
    } else {
      const bound = base.guest.portBound;
      const r = await soft(
        () => checkGamePortOpen(h, p, "udp", { timeoutMs: 6_000, intervalMs: 3_000, verifyBound: async () => bound }),
        12_000,
      );
      base.external.gamePortOpen = r ? r.ok : null;
      base.external.gamePortError = r && !r.ok ? String((r as { error?: string }).error ?? "no answer") : null;
    }
  }

  // ---- DNS (public resolvers) ----
  const resolver = publicResolver();
  if (dnsFacts.subdomainHost) {
    dnsFacts.actualA = (await soft(() => resolver.resolve4(dnsFacts.subdomainHost!), 9_000)) ?? [];
    if (dnsFacts.expectedSrvPort != null) {
      const srv = await soft(() => resolver.resolveSrv(`_minecraft._tcp.${dnsFacts.subdomainHost}`), 9_000);
      dnsFacts.actualSrvPort = srv?.[0]?.port ?? null;
    }
  }
  if (dnsFacts.customDomain) {
    dnsFacts.customDomainA = (await soft(() => resolver.resolve4(dnsFacts.customDomain!), 9_000)) ?? [];
  }

  return base;
}

/**
 * SANDBOX: a plausible, clearly-labelled simulation derived from the DB row,
 * so the console can be exercised end to end without any real host. A server
 * the DB marks STOPPED/ERROR simulates as powered off; everything else as up.
 */
function simulateFacts(f: DiagnosisFacts): DiagnosisFacts {
  const up = f.server.status === "RUNNING";
  f.node = { ...f.node, apiReachable: true, cpuPct: 31, memPct: 64 };
  if (f.server.vmid) {
    f.vm = { pveStatus: up ? "running" : "stopped", existsOnNode: true, agentResponding: up, configuredIp: f.server.ipAddress, memPct: up ? 48 : null, cpuPct: up ? 7 : null, uptimeSec: up ? 86_400 : null };
  }
  if (up) {
    f.guest = {
      ...f.guest,
      sshReachable: true,
      diskPct: 37,
      memPct: 52,
      load1: 0.32,
      cpuCount: 2,
      failedUnits: [],
      oomKillsRecent: 0,
      serviceUnit: f.server.isGame ? `${f.server.gameFamily ?? "game"}.service` : null,
      serviceState: f.server.isGame ? "active" : null,
      containerRestarts: f.server.isGame ? 0 : null,
      portBound: f.server.isGame ? true : null,
    };
    f.network.missingRules = [];
    f.external = { ...f.external, sshOpen: true, gamePortOpen: f.server.isGame ? !!f.network.connectAddress : null };
  }
  if (f.dns.subdomainHost) {
    f.dns.actualA = f.dns.expectedA ? [f.dns.expectedA] : [];
    f.dns.actualSrvPort = f.dns.expectedSrvPort;
  }
  if (f.dns.customDomain) f.dns.customDomainA = [];
  return f;
}

async function opDiagnose(job: Job, p: DiagnosePayload): Promise<void> {
  const server = await loadServer(p.serverId);
  if (!server) return failTerminal(job, "Server not found.");
  await step(job, "Collecting facts (DB, Proxmox, NAT, guest, probes, DNS)…", 10);
  const facts = await gatherDiagnosisFacts(server, { excludeJobId: job.id });
  const result = evaluateDiagnosis(facts);
  await finish(job, { ok: true, diagnosis: result, facts });
  await audit(p.requestedBy, "adminops.diagnose", `${server.hostname} verdict=${result.verdict} top=${result.causes[0]?.key ?? "none"}`);
}

// ---------------------------------------------------------------------------
// op: guest_cmd
// ---------------------------------------------------------------------------

async function opGuestCmd(job: Job, p: GuestCmdPayload): Promise<void> {
  const server = await loadServer(p.serverId);
  if (!server) return failTerminal(job, "Server not found.");
  let built;
  try {
    built = buildGuestCommand(p.command, p.params ?? {});
  } catch (e) {
    return failTerminal(job, String((e as Error).message));
  }
  await step(job, `Running "${built.command.label}" on ${server.hostname}…`, 20);
  if (SANDBOX) {
    await finish(job, {
      ok: true,
      command: built.command.key,
      label: built.command.label,
      exitCode: 0,
      output: `[sandbox] Would run on ${server.hostname}:\n\n${built.script}\n\n(no guest was contacted)`,
      truncated: false,
    });
    return;
  }
  if (server.status !== "RUNNING") return failTerminal(job, `${server.hostname} is ${server.status} — the VM must be running.`);
  try {
    const r = await withServerSsh(server as unknown as SftpServer, (conn) => exec(conn, built.script, built.command.timeoutSec * 1000));
    const pw = serverRootPassword(server);
    const out = capOutput(`${r.stdout}${r.stderr ? `\n[stderr]\n${r.stderr}` : ""}`, [pw]);
    await finish(job, { ok: true, command: built.command.key, label: built.command.label, exitCode: r.code, output: out.text, truncated: out.truncated });
    await audit(p.requestedBy, "adminops.guest_cmd", `${server.hostname} ${built.command.key} rc=${r.code}`);
  } catch (e) {
    return failTerminal(job, `Could not run on ${server.hostname}: ${String((e as Error)?.message ?? e).slice(0, 200)}`);
  }
}

// ---------------------------------------------------------------------------
// Network reconfiguration helpers (same sequence as worker/index.ts's
// assignDedicatedIp / unsuspend NAT fallback — duplicated deliberately small
// because those are module-private there).
// ---------------------------------------------------------------------------

async function powerOff(conn: PveClient, vmid: number): Promise<void> {
  try {
    const st = await conn.vmStatus(vmid);
    if (st?.status === "stopped") return;
  } catch {
    /* fall through to stop */
  }
  try {
    const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/shutdown`, { timeout: 60 });
    await conn.waitForTask(upid, 120_000);
  } catch {
    const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
    await conn.waitForTask(upid);
  }
}

async function powerOn(conn: PveClient, vmid: number): Promise<void> {
  try {
    const st = await conn.vmStatus(vmid);
    if (st?.status === "running") return;
  } catch {
    /* try start anyway */
  }
  const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
  await conn.waitForTask(upid);
}

type NodeRow = NonNullable<Awaited<ReturnType<typeof nodeRowFor>>>;

/** Put a server (whose dedicated IP has just been released) onto shared NAT. */
async function moveToNat(conn: PveClient, server: LoadedServer, nodeRow: NodeRow): Promise<{ ip: string; sshPort: number }> {
  const fresh = await db.server.findUnique({ where: { id: server.id }, select: { ipAddress: true, sshPort: true } });
  const ip = fresh?.ipAddress && fresh.ipAddress.startsWith(nodeRow.subnetPrefix) ? fresh.ipAddress : await allocateIp(server.nodeId, server.id);
  const sshPort = fresh?.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
  if (!SANDBOX && server.vmid) {
    await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
      net0: `virtio,bridge=${nodeRow.bridge ?? "vmbr1"}`,
      ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow.subnetPrefix)}`,
    });
  }
  await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort, wantsDedicatedIp: false } });
  // A NAT game server needs its join port(s) forwarded; reuse rows from an
  // earlier NAT life rather than burning new public ports.
  const fam = familyOf(server);
  if (fam) {
    for (const port of joinPortsFor(fam)) {
      const already = await db.portForward.findFirst({ where: { serverId: server.id, guestPort: port.port, protocol: port.protocol }, select: { id: true } });
      if (!already) await allocateGameForward(server.nodeId, server.id, port.port, port.protocol).catch((e) => console.error(`[admin-ops] forward ${port.protocol}/${port.port} for ${server.hostname} failed`, e));
    }
  }
  return { ip, sshPort };
}

async function claimSpecificIp(serverId: string, address: string, nodeId: string): Promise<boolean> {
  // FREE → PENDING for exactly this row, then allocateDedicatedIp's own
  // idempotent "mine" path cannot see it as ASSIGNED yet, so we hand it the
  // row through the same function by pre-binding serverId. allocateDedicatedIp
  // only re-uses a row that is ASSIGNED; for a PENDING row bound to us it
  // would claim a DIFFERENT free one — hence the `preferAddress` option.
  const r = await db.dedicatedIp.updateMany({
    where: { address, nodeId, status: "FREE", purpose: "CUSTOMER", serverId: null },
    data: { status: "FREE" },
  });
  return r.count === 1;
}

async function giveDedicated(conn: PveClient, server: LoadedServer, nodeRow: NodeRow, address: string | null, billable: boolean): Promise<string> {
  if (SANDBOX) {
    const ip = address ?? (await db.dedicatedIp.findFirst({ where: { nodeId: nodeRow.id, status: "FREE", purpose: "CUSTOMER" }, orderBy: { createdAt: "asc" } }))?.address;
    if (!ip) throw new TerminalOpError("No FREE IP in the pool (sandbox).");
    await db.$transaction([
      db.dedicatedIp.update({ where: { address: ip }, data: { status: "ASSIGNED", serverId: server.id } }),
      db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort: null, wantsDedicatedIp: billable } }),
    ]);
    return ip;
  }
  if (!server.vmid) throw new TerminalOpError(`${server.hostname} has no VM.`);
  if (address && !(await claimSpecificIp(server.id, address, nodeRow.id))) {
    throw new TerminalOpError(`${address} is no longer FREE on ${nodeRow.name}.`);
  }
  const d = await allocateDedicatedIp(server.id, server.vmid, nodeRow.id, address ? { preferAddress: address } : undefined);
  if (!d) throw new TerminalOpError(`No FREE customer IP available on ${nodeRow.name} (or its provider API isn't configured).`);
  if (address && d.address !== address) {
    // Should be impossible with preferAddress; never silently hand out a different IP.
    await releaseDedicatedIp(server.id).catch(() => {});
    throw new TerminalOpError(`Allocator returned ${d.address} instead of ${address} — rolled back.`);
  }
  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
    net0: d.virtualMac ? `virtio=${d.virtualMac},bridge=vmbr0` : `virtio,bridge=vmbr0`,
    ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
  });
  await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null, wantsDedicatedIp: billable } });
  return d.address;
}

function ipOpServer(s: LoadedServer, inflight: boolean, nodeName: string | null): IpOpServer {
  return {
    id: s.id,
    hostname: s.hostname,
    status: s.status,
    vmid: s.vmid,
    nodeId: s.nodeId,
    nodeName,
    isGame: !!s.gamePlanId,
    wantsDedicatedIp: s.wantsDedicatedIp,
    hasInflightJob: inflight,
    dedicatedIp: s.dedicatedIp ? { id: s.dedicatedIp.id, address: s.dedicatedIp.address, status: s.dedicatedIp.status, nodeId: s.dedicatedIp.nodeId } : null,
  };
}

async function inflight(serverId: string, excludeJobId: string): Promise<boolean> {
  return (await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, id: { not: excludeJobId } } })) > 0;
}

async function afterNetworkChange(serverIds: string[], context: string): Promise<string | null> {
  if (SANDBOX) return null;
  const err = await syncPortForwardsBestEffort(context);
  for (const id of serverIds) {
    const s = await db.server.findUnique({ where: { id }, select: { subdomain: true } });
    if (s?.subdomain) await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId: id } });
  }
  return err ? String(err.message ?? err).slice(0, 300) : null;
}

// ---------------------------------------------------------------------------
// op: ip_reassign (same node)
// ---------------------------------------------------------------------------

async function opIpReassign(job: Job, p: IpReassignPayload): Promise<void> {
  const [src, tgt] = await Promise.all([loadServer(p.sourceServerId), loadServer(p.targetServerId)]);
  if (!src || !tgt) return failTerminal(job, "Source or target server not found.");
  const nodeRow = await nodeRowFor(src);
  if (!nodeRow) return failTerminal(job, "No node row.");
  const plan = planIpReassign(
    ipOpServer(src, await inflight(src.id, job.id), nodeRow.name),
    ipOpServer(tgt, await inflight(tgt.id, job.id), tgt.node?.name ?? null),
  );
  if (!plan.ok) return failTerminal(job, plan.error);
  const address = src.dedicatedIp!.address;
  const conn = clientFor(nodeRow);
  const srcWasRunning = src.status === "RUNNING";
  const tgtWasRunning = tgt.status === "RUNNING";
  const log: string[] = [];
  try {
    await step(job, `Stopping ${src.hostname}…`, 10);
    if (!SANDBOX && src.vmid && srcWasRunning) await powerOff(conn, src.vmid);
    log.push(`${src.hostname} stopped`);

    await step(job, `Releasing ${address} from ${src.hostname}…`, 25);
    if (SANDBOX) {
      await db.dedicatedIp.update({ where: { address }, data: { status: "FREE", serverId: null, virtualMac: null } });
      await db.server.updateMany({ where: { id: src.id, ipAddress: address }, data: { ipAddress: null, ipv6: null } });
    } else {
      await releaseDedicatedIp(src.id);
    }
    log.push(`${address} released`);

    await step(job, `Moving ${src.hostname} to NAT…`, 40);
    const nat = await moveToNat(conn, src, nodeRow);
    log.push(`${src.hostname} → NAT ${nat.ip} ssh :${nat.sshPort}`);

    await step(job, `Assigning ${address} to ${tgt.hostname}…`, 55);
    if (!SANDBOX && tgt.vmid && tgtWasRunning) await powerOff(conn, tgt.vmid);
    const given = await giveDedicated(conn, tgt, nodeRow, address, true);
    log.push(`${given} → ${tgt.hostname}`);

    await step(job, "Starting servers…", 75);
    if (!SANDBOX && tgt.vmid && tgtWasRunning) await powerOn(conn, tgt.vmid);
    if (!SANDBOX && src.vmid && srcWasRunning) await powerOn(conn, src.vmid);

    await step(job, "Re-syncing NAT + DNS…", 90);
    const natErr = await afterNetworkChange([src.id, tgt.id], `ip reassign ${address} ${src.hostname}->${tgt.hostname}`);
    if (natErr) log.push(`NAT sync warning: ${natErr}`);

    await notifyOwner(src.userId, `Network change on ${src.hostname}`, `Your server now connects via a shared address (${nodeRow.publicIp}:${nat.sshPort} for SSH). Open the server page for the new connection details.`, `/dashboard/servers/${src.id}`);
    await notifyOwner(tgt.userId, `Dedicated IP added to ${tgt.hostname}`, `Your server now connects on ${given}.`, `/dashboard/servers/${tgt.id}`);
    await audit(p.requestedBy, "adminops.ip_reassign", `${address} ${src.hostname} -> ${tgt.hostname} reason="${p.reason ?? ""}"`);
    await finish(job, { ok: true, address, log });
  } catch (e) {
    if (e instanceof TerminalOpError) return failTerminal(job, e.message, { ok: false, error: e.message, log });
    const msg = String((e as Error)?.message ?? e).slice(0, 300);
    // Best effort: never leave a stopped customer VM behind.
    if (!SANDBOX) {
      if (src.vmid && srcWasRunning) await powerOn(conn, src.vmid).catch(() => {});
      if (tgt.vmid && tgtWasRunning) await powerOn(conn, tgt.vmid).catch(() => {});
    }
    await audit(p.requestedBy, "adminops.ip_reassign.failed", `${address} ${src.hostname} -> ${tgt.hostname}: ${msg}`);
    return failTerminal(job, msg, { ok: false, error: msg, log, hint: "Every step is idempotent — run Diagnose on both servers, then re-run the reassign." });
  }
}

// ---------------------------------------------------------------------------
// op: ip_release / ip_assign (single server; job.serverId is set)
// ---------------------------------------------------------------------------

async function opIpRelease(job: Job, p: IpReleasePayload): Promise<void> {
  const s = await loadServer(p.serverId);
  if (!s) return failTerminal(job, "Server not found.");
  const nodeRow = await nodeRowFor(s);
  if (!nodeRow) return failTerminal(job, "No node row.");
  const plan = planIpRelease(ipOpServer(s, await inflight(s.id, job.id), nodeRow.name));
  if (!plan.ok) return failTerminal(job, plan.error);
  const address = s.dedicatedIp!.address;
  const conn = clientFor(nodeRow);
  const wasRunning = s.status === "RUNNING";
  try {
    await step(job, `Stopping ${s.hostname}…`, 15);
    if (!SANDBOX && s.vmid && wasRunning) await powerOff(conn, s.vmid);
    await step(job, `Releasing ${address}…`, 35);
    if (SANDBOX) {
      await db.dedicatedIp.update({ where: { address }, data: { status: "FREE", serverId: null, virtualMac: null } });
      await db.server.updateMany({ where: { id: s.id, ipAddress: address }, data: { ipAddress: null, ipv6: null } });
    } else {
      await releaseDedicatedIp(s.id);
    }
    const nat = await moveToNat(conn, s, nodeRow);
    await step(job, "Starting + re-syncing…", 75);
    if (!SANDBOX && s.vmid && wasRunning) await powerOn(conn, s.vmid);
    const natErr = await afterNetworkChange([s.id], `ip release ${s.hostname}`);
    await notifyOwner(s.userId, `Network change on ${s.hostname}`, `Your server's dedicated IP was removed; it now connects via ${nodeRow.publicIp}:${nat.sshPort} for SSH.`, `/dashboard/servers/${s.id}`);
    await audit(p.requestedBy, "adminops.ip_release", `${address} from ${s.hostname} reason="${p.reason ?? ""}"`);
    await finish(job, { ok: true, address, nat, warning: natErr });
  } catch (e) {
    if (!SANDBOX && s.vmid && wasRunning) await powerOn(conn, s.vmid).catch(() => {});
    const msg = e instanceof TerminalOpError ? e.message : String((e as Error)?.message ?? e).slice(0, 300);
    return failTerminal(job, msg);
  }
}

async function opIpAssign(job: Job, p: IpAssignPayload): Promise<void> {
  const s = await loadServer(p.serverId);
  if (!s) return failTerminal(job, "Server not found.");
  const nodeRow = await nodeRowFor(s);
  if (!nodeRow) return failTerminal(job, "No node row.");
  const free = (await db.dedicatedIp.findMany({ where: { nodeId: nodeRow.id, status: "FREE", purpose: "CUSTOMER", serverId: null }, orderBy: { createdAt: "asc" }, select: { address: true } })).map((r) => r.address);
  const plan = planIpAssign(ipOpServer(s, await inflight(s.id, job.id), nodeRow.name), p.address ?? null, free);
  if (!plan.ok) return failTerminal(job, plan.error);
  const conn = clientFor(nodeRow);
  const wasRunning = s.status === "RUNNING";
  try {
    await step(job, `Stopping ${s.hostname}…`, 15);
    if (!SANDBOX && s.vmid && wasRunning) await powerOff(conn, s.vmid);
    await step(job, "Claiming the IP…", 40);
    const ip = await giveDedicated(conn, s, nodeRow, p.address ?? null, p.billable);
    await step(job, "Starting + re-syncing…", 75);
    if (!SANDBOX && s.vmid && wasRunning) await powerOn(conn, s.vmid);
    const natErr = await afterNetworkChange([s.id], `ip assign ${s.hostname}`);
    await notifyOwner(s.userId, `Dedicated IP added to ${s.hostname}`, `Your server now connects on ${ip}.`, `/dashboard/servers/${s.id}`);
    await audit(p.requestedBy, "adminops.ip_assign", `${ip} -> ${s.hostname} billable=${p.billable} reason="${p.reason ?? ""}"`);
    await finish(job, { ok: true, address: ip, warning: natErr });
  } catch (e) {
    if (!SANDBOX && s.vmid && wasRunning) await powerOn(conn, s.vmid).catch(() => {});
    const msg = e instanceof TerminalOpError ? e.message : String((e as Error)?.message ?? e).slice(0, 300);
    return failTerminal(job, msg);
  }
}

// ---------------------------------------------------------------------------
// op: drift_scan + cleanups
// ---------------------------------------------------------------------------

async function opDriftScan(job: Job): Promise<void> {
  const nodes = await db.node.findMany({ orderBy: { createdAt: "asc" } });
  const vmsByNode: Record<string, PveVm[] | null> = {};
  let i = 0;
  for (const n of nodes) {
    await step(job, `Reading VMs on ${n.name}…`, Math.round((i++ / Math.max(nodes.length, 1)) * 70));
    if (SANDBOX) {
      const rows = await db.server.findMany({ where: { OR: [{ nodeId: n.id }, ...(n.isPrimary ? [{ nodeId: null }] : [])], vmid: { not: null } }, select: { vmid: true, hostname: true, status: true } });
      vmsByNode[n.id] = [
        ...rows.map((r) => ({ vmid: r.vmid!, name: r.hostname, status: r.status === "RUNNING" ? "running" : "stopped", tags: "nxeon" })),
        { vmid: 9000, template: 1 },
        { vmid: 9001, template: 1 },
      ];
      continue;
    }
    vmsByNode[n.id] = await soft(async () => {
      const list = await clientFor(n).get(`/nodes/${n.pveNode}/qemu`);
      return (Array.isArray(list) ? list : []).map((v: any) => ({ vmid: Number(v.vmid), name: v.name, status: v.status, tags: v.tags, template: v.template }));
    }, 20_000);
  }
  await step(job, "Comparing with the database…", 80);
  const [servers, ips, archives, templates, inflightRows] = await Promise.all([
    db.server.findMany({ select: { id: true, hostname: true, vmid: true, nodeId: true, status: true, ipAddress: true, updatedAt: true } }),
    db.dedicatedIp.findMany({ select: { id: true, address: true, status: true, serverId: true, nodeId: true, purpose: true } }),
    db.serverArchive.findMany({ where: { vmid: { not: null } }, select: { vmid: true, hostname: true, deletedAt: true }, orderBy: { deletedAt: "desc" }, take: 2000 }),
    db.osTemplate.findMany({ where: { active: true }, select: { vmid: true, baseVmid: true } }),
    db.job.findMany({ where: { status: { in: ["QUEUED", "RUNNING"] }, serverId: { not: null } }, select: { serverId: true } }),
  ]);
  const busy = new Set(inflightRows.map((r) => r.serverId!));
  const archivedByVmid: Record<number, { hostname: string; deletedAt: Date }> = {};
  for (const a of archives) if (a.vmid != null && !archivedByVmid[a.vmid]) archivedByVmid[a.vmid] = { hostname: a.hostname, deletedAt: a.deletedAt };
  const templateVmids = [...new Set(templates.flatMap((t) => [t.vmid, t.baseVmid].filter((v): v is number => typeof v === "number" && v >= 9000 && v <= 9999)))].sort((a, b) => a - b);
  const findings = detectDrift({
    nodes: nodes.map((n) => ({ id: n.id, name: n.name, isPrimary: n.isPrimary, enabled: n.enabled, acceptsProvisions: n.acceptsProvisions })),
    vmsByNode,
    servers: servers.map((s) => ({ ...s, hasInflightJob: busy.has(s.id) })),
    dedicatedIps: ips,
    archivedByVmid,
    templateVmids,
    prodTag: process.env.NXEON_TAG ?? "nxeon",
  });
  await finish(job, {
    ok: true,
    findings,
    scannedNodes: nodes.map((n) => ({ id: n.id, name: n.name, vms: vmsByNode[n.id]?.length ?? null })),
    templateVmids,
  });
}

async function opOrphanVmDestroy(job: Job, p: OrphanVmDestroyPayload): Promise<void> {
  const node = await db.node.findUnique({ where: { id: p.nodeId } });
  if (!node) return failTerminal(job, "Node not found.");
  if (!Number.isInteger(p.vmid) || p.vmid < 100 || (p.vmid >= 9000 && p.vmid <= 9999)) return failTerminal(job, "Refusing: templates (9000-9999) and system vmids are never destroyed.");
  const owner = await db.server.findFirst({ where: { vmid: p.vmid }, select: { hostname: true } });
  if (owner) return failTerminal(job, `Refusing: vmid ${p.vmid} belongs to server ${owner.hostname} — delete it through its DELETE job.`);
  if (SANDBOX) {
    await audit(p.requestedBy, "adminops.orphan_vm_destroy", `(sandbox) ${node.name} vmid ${p.vmid}`);
    return finish(job, { ok: true, detail: `[sandbox] VM ${p.vmid} on ${node.name} would be destroyed.` });
  }
  const conn = clientFor(node);
  // Re-verify at run time: still platform-tagged, still stopped, still unowned.
  const cfg = await soft(() => conn.get(`/nodes/${conn.node}/qemu/${p.vmid}/config`), 10_000);
  const st = await soft(() => conn.vmStatus(p.vmid), 10_000);
  if (!cfg || !st) return failTerminal(job, `VM ${p.vmid} could not be read on ${node.name} (already gone?).`);
  const tags = String(cfg.tags ?? "").split(/[;,\s]+/).map((t: string) => t.toLowerCase());
  const prodTag = (process.env.NXEON_TAG ?? "nxeon").toLowerCase();
  if (!tags.includes(prodTag)) return failTerminal(job, `Refusing: VM ${p.vmid} is not tagged "${prodTag}" — it is not a platform VM.`);
  if (cfg.template) return failTerminal(job, "Refusing: that VM is a template.");
  if (st.status !== "stopped") return failTerminal(job, `Refusing: VM ${p.vmid} is ${st.status}. Stop it deliberately first.`);
  const host: VmDestroyHost = {
    probe: async (id) => {
      try {
        await conn.vmStatus(id);
        return "present";
      } catch (e) {
        return isVmAbsentError(e, id) ? "absent" : "unknown";
      }
    },
    stop: async () => {
      /* verified stopped above */
    },
    destroy: async (id) => {
      const upid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, { "destroy-unreferenced-disks": 1, purge: 1 });
      await conn.waitForTask(upid, 600_000);
    },
  };
  await step(job, `Destroying VM ${p.vmid} on ${node.name}…`, 50);
  const outcome = await destroyVmIdempotent(host, p.vmid);
  await audit(p.requestedBy, "adminops.orphan_vm_destroy", `${node.name} vmid ${p.vmid}: ${outcome.detail} reason="${p.reason ?? ""}"`);
  await finish(job, { ok: true, detail: outcome.detail });
}

async function opOrphanIpRelease(job: Job, p: OrphanIpReleasePayload): Promise<void> {
  const ip = await db.dedicatedIp.findUnique({ where: { id: p.ipId }, include: { node: true } });
  if (!ip) return failTerminal(job, "IP row not found.");
  const holder = await db.server.findFirst({ where: { ipAddress: ip.address }, select: { hostname: true } });
  if (holder) return failTerminal(job, `Refusing: ${holder.hostname} still holds ${ip.address}.`);
  if (ip.serverId) {
    const owner = await db.server.findUnique({ where: { id: ip.serverId }, select: { hostname: true } });
    if (owner) return failTerminal(job, `Refusing: ${owner.hostname} still owns this row — use IP release on that server.`);
  }
  if (!SANDBOX) {
    // A live whole-IP DNAT on its node means infrastructure is using it.
    const live = ip.node.isPrimary
      ? await soft(async () => {
          const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"], { timeout: 10_000 });
          return stdout.split("\n").some((l) => l.includes(`-d ${ip.address}/32`) && l.includes("-j DNAT"));
        })
      : await soft(() => agentHasLiveDnatRule(ip.node, ip.address));
    if (live) return failTerminal(job, `Refusing: ${ip.address} is the target of a live DNAT rule on ${ip.node.name} (infrastructure is using it). Mark it INTERNAL instead.`);
  }
  // Clear the row. If it still carried a server id that no longer exists, the
  // FK is SetNull already; go through releaseDedicatedIp only when a vMAC needs
  // removing and a (now-missing) server id is recorded — otherwise a plain reset.
  await db.dedicatedIp.update({ where: { id: ip.id }, data: { status: "FREE", serverId: null, virtualMac: ip.node.provider === "HETZNER" ? ip.virtualMac : null } });
  await audit(p.requestedBy, "adminops.orphan_ip_release", `${ip.address} on ${ip.node.name} reason="${p.reason ?? ""}"${ip.virtualMac && ip.node.provider === "OVH" ? " (OVH vMAC left in place — remove it in the OVH panel if still bound)" : ""}`);
  await finish(job, { ok: true, address: ip.address, note: ip.virtualMac && ip.node.provider === "OVH" ? "The row recorded an OVH virtual MAC; it was not removed via API (no owning server). Check the OVH panel." : null });
}

// ---------------------------------------------------------------------------
// op: bulk_power
// ---------------------------------------------------------------------------

async function opBulkPower(job: Job, p: BulkPowerPayload): Promise<void> {
  let children: ChildState[] = p.children ?? [];
  if (!children.length) {
    const servers = await db.server.findMany({
      where: { id: { in: p.serverIds } },
      select: { id: true, hostname: true, status: true, gamePlanId: true, isFree: true, user: { select: { role: true, excludeFromRevenue: true } } },
    });
    const busy = new Set((await db.job.findMany({ where: { serverId: { in: p.serverIds }, status: { in: ["QUEUED", "RUNNING"] } }, select: { serverId: true } })).map((r) => r.serverId!));
    children = p.serverIds.map((id) => {
      const s = servers.find((x) => x.id === id);
      if (!s) return { serverId: id, jobId: null, skipped: "not found" };
      const why = bulkIneligible(p.action, {
        id: s.id,
        hostname: s.hostname,
        status: s.status,
        isGame: !!s.gamePlanId,
        hasInflightJob: busy.has(s.id),
        ownerIsStaff: s.user.role !== "CUSTOMER",
        ownerExcludedFromRevenue: s.user.excludeFromRevenue,
        isFree: s.isFree,
      });
      return { serverId: id, jobId: null, skipped: why ?? undefined };
    });
    await patchPayload(job, { children });
  }
  const spec = childJobFor(p.action);
  const deadline = Date.now() + 6 * 3600_000;
  for (;;) {
    // Refresh child statuses.
    const ids = children.filter((c) => c.jobId).map((c) => c.jobId!);
    const rows = ids.length ? await db.job.findMany({ where: { id: { in: ids } }, select: { id: true, status: true } }) : [];
    for (const c of children) if (c.jobId) c.status = rows.find((r) => r.id === c.jobId)?.status ?? "DONE";
    if (bulkDone(children)) break;
    for (const serverId of nextWave(children, p.concurrency)) {
      const c = children.find((x) => x.serverId === serverId)!;
      const created = await withServerJobLock(serverId, async (tx) => {
        const pending = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
        if (pending > 0) return null;
        if (spec.type === "DELETE") await tx.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
        return tx.job.create({ data: { type: spec.type, serverId, ...(spec.payload ? { payload: spec.payload as Prisma.InputJsonValue } : {}) }, select: { id: true } });
      });
      if (created) {
        c.jobId = created.id;
        c.status = "QUEUED";
      } else {
        c.skipped = "another job appeared before its turn";
      }
    }
    const done = children.filter((c) => c.skipped || c.status === "DONE" || c.status === "FAILED").length;
    await patchPayload(job, { children });
    await step(job, `${done}/${children.length} finished`, Math.round((done / Math.max(children.length, 1)) * 100));
    if (Date.now() > deadline) return failTerminal(job, "Bulk run exceeded 6h — remaining children left as they are.", { ok: false, children });
    await new Promise((r) => setTimeout(r, 4000));
  }
  const summary = {
    ok: true,
    action: p.action,
    done: children.filter((c) => c.status === "DONE").length,
    failed: children.filter((c) => c.status === "FAILED").length,
    skipped: children.filter((c) => c.skipped).length,
    children,
  };
  await audit(p.requestedBy, "adminops.bulk_power", `${p.action} x${children.length}: done=${summary.done} failed=${summary.failed} skipped=${summary.skipped} reason="${p.reason ?? ""}"`);
  await finish(job, summary);
}

// ---------------------------------------------------------------------------
// Dispatcher
// ---------------------------------------------------------------------------

export async function adminOps(job: Job): Promise<void> {
  const p = (job.payload ?? {}) as unknown as AdminOpPayload;
  switch (p.op) {
    case "diagnose":
      return opDiagnose(job, p);
    case "guest_cmd":
      return opGuestCmd(job, p);
    case "ip_reassign":
      return opIpReassign(job, p);
    case "ip_release":
      return opIpRelease(job, p);
    case "ip_assign":
      return opIpAssign(job, p);
    case "drift_scan":
      return opDriftScan(job);
    case "orphan_vm_destroy":
      return opOrphanVmDestroy(job, p);
    case "orphan_ip_release":
      return opOrphanIpRelease(job, p);
    case "bulk_power":
      return opBulkPower(job, p);
    default:
      return failTerminal(job, `Unknown admin op: ${String((p as { op?: unknown }).op).slice(0, 40)}`);
  }
}

