"use server";

/**
 * Admin Ops console — server actions. Every export is a network-reachable
 * endpoint, so every one of them:
 *   1. gates on requireArea(...) FIRST (fleet = ADMIN-only today; billing for
 *      money ops), and refuses while impersonating;
 *   2. validates every input (ids, reasons, typed confirmations) server-side —
 *      the UI's confirm dialog is a convenience, never the control;
 *   3. writes an AuditLog row with the admin, the target and the reason;
 *   4. hands anything remote to the worker as an ADMIN_OPS Job (the web
 *      process never mutates Proxmox/iptables), or reuses an existing,
 *      already-audited lifecycle action (serverAction, reconcile, gamePower,
 *      retryProvision, adjustBalance, refundPayment, adminExtendServer…)
 *      instead of re-implementing a money path.
 *
 * test/admin-ops-actions-guards.test.ts proves (1) structurally.
 */
import { revalidatePath } from "next/cache";
import type { Prisma } from "@prisma/client";
import { db } from "../db";
import { requireArea } from "../rbac";
import { assertNotImpersonating } from "../auth";
import { recordAudit } from "../audit";
import { withServerJobLock } from "../job-guard";
import { serverAction, reconcileServerFromProxmox, adminExtendServer, adminSetServerFree } from "../actions";
import { gamePower } from "../actions-game-control";
import { retryProvision } from "../actions-server-lifecycle";
import { adjustBalance, refundPayment } from "../actions-admin-billing";
import { setNodeAcceptsProvisions } from "../actions-nodes";
import { sendMail } from "../mailer";
import { emails } from "../email-templates";
import { buildGuestCommand } from "./guest-commands";
import { whyNot, serverStatusAfterAbort, type JobVerb } from "./job-queue";
import { planIpReassign, planIpRelease, planIpAssign, type IpOpServer, type IpPlan } from "./ip-ops";
import { planDrain, type DrainPlan } from "./drain-planner";
import { requestVmMove, type VmMoveResult } from "./vm-move";
import { BULK_ACTIONS, BULK_MAX_CONCURRENCY, BULK_MAX_SERVERS, type BulkAction } from "./bulk";
import { cleanReason, type AdminOpPayload } from "./types";
import type { FixKey } from "./diagnose-rules";

type Ok<T = object> = ({ ok: true } & T) | { ok: false; error: string };

const ID_RE = /^[a-z0-9]{8,40}$/i;
const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;

function badId(id: unknown): boolean {
  return typeof id !== "string" || !ID_RE.test(id);
}

async function gate(area: "fleet" | "billing" = "fleet") {
  const admin = await requireArea(area);
  await assertNotImpersonating();
  return admin;
}

async function enqueue(payload: AdminOpPayload, serverId: string | null = null, extra?: { status?: "RUNNING" }): Promise<string> {
  const job = await db.job.create({
    data: { type: "ADMIN_OPS", serverId, payload: payload as unknown as Prisma.InputJsonValue, ...(extra?.status ? { status: extra.status } : {}) },
    select: { id: true },
  });
  return job.id;
}

async function inflightCount(serverId: string): Promise<number> {
  return db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
}

function revalidateServer(id: string) {
  revalidatePath(`/admin/servers/${id}`);
  revalidatePath(`/admin/ops/servers/${id}`);
  revalidatePath(`/dashboard/servers/${id}`);
}

// ---------------------------------------------------------------------------
// Polling
// ---------------------------------------------------------------------------

export type OpJobView = {
  id: string;
  op: string | null;
  status: string;
  step: string | null;
  progress: number;
  error: string | null;
  result: unknown;
  createdAt: string;
  updatedAt: string;
};

/** Poll an ADMIN_OPS job. Returns null for any other job type. */
export async function getOpJob(jobId: string): Promise<OpJobView | null> {
  await gate();
  if (badId(jobId)) return null;
  const j = await db.job.findUnique({ where: { id: jobId } });
  if (!j || j.type !== "ADMIN_OPS") return null;
  const p = (j.payload ?? {}) as { op?: string; result?: unknown };
  return {
    id: j.id,
    op: p.op ?? null,
    status: j.status,
    step: j.step,
    progress: j.progress,
    error: j.error,
    result: p.result ?? null,
    createdAt: j.createdAt.toISOString(),
    updatedAt: j.updatedAt.toISOString(),
  };
}

// ---------------------------------------------------------------------------
// Diagnose + fixes
// ---------------------------------------------------------------------------

export async function startDiagnose(serverId: string): Promise<Ok<{ jobId: string }>> {
  const admin = await gate();
  if (badId(serverId)) return { ok: false, error: "Invalid server." };
  const server = await db.server.findUnique({ where: { id: serverId }, select: { id: true, hostname: true } });
  if (!server) return { ok: false, error: "Server not found." };
  // De-dupe: an identical diagnose already queued/running for this server is reused.
  const existing = await db.job.findFirst({
    where: {
      type: "ADMIN_OPS",
      status: { in: ["QUEUED", "RUNNING"] },
      AND: [{ payload: { path: ["op"], equals: "diagnose" } }, { payload: { path: ["serverId"], equals: serverId } }],
    },
    select: { id: true },
  });
  if (existing) return { ok: true, jobId: existing.id };
  const jobId = await enqueue({ op: "diagnose", requestedBy: admin.id, serverId });
  await recordAudit(admin.id, "adminops.diagnose.request", server.hostname);
  return { ok: true, jobId };
}

/** Latest finished diagnosis for a server (so the panel can show it on load). */
export async function latestDiagnosis(serverId: string): Promise<OpJobView | null> {
  await gate();
  if (badId(serverId)) return null;
  const j = await db.job.findFirst({
    where: { type: "ADMIN_OPS", AND: [{ payload: { path: ["op"], equals: "diagnose" } }, { payload: { path: ["serverId"], equals: serverId } }] },
    orderBy: { createdAt: "desc" },
    select: { id: true },
  });
  return j ? getOpJob(j.id) : null;
}

const FIXES: FixKey[] = [
  "start_vm",
  "reboot_vm",
  "reconcile_status",
  "restart_game_service",
  "sync_forwards",
  "sync_game_dns",
  "retry_provision",
  "clear_stuck_job",
  "open_guest_logs",
];

/** Apply a one-click fix suggested by Diagnose — always via the existing path. */
export async function applyFix(serverId: string, fix: string): Promise<Ok<{ message: string; jobId?: string; navigate?: string }>> {
  const admin = await gate();
  if (badId(serverId)) return { ok: false, error: "Invalid server." };
  if (!FIXES.includes(fix as FixKey)) return { ok: false, error: "Unknown fix." };
  const server = await db.server.findUnique({ where: { id: serverId }, select: { id: true, hostname: true, subdomain: true } });
  if (!server) return { ok: false, error: "Server not found." };
  const done = async (message: string, jobId?: string) => {
    await recordAudit(admin.id, "adminops.fix", `${server.hostname} ${fix}${jobId ? ` job=${jobId}` : ""}`);
    revalidateServer(serverId);
    return { ok: true as const, message, jobId };
  };
  switch (fix as FixKey) {
    case "start_vm":
    case "reboot_vm": {
      const r = await serverAction(serverId, fix === "start_vm" ? "start" : "reboot");
      if (r && "error" in r && r.error) return { ok: false, error: r.error };
      return done(fix === "start_vm" ? "START queued." : "REBOOT queued.", r && "jobId" in r ? r.jobId : undefined);
    }
    case "reconcile_status": {
      const r = await reconcileServerFromProxmox(serverId);
      if (r.error) return { ok: false, error: r.error };
      return done(r.status ? `Status reconciled → ${r.status}.` : r.message ?? "Nothing to change.");
    }
    case "restart_game_service": {
      const r = await gamePower(serverId, "restart");
      if (!r.ok) return { ok: false, error: r.error };
      return done("Game service restart queued.", r.jobId);
    }
    case "sync_forwards": {
      const pending = await db.job.findFirst({ where: { type: "SYNC_FORWARDS", status: "QUEUED" }, select: { id: true } });
      const id = pending?.id ?? (await db.job.create({ data: { type: "SYNC_FORWARDS" }, select: { id: true } })).id;
      return done("NAT re-sync queued (all nodes, diff-only — no flush).", id);
    }
    case "sync_game_dns": {
      if (!server.subdomain) return { ok: false, error: "This server has no managed subdomain." };
      const j = await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId }, select: { id: true } });
      return done("Subdomain DNS re-sync queued.", j.id);
    }
    case "retry_provision": {
      const r = await retryProvision(serverId);
      if (r.error) return { ok: false, error: r.error };
      return done("Provisioning retry queued.");
    }
    case "clear_stuck_job":
      return { ok: true, message: "Opening the job queue.", navigate: `/admin/ops/jobs?server=${serverId}` };
    case "open_guest_logs":
      return { ok: true, message: "Open Guest tools below.", navigate: `/admin/ops/servers/${serverId}#guest` };
  }
}

// ---------------------------------------------------------------------------
// Guest ops
// ---------------------------------------------------------------------------

export async function runGuestCommand(serverId: string, command: string, params: Record<string, string | number> = {}): Promise<Ok<{ jobId: string }>> {
  const admin = await gate();
  if (badId(serverId)) return { ok: false, error: "Invalid server." };
  try {
    buildGuestCommand(command, params); // validate before enqueueing; the worker re-validates
  } catch (e) {
    return { ok: false, error: String((e as Error).message) };
  }
  const server = await db.server.findUnique({ where: { id: serverId }, select: { hostname: true, status: true } });
  if (!server) return { ok: false, error: "Server not found." };
  const jobId = await enqueue({ op: "guest_cmd", requestedBy: admin.id, serverId, command, params });
  await recordAudit(admin.id, "adminops.guest_cmd.request", `${server.hostname} ${command}`);
  return { ok: true, jobId };
}

/** Restart the game SERVICE only (never the VM) — the existing GAME_POWER path. */
export async function restartGameService(serverId: string): Promise<Ok<{ jobId: string }>> {
  await gate();
  if (badId(serverId)) return { ok: false, error: "Invalid server." };
  const r = await gamePower(serverId, "restart");
  if (!r.ok) return { ok: false, error: r.error };
  revalidateServer(serverId);
  return { ok: true, jobId: r.jobId };
}

// ---------------------------------------------------------------------------
// IP operations
// ---------------------------------------------------------------------------

async function ipOpServer(id: string): Promise<IpOpServer | null> {
  const s = await db.server.findUnique({
    where: { id },
    include: { dedicatedIp: { select: { id: true, address: true, status: true, nodeId: true } }, node: { select: { id: true, name: true } } },
  });
  if (!s) return null;
  const primary = s.nodeId ? null : await db.node.findFirst({ where: { isPrimary: true }, select: { id: true, name: true } });
  return {
    id: s.id,
    hostname: s.hostname,
    status: s.status,
    vmid: s.vmid,
    nodeId: s.nodeId ?? primary?.id ?? null,
    nodeName: s.node?.name ?? primary?.name ?? null,
    isGame: !!s.gamePlanId,
    wantsDedicatedIp: s.wantsDedicatedIp,
    hasInflightJob: (await inflightCount(s.id)) > 0,
    dedicatedIp: s.dedicatedIp,
  };
}

export async function previewIpReassign(sourceServerId: string, targetServerId: string): Promise<IpPlan> {
  await gate();
  if (badId(sourceServerId) || badId(targetServerId)) return { ok: false, error: "Invalid server." };
  const [a, b] = await Promise.all([ipOpServer(sourceServerId), ipOpServer(targetServerId)]);
  if (!a || !b) return { ok: false, error: "Server not found." };
  return planIpReassign(a, b);
}

/**
 * Reassign a dedicated IP between two servers on the same node. `confirm` must
 * be the IP address itself. The job is pinned to the SOURCE server (so the
 * scheduler serialises it against that server's jobs) and a HOLD row is
 * placed on the TARGET so customer/admin power actions there are refused
 * ("another operation running") until the move finishes.
 */
export async function startIpReassign(sourceServerId: string, targetServerId: string, reason: string, confirm: string): Promise<Ok<{ jobId: string }>> {
  const admin = await gate();
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters) — it goes in the audit log." };
  const plan = await previewIpReassign(sourceServerId, targetServerId);
  if (!plan.ok) return plan;
  const src = await db.server.findUnique({ where: { id: sourceServerId }, include: { dedicatedIp: true } });
  if (!src?.dedicatedIp || confirm.trim() !== src.dedicatedIp.address) return { ok: false, error: `Type the IP address (${src?.dedicatedIp?.address ?? "?"}) to confirm.` };
  const out = await withServerJobLock(targetServerId, async (tx) => {
    const busy = await tx.job.count({ where: { serverId: { in: [sourceServerId, targetServerId] }, status: { in: ["QUEUED", "RUNNING"] } } });
    if (busy) return null;
    const hold = await tx.job.create({
      data: { type: "ADMIN_OPS", serverId: targetServerId, status: "RUNNING", step: "Held for an IP reassign", payload: { op: "hold", requestedBy: admin.id } as Prisma.InputJsonValue },
      select: { id: true },
    });
    const job = await tx.job.create({
      data: {
        type: "ADMIN_OPS",
        serverId: sourceServerId,
        payload: { op: "ip_reassign", requestedBy: admin.id, reason: why, sourceServerId, targetServerId, holdJobId: hold.id } as Prisma.InputJsonValue,
      },
      select: { id: true },
    });
    return job.id;
  });
  if (!out) return { ok: false, error: "One of the servers just picked up another job — try again when it's idle." };
  await recordAudit(admin.id, "adminops.ip_reassign.request", `${src.dedicatedIp.address} ${src.hostname} -> ${targetServerId} reason="${why}"`);
  revalidateServer(sourceServerId);
  revalidateServer(targetServerId);
  return { ok: true, jobId: out };
}

export async function previewIpRelease(serverId: string): Promise<IpPlan> {
  await gate();
  if (badId(serverId)) return { ok: false, error: "Invalid server." };
  const s = await ipOpServer(serverId);
  return s ? planIpRelease(s) : { ok: false, error: "Server not found." };
}

export async function startIpRelease(serverId: string, reason: string, confirm: string): Promise<Ok<{ jobId: string }>> {
  const admin = await gate();
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters)." };
  const plan = await previewIpRelease(serverId);
  if (!plan.ok) return plan;
  const s = await db.server.findUnique({ where: { id: serverId }, include: { dedicatedIp: true } });
  if (!s?.dedicatedIp || confirm.trim() !== s.dedicatedIp.address) return { ok: false, error: `Type the IP address (${s?.dedicatedIp?.address ?? "?"}) to confirm.` };
  const jobId = await withServerJobLock(serverId, async (tx) => {
    if (await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } })) return null;
    return (await tx.job.create({ data: { type: "ADMIN_OPS", serverId, payload: { op: "ip_release", requestedBy: admin.id, reason: why, serverId } as Prisma.InputJsonValue }, select: { id: true } })).id;
  });
  if (!jobId) return { ok: false, error: "Another job is in flight on this server." };
  await recordAudit(admin.id, "adminops.ip_release.request", `${s.dedicatedIp.address} ${s.hostname} reason="${why}"`);
  revalidateServer(serverId);
  return { ok: true, jobId };
}

async function freeIpsForServer(serverId: string): Promise<string[]> {
  const s = await db.server.findUnique({ where: { id: serverId }, select: { nodeId: true } });
  const nodeId = s?.nodeId ?? (await db.node.findFirst({ where: { isPrimary: true }, select: { id: true } }))?.id;
  if (!nodeId) return [];
  return (await db.dedicatedIp.findMany({ where: { nodeId, status: "FREE", purpose: "CUSTOMER", serverId: null }, orderBy: { createdAt: "asc" }, select: { address: true } })).map((r) => r.address);
}

export async function previewIpAssign(serverId: string, address: string | null): Promise<IpPlan & { free?: string[] }> {
  await gate();
  if (badId(serverId)) return { ok: false, error: "Invalid server." };
  if (address && !IPV4_RE.test(address)) return { ok: false, error: "Not an IPv4 address." };
  const s = await ipOpServer(serverId);
  if (!s) return { ok: false, error: "Server not found." };
  const free = await freeIpsForServer(serverId);
  return { ...planIpAssign(s, address, free), free };
}

export async function startIpAssign(serverId: string, address: string | null, billable: boolean, reason: string): Promise<Ok<{ jobId: string }>> {
  const admin = await gate();
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters)." };
  const plan = await previewIpAssign(serverId, address || null);
  if (!plan.ok) return plan;
  const jobId = await withServerJobLock(serverId, async (tx) => {
    if (await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } })) return null;
    return (await tx.job.create({ data: { type: "ADMIN_OPS", serverId, payload: { op: "ip_assign", requestedBy: admin.id, reason: why, serverId, address: address || undefined, billable: !!billable } as Prisma.InputJsonValue }, select: { id: true } })).id;
  });
  if (!jobId) return { ok: false, error: "Another job is in flight on this server." };
  await recordAudit(admin.id, "adminops.ip_assign.request", `${serverId} ${address ?? "(first free)"} billable=${!!billable} reason="${why}"`);
  revalidateServer(serverId);
  return { ok: true, jobId };
}

// ---------------------------------------------------------------------------
// Node moves / drain (engine owned by the vm-node-migration branch)
// ---------------------------------------------------------------------------

export async function requestServerMove(serverId: string, targetNodeId: string, dryRun: boolean, reason: string): Promise<VmMoveResult> {
  const admin = await gate();
  if (badId(serverId) || badId(targetNodeId)) return { ok: false, error: "Invalid id." };
  const why = cleanReason(reason);
  if (!why && !dryRun) return { ok: false, error: "Give a reason (4-300 characters)." };
  const r = await requestVmMove({ serverId, targetNodeId, dryRun, reason: why ?? "dry run", requestedBy: admin.id });
  await recordAudit(admin.id, dryRun ? "adminops.vm_move.preview" : "adminops.vm_move.request", `${serverId} -> ${targetNodeId} ok=${r.ok}${why ? ` reason="${why}"` : ""}`);
  return r;
}

export async function previewDrain(nodeId: string, mode: "drain" | "rebalance", targetPct: number, allowCrossRegion: boolean): Promise<Ok<{ plan: DrainPlan }>> {
  await gate();
  if (badId(nodeId)) return { ok: false, error: "Invalid node." };
  const nodes = await db.node.findMany({ orderBy: { createdAt: "asc" } });
  const source = nodes.find((n) => n.id === nodeId);
  if (!source) return { ok: false, error: "Node not found." };
  const servers = await db.server.findMany({
    where: { status: { notIn: ["DELETING"] } },
    select: { id: true, hostname: true, nodeId: true, status: true, extraDiskGB: true, plan: { select: { ramMB: true, diskGB: true } }, gamePlan: { select: { ramMB: true, diskGB: true } }, dedicatedIp: { select: { id: true } } },
  });
  const primaryId = nodes.find((n) => n.isPrimary)?.id;
  const ram = (s: (typeof servers)[number]) => s.gamePlan?.ramMB ?? s.plan.ramMB;
  const committed = new Map<string, number>();
  for (const s of servers) {
    const nid = s.nodeId ?? primaryId;
    if (nid) committed.set(nid, (committed.get(nid) ?? 0) + ram(s));
  }
  const plan = planDrain({
    source: { id: source.id, name: source.name, region: source.region, capacityRamMB: source.capacityRamMB, committedRamMB: committed.get(source.id) ?? 0, enabled: source.enabled, acceptsProvisions: source.acceptsProvisions },
    nodes: nodes.map((n) => ({ id: n.id, name: n.name, region: n.region, capacityRamMB: n.capacityRamMB, committedRamMB: committed.get(n.id) ?? 0, enabled: n.enabled, acceptsProvisions: n.acceptsProvisions })),
    servers: servers
      .filter((s) => (s.nodeId ?? primaryId) === source.id)
      .map((s) => ({ id: s.id, hostname: s.hostname, ramMB: ram(s), diskGB: (s.gamePlan?.diskGB ?? s.plan.diskGB) + s.extraDiskGB, hasDedicatedIp: !!s.dedicatedIp, status: s.status })),
    mode,
    targetPct: Math.min(Math.max(Number(targetPct) || 75, 10), 100),
    allowCrossRegion: !!allowCrossRegion,
  });
  return { ok: true, plan };
}

/** Stop new provisions landing on a node (first step of any drain). Reuses the Infrastructure toggle. */
export async function setNodeDraining(nodeId: string, draining: boolean, reason: string): Promise<Ok> {
  const admin = await gate();
  if (badId(nodeId)) return { ok: false, error: "Invalid node." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters)." };
  const r = await setNodeAcceptsProvisions(nodeId, !draining);
  if (r.error) return { ok: false, error: r.error };
  await recordAudit(admin.id, draining ? "adminops.node_drain_on" : "adminops.node_drain_off", `${nodeId} reason="${why}"`);
  revalidatePath("/admin/ops/fleet");
  return { ok: true };
}

