"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";
import { isUploadInProgress } from "@/lib/upload-in-progress";

/**
 * Refreshes the page every `intervalMs` while mounted (used during
 * transitional states — see each call site's own gate, e.g. a server with any
 * job queued/running).
 *
 * Skips a tick while a file is actively uploading anywhere on the page (see
 * lib/upload-in-progress.ts) — found live 2026-09-06: a customer's large File
 * Manager upload (well over 5s to transfer) kept getting interrupted mid-way
 * because THIS component was also mounted on the same server detail page
 * (gated on "any job queued/running" — e.g. an unrelated scheduled backup —
 * not on the upload itself) and refreshing the page out from under it.
 */
export function AutoRefresh({ intervalMs = 5000 }: { intervalMs?: number }) {
  const router = useRouter();
  useEffect(() => {
    const t = setInterval(() => {
      if (isUploadInProgress()) return;
      router.refresh();
    }, intervalMs);
    return () => clearInterval(t);
  }, [router, intervalMs]);
  return null;
}

