"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { getOpJob, type OpJobView } from "@/lib/admin-ops/actions";

/**
 * Poll one ADMIN_OPS job until it is DONE/FAILED. `jobId` null = idle.
 * Backs off from 1.5s to 4s so a long op (bulk, drift) doesn't hammer the DB.
 */
export function useOpJob(jobId: string | null, initial: OpJobView | null = null) {
  const [job, setJob] = useState<OpJobView | null>(initial);
  const tries = useRef(0);
  useEffect(() => {
    if (!jobId) return;
    let alive = true;
    tries.current = 0;
    const tick = async () => {
      const j = await getOpJob(jobId).catch(() => null);
      if (!alive) return;
      if (j) setJob(j);
      if (!j || (j.status !== "DONE" && j.status !== "FAILED")) {
        tries.current++;
        setTimeout(tick, Math.min(4000, 1500 + tries.current * 250));
      }
    };
    tick();
    return () => {
      alive = false;
    };
  }, [jobId]);
  const busy = !!jobId && (!job || job.id !== jobId || job.status === "QUEUED" || job.status === "RUNNING");
  return { job: job && (!jobId || job.id === jobId) ? job : job, busy };
}

export function useAction<A extends unknown[], R>(fn: (...a: A) => Promise<R>) {
  const [pending, setPending] = useState(false);
  const run = useCallback(
    async (...a: A): Promise<R | null> => {
      setPending(true);
      try {
        return await fn(...a);
      } catch (e) {
        return { ok: false, error: String((e as Error)?.message ?? e) } as unknown as R;
      } finally {
        setPending(false);
      }
    },
    [fn],
  );
  return { run, pending };
}

export function JobProgress({ job, busy }: { job: OpJobView | null; busy: boolean }) {
  if (!job) return null;
  const failed = job.status === "FAILED";
  return (
    <div className="mt-3 space-y-1" aria-live="polite">
      <div className="flex items-center justify-between text-xs text-slate-400">
        <span>{busy ? job.step ?? (job.status === "QUEUED" ? "Queued — waiting for a worker slot…" : "Working…") : failed ? "Failed" : "Finished"}</span>
        <span className="font-mono">{job.status.toLowerCase()}</span>
      </div>
      {busy && (
        <div className="h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
          <div className="h-full rounded-full bg-gradient-to-r from-[#3b6be8] to-[#7b3fef] transition-all" style={{ width: `${Math.max(6, job.progress)}%` }} />
        </div>
      )}
      {failed && <p className="text-xs text-red-400">{(job.result as { error?: string } | null)?.error ?? job.error ?? "The operation failed."}</p>}
    </div>
  );
}

export function ReasonInput({ value, onChange, placeholder = "Reason (goes in the audit log) — e.g. ticket #123" }: { value: string; onChange: (v: string) => void; placeholder?: string }) {
  return <input className="input w-full py-1.5 text-sm" value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} maxLength={300} />;
}

export function Notice({ tone, children }: { tone: "ok" | "err" | "info"; children: React.ReactNode }) {
  const cls = tone === "ok" ? "border-emerald-500/30 bg-emerald-500/[0.07] text-emerald-300" : tone === "err" ? "border-red-500/30 bg-red-500/[0.07] text-red-300" : "border-white/10 bg-white/[0.03] text-slate-300";
  return <div className={`rounded-lg border px-3 py-2 text-xs ${cls}`} role={tone === "err" ? "alert" : undefined}>{children}</div>;
}

export function PlanPreview({ plan }: { plan: { ok: true; steps: string[]; warnings: string[] } | { ok: false; error: string } | null }) {
  if (!plan) return null;
  if (!plan.ok) return <Notice tone="err">{plan.error}</Notice>;
  return (
    <div className="space-y-2 rounded-lg border border-white/10 bg-white/[0.02] p-3 text-xs">
      <p className="font-semibold uppercase tracking-wide text-slate-400">Dry run — what will happen</p>
      <ol className="list-decimal space-y-1 pl-4 text-slate-300">
        {plan.steps.map((s, i) => (
          <li key={i}>{s}</li>
        ))}
      </ol>
      {plan.warnings.length > 0 && (
        <ul className="space-y-1 text-amber-300">
          {plan.warnings.map((w, i) => (
            <li key={i}>⚠ {w}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

export function SectionTitle({ title, sub, right }: { title: string; sub?: string; right?: React.ReactNode }) {
  return (
    <div className="mb-3 flex flex-wrap items-start justify-between gap-2">
      <div>
        <h3 className="font-semibold">{title}</h3>
        {sub && <p className="mt-0.5 text-xs text-slate-400">{sub}</p>}
      </div>
      {right}
    </div>
  );
}

