  return <div className={`rounded-lg border px-3 py-2 text-xs ${cls}`} role={tone === "err" ? "alert" : undefined}>{children}</div>;
}

export function PlanPreview({ plan }: { plan: { ok: true; steps: string[]; warnings: string[] } | { ok: false; error: string } | null }) {
  if (!plan) return null;
  if (!plan.ok) return <Notice tone="err">{plan.error}</Notice>;
  return (
    <div className="space-y-2 rounded-lg border border-white/10 bg-white/[0.02] p-3 text-xs">
      <p className="font-semibold uppercase tracking-wide text-slate-400">Dry run — what will happen</p>
      <ol className="list-decimal space-y-1 pl-4 text-slate-300">
        {plan.steps.map((s, i) => (
          <li key={i}>{s}</li>
        ))}
      </ol>
      {plan.warnings.length > 0 && (
        <ul className="space-y-1 text-amber-300">
          {plan.warnings.map((w, i) => (
            <li key={i}>⚠ {w}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

export function SectionTitle({ title, sub, right }: { title: string; sub?: string; right?: React.ReactNode }) {
  return (
    <div className="mb-3 flex flex-wrap items-start justify-between gap-2">
      <div>
        <h3 className="font-semibold">{title}</h3>
        {sub && <p className="mt-0.5 text-xs text-slate-400">{sub}</p>}
      </div>
      {right}
    </div>
  );
}

