"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { startDiagnose, applyFix, type OpJobView } from "@/lib/admin-ops/actions";
import { FIX_LABELS, type DiagnosisResult, type FixKey, type CheckStatus } from "@/lib/admin-ops/diagnose-rules";
import { useOpJob, JobProgress, Notice, SectionTitle } from "./shared";

const VERDICT: Record<DiagnosisResult["verdict"], { label: string; cls: string }> = {
  healthy: { label: "Healthy", cls: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300" },
  degraded: { label: "Degraded", cls: "border-amber-500/40 bg-amber-500/10 text-amber-300" },
  down: { label: "Down", cls: "border-red-500/40 bg-red-500/10 text-red-300" },
  unknown: { label: "Unknown", cls: "border-white/15 bg-white/[0.04] text-slate-300" },
};

const CHECK_ICON: Record<CheckStatus, { ch: string; cls: string }> = {
  ok: { ch: "✓", cls: "text-emerald-400" },
  warn: { ch: "!", cls: "text-amber-400" },
  fail: { ch: "✕", cls: "text-red-400" },
  skip: { ch: "–", cls: "text-slate-500" },
};

/**
 * One-click "Diagnose server": runs the full check ladder in the worker and
 * renders the verdict, ranked probable causes with their evidence, every raw
 * check, and the suggested one-click fixes (each through an existing,
 * audited path — see applyFix in lib/admin-ops/actions.ts).
 */
export function DiagnosePanel({ serverId, initial }: { serverId: string; initial: OpJobView | null }) {
  const router = useRouter();
  const [jobId, setJobId] = useState<string | null>(initial && (initial.status === "QUEUED" || initial.status === "RUNNING") ? initial.id : null);
  const { job, busy } = useOpJob(jobId, initial);
  const [error, setError] = useState<string | null>(null);
  const [fixMsg, setFixMsg] = useState<{ tone: "ok" | "err"; text: string } | null>(null);
  const [fixing, setFixing] = useState<string | null>(null);
  const [showChecks, setShowChecks] = useState(false);

  const result = (job?.result as { diagnosis?: DiagnosisResult } | null)?.diagnosis ?? null;

  const run = async () => {
    setError(null);
    setFixMsg(null);
    const r = await startDiagnose(serverId);
    if (!r.ok) setError(r.error);
    else setJobId(r.jobId);
  };

  const fix = async (key: FixKey) => {
    if (!window.confirm(`${FIX_LABELS[key]}?`)) return;
    setFixing(key);
    setFixMsg(null);
    const r = await applyFix(serverId, key);
    setFixing(null);
    if (!r.ok) return setFixMsg({ tone: "err", text: r.error });
    setFixMsg({ tone: "ok", text: r.message });
    if (r.navigate) router.push(r.navigate);
    else router.refresh();
  };

  return (
    <div className="card" data-testid="diagnose-panel">
      <SectionTitle
        title="Diagnose server"
        sub="VM, guest agent, game service, port in guest, DNAT on the node, outside probe, DNS, logs, resources, recent jobs — one click."
        right={
          <button className="btn-primary py-1.5 text-sm" onClick={run} disabled={busy}>
            {busy ? "Diagnosing…" : result ? "Run again" : "Diagnose"}
          </button>
        }
      />
      {error && <Notice tone="err">{error}</Notice>}
      <JobProgress job={job} busy={busy} />

      {result && !busy && (
        <div className="mt-4 space-y-4">
          {result.sandbox && <Notice tone="info">Sandbox simulation — no host, guest or DNS was contacted. Results are derived from the database row.</Notice>}
          <div className="flex flex-wrap items-start gap-3">
            <span className={`rounded-full border px-3 py-1 text-xs font-semibold uppercase tracking-wide ${VERDICT[result.verdict].cls}`} data-testid="diagnose-verdict">
              {VERDICT[result.verdict].label}
            </span>
            <p className="min-w-0 flex-1 text-sm text-slate-200">{result.headline}</p>
          </div>
          {result.connectAddress && (
            <p className="text-xs text-slate-400">
              Customer connects to <span className="font-mono text-slate-200">{result.connectAddress}</span>
            </p>
          )}

          {result.causes.length > 0 && (
            <div className="space-y-2">
              <p className="text-xs font-semibold uppercase tracking-wide text-slate-400">Probable causes (most likely first)</p>
              {result.causes.map((c, i) => (
                <div key={c.key} className="rounded-lg border border-white/10 bg-white/[0.02] p-3">
                  <div className="flex flex-wrap items-center justify-between gap-2">
                    <p className="text-sm font-medium">
                      <span className="mr-2 font-mono text-xs text-slate-500">#{i + 1}</span>
                      {c.title}
                      {c.customerSide && <span className="ml-2 rounded-full border border-white/10 px-2 py-0.5 text-[10px] text-slate-400">customer-side</span>}
                    </p>
                    <span className="font-mono text-xs text-slate-400">{c.confidence}%</span>
                  </div>
                  <ul className="mt-1.5 space-y-1 text-xs text-slate-400">
                    {c.evidence.map((e, j) => (
                      <li key={j} className="break-words font-mono">{e}</li>
                    ))}
                  </ul>
                  {c.fixes.length > 0 && (
                    <div className="mt-2 flex flex-wrap gap-2">
                      {c.fixes.map((f) => (
                        <button key={f} className="btn-secondary py-1 text-xs" disabled={!!fixing} onClick={() => fix(f)}>
                          {fixing === f ? "Working…" : FIX_LABELS[f]}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
          {fixMsg && <Notice tone={fixMsg.tone}>{fixMsg.text}</Notice>}

          <div>
            <button className="text-xs text-brand-300 hover:underline" onClick={() => setShowChecks((v) => !v)}>
              {showChecks ? "Hide" : "Show"} all {result.checks.length} checks
            </button>
            {showChecks && (
              <ul className="mt-2 divide-y divide-white/[0.06] rounded-lg border border-white/10">
                {result.checks.map((c) => (
                  <li key={c.key} className="flex gap-3 px-3 py-2 text-xs">
                    <span className={`w-3 font-bold ${CHECK_ICON[c.status].cls}`}>{CHECK_ICON[c.status].ch}</span>
                    <span className="w-44 shrink-0 text-slate-300">{c.label}</span>
                    <span className="min-w-0 break-words font-mono text-slate-400">{c.detail}</span>
                  </li>
                ))}
              </ul>
            )}
          </div>
          <p className="text-[11px] text-slate-500">Generated {new Date(result.generatedAt).toLocaleString()}</p>
        </div>
      )}
    </div>
  );
}

