"use client";

import { useMemo, useState } from "react";
import { runGuestCommand, restartGameService } from "@/lib/admin-ops/actions";
import { useOpJob, JobProgress, Notice, SectionTitle } from "./shared";

export type GuestCommandMeta = {
  key: string;
  label: string;
  description: string;
  params: { name: string; label: string; kind: string; default?: string | number }[];
};

/**
 * Guest tools: restart the game service (never the VM), and run one of the
 * WHITELISTED read-only diagnostic commands with captured output. There is no
 * free-text shell here by design — see lib/admin-ops/guest-commands.ts.
 */
export function GuestTools({ serverId, commands, isGame, gameUnit, running }: { serverId: string; commands: GuestCommandMeta[]; isGame: boolean; gameUnit: string | null; running: boolean }) {
  const [key, setKey] = useState(isGame ? "journal_unit" : "overview");
  const cmd = useMemo(() => commands.find((c) => c.key === key) ?? commands[0], [commands, key]);
  const [params, setParams] = useState<Record<string, string>>({ unit: gameUnit ?? "" });
  const [jobId, setJobId] = useState<string | null>(null);
  const { job, busy } = useOpJob(jobId);
  const [error, setError] = useState<string | null>(null);
  const [restartMsg, setRestartMsg] = useState<{ tone: "ok" | "err"; text: string } | null>(null);
  const [restarting, setRestarting] = useState(false);
  const out = job?.result as { output?: string; exitCode?: number | null; truncated?: boolean; label?: string } | null;

  const run = async () => {
    setError(null);
    const clean: Record<string, string> = {};
    for (const p of cmd.params) if (params[p.name]) clean[p.name] = params[p.name];
    const r = await runGuestCommand(serverId, cmd.key, clean);
    if (!r.ok) setError(r.error);
    else setJobId(r.jobId);
  };

  const restart = async () => {
    if (!window.confirm("Restart the game service? Players are disconnected; the VM keeps running.")) return;
    setRestarting(true);
    const r = await restartGameService(serverId);
    setRestarting(false);
    setRestartMsg(r.ok ? { tone: "ok", text: "Game service restart queued (GAME_POWER). Watch the job history." } : { tone: "err", text: r.error });
  };

  return (
    <div className="card" id="guest" data-testid="guest-tools">
      <SectionTitle
        title="Guest tools"
        sub="Read-only diagnostics over the platform's SSH. Whitelisted commands only — output is captured, capped and scrubbed."
        right={
          isGame ? (
            <button className="btn-secondary py-1.5 text-sm" onClick={restart} disabled={restarting || !running} title={running ? "" : "The VM must be running"}>
              {restarting ? "Queuing…" : "Restart game service"}
            </button>
          ) : null
        }
      />
      {restartMsg && <div className="mb-3"><Notice tone={restartMsg.tone}>{restartMsg.text}</Notice></div>}
      <div className="flex flex-wrap items-end gap-2">
        <label className="flex min-w-[220px] flex-col gap-1 text-xs text-slate-400">
          Command
          <select className="input py-1.5 text-sm" value={key} onChange={(e) => setKey(e.target.value)}>
            {commands.map((c) => (
              <option key={c.key} value={c.key}>
                {c.label}
              </option>
            ))}
          </select>
        </label>
        {cmd.params.map((p) => (
          <label key={p.name} className="flex flex-col gap-1 text-xs text-slate-400">
            {p.label}
            <input
              className="input w-44 py-1.5 font-mono text-sm"
              value={params[p.name] ?? ""}
              placeholder={p.default != null ? String(p.default) : p.kind === "unit" ? "minecraft.service" : ""}
              onChange={(e) => setParams((s) => ({ ...s, [p.name]: e.target.value }))}
            />
          </label>
        ))}
        <button className="btn-primary py-1.5 text-sm" onClick={run} disabled={busy}>
          {busy ? "Running…" : "Run"}
        </button>
      </div>
      <p className="mt-1.5 text-xs text-slate-500">{cmd.description}</p>
      {error && <div className="mt-2"><Notice tone="err">{error}</Notice></div>}
      <JobProgress job={job} busy={busy} />
      {out?.output != null && !busy && (
        <div className="mt-3">
          <div className="mb-1 flex justify-between text-[11px] text-slate-500">
            <span>{out.label}</span>
            <span>exit {out.exitCode ?? "?"}{out.truncated ? " · output truncated to the last 64 KB" : ""}</span>
          </div>
          <pre className="max-h-96 overflow-auto whitespace-pre-wrap break-words rounded-lg border border-white/10 bg-black/40 p-3 font-mono text-[11px] leading-relaxed text-slate-300" data-testid="guest-output">
            {out.output || "(no output)"}
          </pre>
        </div>
      )}
    </div>
  );
}

