"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import {
  previewIpReassign,
  startIpReassign,
  previewIpRelease,
  startIpRelease,
  previewIpAssign,
  startIpAssign,
  requestServerMove,
} from "@/lib/admin-ops/actions";
import type { IpPlan } from "@/lib/admin-ops/ip-ops";
import { useOpJob, JobProgress, Notice, PlanPreview, ReasonInput, SectionTitle } from "./shared";

type Mode = "reassign" | "release" | "assign" | "move";

/**
 * Dedicated-IP operations for one server, each previewed as a dry run before
 * it is enqueued: give this server's IP to another server on the same node,
 * release it back to the pool (server drops to NAT), or assign a FREE pool IP.
 * "Move to another node" goes to the VM move engine (owned by the
 * vm-node-migration branch) via requestServerMove.
 */
export function IpOpsPanel({
  serverId,
  dedicatedIp,
  sameNodeServers,
  freeIps,
  nodes,
  currentNodeId,
}: {
  serverId: string;
  dedicatedIp: string | null;
  sameNodeServers: { id: string; hostname: string; hasIp: boolean }[];
  freeIps: string[];
  nodes: { id: string; name: string; region: string }[];
  currentNodeId: string | null;
}) {
  const router = useRouter();
  const [mode, setMode] = useState<Mode>(dedicatedIp ? "reassign" : "assign");
  const [target, setTarget] = useState("");
  const [address, setAddress] = useState("");
  const [billable, setBillable] = useState(false);
  const [reason, setReason] = useState("");
  const [confirm, setConfirm] = useState("");
  const [plan, setPlan] = useState<IpPlan | null>(null);
  const [msg, setMsg] = useState<{ tone: "ok" | "err" | "info"; text: string } | null>(null);
  const [jobId, setJobId] = useState<string | null>(null);
  const { job, busy } = useOpJob(jobId);
  const [moveNode, setMoveNode] = useState("");

  const reset = (m: Mode) => {
    setMode(m);
    setPlan(null);
    setMsg(null);
    setConfirm("");
  };

  const preview = async () => {
    setMsg(null);
    if (mode === "reassign") {
      if (!target) return setMsg({ tone: "err", text: "Pick a target server." });
      setPlan(await previewIpReassign(serverId, target));
    } else if (mode === "release") {
      setPlan(await previewIpRelease(serverId));
    } else if (mode === "assign") {
      setPlan(await previewIpAssign(serverId, address || null));
    } else {
      if (!moveNode) return setMsg({ tone: "err", text: "Pick a target node." });
      const r = await requestServerMove(serverId, moveNode, true, reason || "dry run");
      setMsg(r.ok ? { tone: "ok", text: (r.steps ?? ["Dry run accepted."]).join(" · ") } : { tone: r.engineMissing ? "info" : "err", text: r.error });
    }
  };

  const execute = async () => {
    setMsg(null);
    let r: { ok: true; jobId: string } | { ok: false; error: string };
    if (mode === "reassign") r = await startIpReassign(serverId, target, reason, confirm);
    else if (mode === "release") r = await startIpRelease(serverId, reason, confirm);
    else if (mode === "assign") r = await startIpAssign(serverId, address || null, billable, reason);
    else {
      const m = await requestServerMove(serverId, moveNode, false, reason);
      setMsg(m.ok ? { tone: "ok", text: `Move requested${m.jobId ? ` (job ${m.jobId})` : ""}.` } : { tone: m.engineMissing ? "info" : "err", text: m.error });
      return;
    }
    if (!r.ok) return setMsg({ tone: "err", text: r.error });
    setJobId(r.jobId);
    setPlan(null);
    router.refresh();
  };

  const needsConfirm = mode === "reassign" || mode === "release";
  const canRun = mode === "move" ? !!moveNode : !!plan && plan.ok;

  return (
    <div className="card" data-testid="ip-ops">
      <SectionTitle title="IP & placement" sub={dedicatedIp ? `Dedicated IP ${dedicatedIp}` : "Shared NAT address (no dedicated IP)"} />
      <div className="mb-3 flex flex-wrap gap-1.5">
        {(
          [
            ["reassign", "Give IP to another server", !!dedicatedIp],
            ["release", "Release IP (→ NAT)", !!dedicatedIp],
            ["assign", "Assign a pool IP", !dedicatedIp],
            ["move", "Move to another node", true],
          ] as [Mode, string, boolean][]
        ).map(([m, label, enabled]) => (
          <button key={m} className={`rounded-full border px-3 py-1 text-xs ${mode === m ? "border-brand-500/60 bg-brand-500/15 text-brand-200" : "border-white/10 text-slate-400 hover:text-slate-200"} disabled:opacity-40`} disabled={!enabled} onClick={() => reset(m)}>
            {label}
          </button>
        ))}
      </div>

      <div className="space-y-2">
        {mode === "reassign" && (
          <select className="input w-full py-1.5 text-sm" value={target} onChange={(e) => { setTarget(e.target.value); setPlan(null); }}>
            <option value="">Target server on the same node…</option>
            {sameNodeServers.filter((s) => s.id !== serverId).map((s) => (
              <option key={s.id} value={s.id} disabled={s.hasIp}>
                {s.hostname}{s.hasIp ? " (already has a dedicated IP)" : ""}
              </option>
            ))}
          </select>
        )}
        {mode === "assign" && (
          <div className="flex flex-wrap items-center gap-3">
            <select className="input py-1.5 text-sm" value={address} onChange={(e) => { setAddress(e.target.value); setPlan(null); }}>
              <option value="">First free IP on this node ({freeIps.length} free)</option>
              {freeIps.map((a) => (
                <option key={a} value={a}>{a}</option>
              ))}
            </select>
            <label className="flex items-center gap-2 text-xs text-slate-300">
              <input type="checkbox" checked={billable} onChange={(e) => setBillable(e.target.checked)} />
              Bill the dedicated-IP add-on at renewal
            </label>
          </div>
        )}
        {mode === "move" && (
          <select className="input w-full py-1.5 text-sm" value={moveNode} onChange={(e) => setMoveNode(e.target.value)}>
            <option value="">Target node…</option>
            {nodes.filter((n) => n.id !== currentNodeId).map((n) => (
              <option key={n.id} value={n.id}>{n.name} · {n.region}</option>
            ))}
          </select>
        )}
        <ReasonInput value={reason} onChange={setReason} />
        <div className="flex flex-wrap items-center gap-2">
          <button className="btn-secondary py-1.5 text-sm" onClick={preview} disabled={busy}>
            Preview (dry run)
          </button>
          {needsConfirm && plan?.ok && (
            <input className="input w-48 py-1.5 font-mono text-xs" placeholder={`type ${dedicatedIp ?? "the IP"}`} value={confirm} onChange={(e) => setConfirm(e.target.value)} />
          )}
          <button className="btn-danger py-1.5 text-sm" onClick={execute} disabled={busy || !canRun || (needsConfirm && confirm.trim() !== dedicatedIp)}>
            {busy ? "Working…" : "Execute"}
          </button>
        </div>
      </div>
      <div className="mt-3 space-y-2">
        <PlanPreview plan={plan} />
        {msg && <Notice tone={msg.tone}>{msg.text}</Notice>}
        <JobProgress job={job} busy={busy} />
        {job?.status === "DONE" && <Notice tone="ok">Done. {(job.result as { log?: string[] } | null)?.log?.join(" · ") ?? ""}</Notice>}
      </div>
    </div>
  );
}

