"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { customerCredit, customerExtend, customerSetFree, customerTransferServer, customerRefund } from "@/lib/admin-ops/actions";
import { Notice, ReasonInput, SectionTitle } from "./shared";

type Tab = "credit" | "extend" | "free" | "transfer" | "refund";

/**
 * Customer-facing account ops for one server's owner. Every money path is the
 * existing audited action (adjustBalance / refundPayment / adminExtendServer /
 * adminSetServerFree) wrapped with a mandatory reason and an optional in-app
 * notification and/or email to the customer.
 */
export function CustomerOpsPanel({
  serverId,
  hostname,
  ownerId,
  ownerEmail,
  isFree,
  expiresAt,
}: {
  serverId: string;
  hostname: string;
  ownerId: string;
  ownerEmail: string;
  isFree: boolean;
  expiresAt: string | null;
}) {
  const router = useRouter();
  const [tab, setTab] = useState<Tab>("extend");
  const [reason, setReason] = useState("");
  const [amount, setAmount] = useState("");
  const [days, setDays] = useState("7");
  const [invoiceId, setInvoiceId] = useState("");
  const [target, setTarget] = useState("");
  const [confirm, setConfirm] = useState("");
  const [notify, setNotify] = useState(true);
  const [email, setEmail] = useState(false);
  const [resetPw, setResetPw] = useState(false);
  const [pending, setPending] = useState(false);
  const [msg, setMsg] = useState<{ tone: "ok" | "err"; text: string } | null>(null);

  const go = async () => {
    setMsg(null);
    setPending(true);
    let r: { ok: true; message: string } | { ok: false; error: string };
    try {
      if (tab === "credit") r = await customerCredit(ownerId, Number(amount), reason, notify, email);
      else if (tab === "refund") r = await customerRefund(ownerId, Number(amount), invoiceId.trim(), reason, notify, email);
      else if (tab === "extend") r = await customerExtend(serverId, Number(days), reason, notify, email);
      else if (tab === "free") r = await customerSetFree(serverId, !isFree, reason);
      else r = await customerTransferServer(serverId, target, reason, { notify, email, resetPassword: resetPw }, confirm);
    } finally {
      setPending(false);
    }
    setMsg(r.ok ? { tone: "ok", text: r.message } : { tone: "err", text: r.error });
    if (r.ok) router.refresh();
  };

  return (
    <div className="card" data-testid="customer-ops">
      <SectionTitle title="Customer ops" sub={`Owner ${ownerEmail} · ${isFree ? "free server" : expiresAt ? `renews ${new Date(expiresAt).toLocaleDateString()}` : "no expiry"}`} />
      <div className="mb-3 flex flex-wrap gap-1.5">
        {(
          [
            ["extend", "Extend / shorten"],
            ["credit", "Wallet credit"],
            ["refund", "Refund"],
            ["free", isFree ? "Make paid" : "Make free"],
            ["transfer", "Transfer server"],
          ] as [Tab, string][]
        ).map(([t, label]) => (
          <button key={t} className={`rounded-full border px-3 py-1 text-xs ${tab === t ? "border-brand-500/60 bg-brand-500/15 text-brand-200" : "border-white/10 text-slate-400 hover:text-slate-200"}`} onClick={() => { setTab(t); setMsg(null); }}>
            {label}
          </button>
        ))}
      </div>
      <div className="space-y-2">
        {tab === "extend" && (
          <label className="flex items-center gap-2 text-xs text-slate-400">
            Days
            <input className="input w-24 py-1.5 text-sm" type="number" min={-365} max={365} value={days} onChange={(e) => setDays(e.target.value)} />
            <span>Recorded as gifted time (never prorates into refundable credit).</span>
          </label>
        )}
        {(tab === "credit" || tab === "refund") && (
          <div className="flex flex-wrap items-center gap-2 text-xs text-slate-400">
            <label className="flex items-center gap-2">
              Amount $
              <input className="input w-28 py-1.5 text-sm" type="number" step="0.01" value={amount} onChange={(e) => setAmount(e.target.value)} placeholder={tab === "credit" ? "5.00 or -5.00" : "5.00"} />
            </label>
            {tab === "refund" && <input className="input w-56 py-1.5 font-mono text-xs" placeholder="Invoice id (optional)" value={invoiceId} onChange={(e) => setInvoiceId(e.target.value)} />}
            <span>{tab === "refund" ? "Goes back to the original card when traceable, else wallet-only." : "Negative = debit."}</span>
          </div>
        )}
        {tab === "free" && <p className="text-xs text-slate-400">{isFree ? "Starts a gifted 30-day billing term; normal renewals follow." : "Removes billing and the expiry date. The server keeps running."}</p>}
        {tab === "transfer" && (
          <div className="space-y-2">
            <input className="input w-full py-1.5 text-sm" placeholder="New owner's account email" value={target} onChange={(e) => setTarget(e.target.value)} />
            <p className="text-xs text-slate-500">Moves the server plus its volumes, websites, databases, apps, cron and SSL. Invoices and history stay with the current owner. Renewals bill the new owner from now on.</p>
            <label className="flex items-center gap-2 text-xs text-slate-300">
              <input type="checkbox" checked={resetPw} onChange={(e) => setResetPw(e.target.checked)} /> Rotate the root password after the transfer
            </label>
            <input className="input w-60 py-1.5 font-mono text-xs" placeholder={`type ${hostname}`} value={confirm} onChange={(e) => setConfirm(e.target.value)} />
          </div>
        )}
        <ReasonInput value={reason} onChange={setReason} />
        {tab !== "free" && (
          <div className="flex flex-wrap gap-4 text-xs text-slate-300">
            <label className="flex items-center gap-2"><input type="checkbox" checked={notify} onChange={(e) => setNotify(e.target.checked)} /> In-app notification</label>
            <label className="flex items-center gap-2"><input type="checkbox" checked={email} onChange={(e) => setEmail(e.target.checked)} /> Email the customer</label>
          </div>
        )}
        <button className={tab === "transfer" || tab === "refund" ? "btn-danger py-1.5 text-sm" : "btn-primary py-1.5 text-sm"} onClick={go} disabled={pending}>
          {pending ? "Working…" : "Apply"}
        </button>
        {msg && <Notice tone={msg.tone}>{msg.text}</Notice>}
      </div>
    </div>
  );
}

