import Link from "next/link";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { latestDiagnosis } from "@/lib/admin-ops/actions";
import { GUEST_COMMANDS } from "@/lib/admin-ops/guest-commands";
import { controlSpec, isGameFamily } from "@/lib/game-control";
import { DiagnosePanel } from "./DiagnosePanel";
import { GuestTools, type GuestCommandMeta } from "./GuestTools";
import { IpOpsPanel } from "./IpOpsPanel";
import { CustomerOpsPanel } from "./CustomerOpsPanel";

/**
 * EMBEDDABLE admin ops panel for one server: Diagnose, guest tools, IP &
 * placement, customer ops. A server component — drop it into any admin page
 * that already knows the server id:
 *
 *   import { ServerOpsPanel } from "@/components/admin/ops/ServerOpsPanel";
 *   <ServerOpsPanel serverId={server.id} />
 *
 * It gates itself (fleet area) and loads everything it needs, so the host
 * page doesn't have to. `sections` limits which cards render (default all).
 * It uses only the admin portal's existing classes (card / btn-* / input), so
 * it inherits whatever chrome the host page has — no restyling of the host.
 */
export async function ServerOpsPanel({
  serverId,
  sections = ["diagnose", "guest", "ip", "customer"],
}: {
  serverId: string;
  sections?: ("diagnose" | "guest" | "ip" | "customer")[];
}) {
  await requireArea("fleet");
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: {
      node: { select: { id: true, name: true } },
      dedicatedIp: { select: { address: true } },
      gamePlan: { select: { gameFamily: true } },
      osTemplate: { select: { family: true } },
      user: { select: { id: true, email: true } },
    },
  });
  if (!server) return null;

  const primary = server.nodeId ? null : await db.node.findFirst({ where: { isPrimary: true }, select: { id: true } });
  const nodeId = server.nodeId ?? primary?.id ?? null;
  const [nodes, sameNode, freeIps, initial] = await Promise.all([
    db.node.findMany({ where: { enabled: true }, select: { id: true, name: true, region: true }, orderBy: { createdAt: "asc" } }),
    nodeId
      ? db.server.findMany({
          where: { status: { in: ["RUNNING", "STOPPED"] }, ...(server.nodeId ? { nodeId } : { OR: [{ nodeId }, { nodeId: null }] }) },
          select: { id: true, hostname: true, dedicatedIp: { select: { id: true } } },
          orderBy: { hostname: "asc" },
          take: 500,
        })
      : Promise.resolve([]),
    nodeId
      ? db.dedicatedIp.findMany({ where: { nodeId, status: "FREE", purpose: "CUSTOMER", serverId: null }, select: { address: true }, orderBy: { createdAt: "asc" } })
      : Promise.resolve([]),
    sections.includes("diagnose") ? latestDiagnosis(serverId) : Promise.resolve(null),
  ]);

  const family = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  const isGame = !!server.gamePlanId && isGameFamily(family);
  const spec = isGame ? controlSpec(family) : null;
  const commands: GuestCommandMeta[] = GUEST_COMMANDS.map((c) => ({
    key: c.key,
    label: c.label,
    description: c.description,
    params: c.params.map((p) => ({ name: p.name, label: p.label, kind: p.kind, default: p.default })),
  }));

  return (
    <div className="space-y-4" data-testid="server-ops-panel">
      {sections.includes("diagnose") && <DiagnosePanel serverId={server.id} initial={initial} />}
      {sections.includes("guest") && (
        <GuestTools serverId={server.id} commands={commands} isGame={isGame} gameUnit={spec?.serviceHints[0] ?? null} running={server.status === "RUNNING"} />
      )}
      <div className="grid gap-4 xl:grid-cols-2">
        {sections.includes("ip") && (
          <IpOpsPanel
            serverId={server.id}
            dedicatedIp={server.dedicatedIp?.address ?? null}
            sameNodeServers={sameNode.map((s) => ({ id: s.id, hostname: s.hostname, hasIp: !!s.dedicatedIp }))}
            freeIps={freeIps.map((r) => r.address)}
            nodes={nodes}
            currentNodeId={nodeId}
          />
        )}
        {sections.includes("customer") && (
          <CustomerOpsPanel
            serverId={server.id}
            hostname={server.hostname}
            ownerId={server.user.id}
            ownerEmail={server.user.email}
            isFree={server.isFree}
            expiresAt={server.expiresAt?.toISOString() ?? null}
          />
        )}
      </div>
      <p className="text-[11px] text-slate-500">
        Every action here is audited. Queue view:{" "}
        <Link className="text-brand-300 hover:underline" href={`/admin/ops/jobs?server=${server.id}`}>
          this server&apos;s jobs
        </Link>
      </p>
    </div>
  );
}

