import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatCard } from "@/components/ui/primitives";
import { OpsNav } from "@/components/admin/ops/OpsNav";
import { ServerSearch } from "@/components/admin/ops/ServerSearch";
import { STALE_QUEUED_MIN, STALE_RUNNING_MIN } from "@/lib/admin-ops/job-queue";
import type { DriftFinding } from "@/lib/admin-ops/drift";

export const dynamic = "force-dynamic";

/**
 * Admin Ops — the hard-coded, audited replacement for the operational chores
 * the owner used to delegate to an AI session (see docs/ADMIN-OPS-CATALOG.md).
 */
export default async function AdminOpsHome() {
  await requireArea("fleet");
  const now = Date.now();
  const [staleRunning, staleQueued, failed24h, notAccepting, lastScan, errorServers] = await Promise.all([
    db.job.count({ where: { status: "RUNNING", updatedAt: { lt: new Date(now - STALE_RUNNING_MIN * 60_000) }, NOT: { type: "ADMIN_OPS", payload: { path: ["op"], equals: "hold" } } } }),
    db.job.count({ where: { status: "QUEUED", createdAt: { lt: new Date(now - STALE_QUEUED_MIN * 60_000) } } }),
    db.job.count({ where: { status: "FAILED", updatedAt: { gte: new Date(now - 86400_000) } } }),
    db.node.count({ where: { enabled: true, acceptsProvisions: false } }),
    db.job.findFirst({ where: { type: "ADMIN_OPS", status: "DONE", payload: { path: ["op"], equals: "drift_scan" } }, orderBy: { createdAt: "desc" }, select: { payload: true, updatedAt: true } }),
    db.server.count({ where: { status: "ERROR" } }),
  ]);
  const findings = ((lastScan?.payload as { result?: { findings?: DriftFinding[] } } | null)?.result?.findings ?? []).filter((f) => f.severity !== "info");

  const tools = [
    { href: "/admin/ops/servers", title: "Diagnose a server", body: "One click: VM, guest agent, game service, port in guest, DNAT, outside probe, DNS, logs, resources, jobs → verdict + fixes." },
    { href: "/admin/ops/servers", title: "Guest tools", body: "Restart the game service, tail logs, run whitelisted diagnostics (no free shell)." },
    { href: "/admin/ops/servers", title: "IP & placement", body: "Give a dedicated IP to another server, release to NAT, assign from the pool, move node." },
    { href: "/admin/ops/jobs", title: "Job queue", body: "Stuck/failed jobs with requeue, cancel and force-fail — each with a reason." },
    { href: "/admin/ops/fleet", title: "Fleet", body: "DB↔Proxmox drift + orphan cleanup, bulk power/teardown with concurrency limits, node drain planner." },
    { href: "/admin/ops/customers", title: "Customers", body: "Credit, refund, extend, make free, transfer a server — reason + audit + optional notification." },
  ];

  return (
    <div>
      <PageHeader title="Ops console" sub="Safe, audited, hard-coded operations. Every action records who, what and why." />
      <OpsNav active="/admin/ops" />
      <div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-5">
        <StatCard label="Stuck running jobs" value={String(staleRunning)} href="/admin/ops/jobs?health=stale_running" />
        <StatCard label="Queued > 15 min" value={String(staleQueued)} href="/admin/ops/jobs?health=stale_queued" />
        <StatCard label="Failed jobs (24h)" value={String(failed24h)} href="/admin/ops/jobs?status=FAILED" />
        <StatCard label="Servers in ERROR" value={String(errorServers)} href="/admin/servers" />
        <StatCard label="Drift findings" value={lastScan ? String(findings.length) : "—"} href="/admin/ops/fleet" />
      </div>
      <div className="mb-6 card">
        <h2 className="mb-2 font-semibold">Find a server</h2>
        <ServerSearch />
      </div>
      {notAccepting > 0 && (
        <p className="mb-4 text-xs text-amber-300">{notAccepting} node(s) are currently not accepting new provisions (draining).</p>
      )}
      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        {tools.map((t) => (
          <Link key={t.title} href={t.href} className="card card-hover block">
            <h3 className="font-semibold">{t.title}</h3>
            <p className="mt-1 text-sm text-slate-400">{t.body}</p>
          </Link>
        ))}
      </div>
      <p className="mt-6 text-xs text-slate-500">
        Last drift scan: {lastScan ? lastScan.updatedAt.toLocaleString() : "never"} · Catalog of covered chores: docs/ADMIN-OPS-CATALOG.md
      </p>
    </div>
  );
}

