import Link from "next/link";
import type { Prisma } from "@prisma/client";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatusDot } from "@/components/ui/primitives";
import { OpsNav } from "@/components/admin/ops/OpsNav";
import { ServerSearch } from "@/components/admin/ops/ServerSearch";

export const dynamic = "force-dynamic";

export default async function OpsServerSearch({ searchParams }: { searchParams: Promise<{ q?: string }> }) {
  await requireArea("fleet");
  const q = String((await searchParams).q ?? "").trim().slice(0, 120);
  let where: Prisma.ServerWhereInput = { status: { in: ["ERROR", "PROVISIONING", "PENDING"] } };
  if (q) {
    const n = Number(q);
    where = {
      OR: [
        { hostname: { contains: q, mode: "insensitive" } },
        { label: { contains: q, mode: "insensitive" } },
        { subdomain: { contains: q, mode: "insensitive" } },
        { ipAddress: { contains: q } },
        { id: q },
        { user: { email: { contains: q, mode: "insensitive" } } },
        { dedicatedIp: { address: { contains: q } } },
        ...(Number.isInteger(n) && n > 0 ? [{ vmid: n }, { sshPort: n }] : []),
      ],
    };
  }
  const servers = await db.server.findMany({
    where,
    take: 60,
    orderBy: { updatedAt: "desc" },
    select: {
      id: true,
      hostname: true,
      status: true,
      vmid: true,
      ipAddress: true,
      user: { select: { email: true } },
      node: { select: { name: true } },
      gamePlan: { select: { gameFamily: true } },
      dedicatedIp: { select: { address: true } },
    },
  });
  return (
    <div>
      <PageHeader title="Server ops" sub={q ? `Results for “${q}”` : "Servers needing attention (ERROR / stuck provisioning) — or search."} />
      <OpsNav active="/admin/ops/servers" />
      <div className="mb-4">
        <ServerSearch defaultValue={q} />
      </div>
      <div className="card overflow-x-auto p-0">
        <table className="w-full min-w-[640px] text-sm">
          <thead className="text-left text-xs text-slate-400">
            <tr>
              <th className="px-4 py-3">Server</th>
              <th className="px-4 py-3">Status</th>
              <th className="px-4 py-3">Node</th>
              <th className="px-4 py-3">Address</th>
              <th className="px-4 py-3">Owner</th>
            </tr>
          </thead>
          <tbody>
            {servers.map((s) => (
              <tr key={s.id} className="border-t border-white/[0.06] hover:bg-white/[0.02]">
                <td className="px-4 py-2.5">
                  <Link className="font-medium hover:text-brand-300" href={`/admin/ops/servers/${s.id}`}>
                    {s.hostname}
                  </Link>
                  <span className="ml-2 text-xs text-slate-500">{s.gamePlan?.gameFamily ?? "vps"}{s.vmid ? ` · ${s.vmid}` : ""}</span>
                </td>
                <td className="px-4 py-2.5"><StatusDot status={s.status} /></td>
                <td className="px-4 py-2.5 text-slate-400">{s.node?.name ?? "primary"}</td>
                <td className="px-4 py-2.5 font-mono text-xs text-slate-400">{s.dedicatedIp?.address ?? s.ipAddress ?? "—"}</td>
                <td className="px-4 py-2.5 text-slate-400">{s.user.email}</td>
              </tr>
            ))}
            {servers.length === 0 && (
              <tr>
                <td colSpan={5} className="px-4 py-8 text-center text-sm text-slate-500">
                  {q ? "No servers match." : "Nothing needs attention right now."}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

