"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { jobIntervene } from "@/lib/admin-ops/actions";
import { Notice } from "./shared";

export type JobRow = {
  id: string;
  type: string;
  op: string | null;
  status: string;
  attempts: number;
  error: string | null;
  step: string | null;
  serverId: string | null;
  hostname: string | null;
  ageMin: number;
  silentMin: number;
  health: "ok" | "stale_running" | "stale_queued" | "failed";
  allowed: { requeue: string | null; cancel: string | null; force_fail: string | null };
};

const HEALTH: Record<JobRow["health"], string> = {
  ok: "",
  stale_running: "text-red-300",
  stale_queued: "text-amber-300",
  failed: "text-red-400",
};

const VERB_LABEL = { requeue: "Re-queue", cancel: "Cancel", force_fail: "Force-fail" } as const;

/**
 * Job queue manager. Each button is shown only when lib/admin-ops/job-queue.ts
 * allows that intervention for that job (the server action re-checks); a
 * disabled button's tooltip says why not. Every intervention asks for a reason.
 */
export function JobQueueTable({ rows }: { rows: JobRow[] }) {
  const router = useRouter();
  const [busy, setBusy] = useState<string | null>(null);
  const [msg, setMsg] = useState<{ tone: "ok" | "err"; text: string } | null>(null);

  const act = async (j: JobRow, verb: keyof typeof VERB_LABEL) => {
    const reason = window.prompt(`${VERB_LABEL[verb]} ${j.type} ${j.hostname ?? ""} — reason for the audit log:`);
    if (!reason) return;
    setBusy(`${j.id}:${verb}`);
    const r = await jobIntervene(j.id, verb, reason);
    setBusy(null);
    setMsg(r.ok ? { tone: "ok", text: `${j.type}: ${r.message}` } : { tone: "err", text: r.error });
    if (r.ok) router.refresh();
  };

  return (
    <div className="space-y-3">
      {msg && <Notice tone={msg.tone}>{msg.text}</Notice>}
      <div className="card overflow-x-auto p-0">
        <table className="w-full min-w-[860px] text-sm" data-testid="job-queue">
          <thead className="text-left text-xs text-slate-400">
            <tr>
              <th className="px-3 py-3">Job</th>
              <th className="px-3 py-3">Server</th>
              <th className="px-3 py-3">Status</th>
              <th className="px-3 py-3">Age</th>
              <th className="px-3 py-3">Error / step</th>
              <th className="px-3 py-3 text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((j) => (
              <tr key={j.id} className="border-t border-white/[0.06] align-top">
                <td className="px-3 py-2.5">
                  <span className="font-medium">{j.type.toLowerCase()}</span>
                  {j.op && <span className="ml-1 text-xs text-slate-500">· {j.op}</span>}
                  <div className="font-mono text-[10px] text-slate-600">{j.id}</div>
                </td>
                <td className="px-3 py-2.5">
                  {j.serverId ? (
                    <Link className="hover:text-brand-300" href={`/admin/ops/servers/${j.serverId}`}>
                      {j.hostname ?? j.serverId}
                    </Link>
                  ) : (
                    <span className="text-slate-500">platform</span>
                  )}
                </td>
                <td className={`px-3 py-2.5 text-xs ${HEALTH[j.health]}`}>
                  {j.status.toLowerCase()} · try {j.attempts}
                  {j.health === "stale_running" && <div>silent {j.silentMin} min</div>}
                  {j.health === "stale_queued" && <div>waiting {j.ageMin} min</div>}
                </td>
                <td className="px-3 py-2.5 text-xs text-slate-400">{j.ageMin < 120 ? `${j.ageMin} min` : `${Math.round(j.ageMin / 60)} h`}</td>
                <td className="max-w-md px-3 py-2.5 text-xs">
                  {j.error ? <span className="break-words text-red-400">{j.error.slice(0, 260)}</span> : <span className="text-slate-500">{j.step ?? ""}</span>}
                </td>
                <td className="px-3 py-2.5">
                  <div className="flex justify-end gap-1.5">
                    {(Object.keys(VERB_LABEL) as (keyof typeof VERB_LABEL)[]).map((v) => {
                      const why = j.allowed[v];
                      const relevant = (v === "requeue" && j.status === "FAILED") || (v === "cancel" && j.status === "QUEUED") || (v === "force_fail" && j.status === "RUNNING");
                      if (!relevant) return null;
                      return (
                        <button key={v} className={v === "requeue" ? "btn-secondary py-1 text-xs" : "btn-danger py-1 text-xs"} disabled={!!why || !!busy} title={why ?? ""} onClick={() => act(j, v)}>
                          {busy === `${j.id}:${v}` ? "…" : VERB_LABEL[v]}
                        </button>
                      );
                    })}
                  </div>
                </td>
              </tr>
            ))}
            {rows.length === 0 && (
              <tr>
                <td colSpan={6} className="px-4 py-8 text-center text-sm text-slate-500">
                  No jobs match.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

