import Link from "next/link";
import type { Prisma } from "@prisma/client";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader } from "@/components/ui/primitives";
import { AutoRefresh } from "@/components/AutoRefresh";
import { OpsNav } from "@/components/admin/ops/OpsNav";
import { JobQueueTable, type JobRow } from "@/components/admin/ops/JobQueueTable";
import { jobHealth, whyNot, ageMin, STALE_QUEUED_MIN, STALE_RUNNING_MIN } from "@/lib/admin-ops/job-queue";

export const dynamic = "force-dynamic";

const FILTERS = [
  { key: "active", label: "Active" },
  { key: "stale", label: "Stuck" },
  { key: "FAILED", label: "Failed (7d)" },
  { key: "all", label: "All recent" },
];

export default async function OpsJobs({ searchParams }: { searchParams: Promise<{ status?: string; health?: string; server?: string; type?: string }> }) {
  await requireArea("fleet");
  const sp = await searchParams;
  const now = new Date();
  const filter = sp.health ? "stale" : sp.status === "FAILED" ? "FAILED" : sp.status === "all" ? "all" : sp.status ?? "active";
  const where: Prisma.JobWhereInput = {};
  if (sp.server && /^[a-z0-9]{8,40}$/i.test(sp.server)) where.serverId = sp.server;
  if (sp.type && /^[A-Z_]{3,30}$/.test(sp.type)) where.type = sp.type as Prisma.JobWhereInput["type"];
  if (filter === "active") where.status = { in: ["QUEUED", "RUNNING"] };
  else if (filter === "FAILED") Object.assign(where, { status: "FAILED", updatedAt: { gte: new Date(now.getTime() - 7 * 86400_000) } });
  else if (filter === "stale")
    where.OR = [
      { status: "RUNNING", updatedAt: { lt: new Date(now.getTime() - STALE_RUNNING_MIN * 60_000) } },
      { status: "QUEUED", createdAt: { lt: new Date(now.getTime() - STALE_QUEUED_MIN * 60_000) } },
    ];
  const jobs = await db.job.findMany({ where, orderBy: { createdAt: "desc" }, take: 200, include: { server: { select: { hostname: true } } } });
  const rows: JobRow[] = jobs
    .filter((j) => !(j.type === "ADMIN_OPS" && (j.payload as { op?: string } | null)?.op === "hold" && filter === "stale"))
    .map((j) => ({
      id: j.id,
      type: j.type,
      op: j.type === "ADMIN_OPS" ? ((j.payload as { op?: string } | null)?.op ?? null) : null,
      status: j.status,
      attempts: j.attempts,
      error: j.error,
      step: j.step,
      serverId: j.serverId,
      hostname: j.server?.hostname ?? null,
      ageMin: ageMin(j.createdAt, now),
      silentMin: ageMin(j.updatedAt, now),
      health: jobHealth(j, now),
      allowed: { requeue: whyNot("requeue", j, now), cancel: whyNot("cancel", j, now), force_fail: whyNot("force_fail", j, now) },
    }));
  const active = rows.some((r) => r.status === "QUEUED" || r.status === "RUNNING");
  const qs = (k: string) => {
    const p = new URLSearchParams();
    if (k === "stale") p.set("health", "stale");
    else p.set("status", k);
    if (sp.server) p.set("server", sp.server);
    return `/admin/ops/jobs?${p.toString()}`;
  };
  return (
    <div>
      {active && <AutoRefresh intervalMs={8000} />}
      <PageHeader title="Job queue" sub={`Running jobs silent for ${STALE_RUNNING_MIN}+ min and queued jobs waiting ${STALE_QUEUED_MIN}+ min are flagged.`} />
      <OpsNav active="/admin/ops/jobs" />
      <div className="mb-4 flex flex-wrap gap-1.5">
        {FILTERS.map((f) => (
          <Link key={f.key} href={qs(f.key)} className={`rounded-full border px-3 py-1 text-xs ${filter === f.key ? "border-brand-500/60 bg-brand-500/15 text-brand-200" : "border-white/10 text-slate-400 hover:text-slate-200"}`}>
            {f.label}
          </Link>
        ))}
        {sp.server && (
          <Link href="/admin/ops/jobs" className="rounded-full border border-white/10 px-3 py-1 text-xs text-slate-400">
            × server filter
          </Link>
        )}
      </div>
      <JobQueueTable rows={rows} />
      <p className="mt-3 text-xs text-slate-500">
        Never re-queueable: RESIZE / DISK_EXPAND / ASSIGN_DEDICATED_IP (refunded on failure) and PROVISION (use Retry provisioning). Force-fail only after {STALE_RUNNING_MIN} silent minutes.
      </p>
    </div>
  );
}

