"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { startDriftScan, startOrphanVmDestroy, startOrphanIpRelease, applyFix, type OpJobView } from "@/lib/admin-ops/actions";
import type { DriftFinding } from "@/lib/admin-ops/drift";
import { useOpJob, JobProgress, Notice, SectionTitle } from "./shared";

const SEV: Record<DriftFinding["severity"], string> = {
  high: "border-red-500/40 bg-red-500/10 text-red-300",
  medium: "border-amber-500/40 bg-amber-500/10 text-amber-300",
  low: "border-white/15 text-slate-300",
  info: "border-white/10 text-slate-500",
};

/**
 * DB ↔ Proxmox drift + orphan detector with SAFE one-click cleanup. Only the
 * findings lib/admin-ops/drift.ts marks fixable get a button; destructive ones
 * need a typed confirmation and a reason, and the worker re-verifies before acting.
 */
export function DriftPanel({ initial }: { initial: OpJobView | null }) {
  const router = useRouter();
  const [jobId, setJobId] = useState<string | null>(initial && (initial.status === "QUEUED" || initial.status === "RUNNING") ? initial.id : null);
  const { job, busy } = useOpJob(jobId, initial);
  const [msg, setMsg] = useState<{ tone: "ok" | "err"; text: string } | null>(null);
  const [showInfo, setShowInfo] = useState(false);
  const [working, setWorking] = useState<string | null>(null);
  const result = job?.result as { findings?: DriftFinding[]; scannedNodes?: { name: string; vms: number | null }[] } | null;
  const findings = (result?.findings ?? []).filter((f) => showInfo || f.severity !== "info");

  const scan = async () => {
    setMsg(null);
    const r = await startDriftScan();
    if (!r.ok) setMsg({ tone: "err", text: r.error });
    else setJobId(r.jobId);
  };

  const fix = async (f: DriftFinding, i: number) => {
    const key = `${i}`;
    setMsg(null);
    if (f.fix === "orphan_vm_destroy" && f.nodeId && f.vmid) {
      const confirm = window.prompt(`Destroy orphan VM ${f.vmid} on ${f.nodeName}? Its disks are purged. Type the vmid to confirm:`);
      if (!confirm) return;
      const reason = window.prompt("Reason (audit log):");
      if (!reason) return;
      setWorking(key);
      const r = await startOrphanVmDestroy(f.nodeId, f.vmid, reason, confirm);
      setWorking(null);
      setMsg(r.ok ? { tone: "ok", text: `Destroy queued (job ${r.jobId}). Re-scan when it finishes.` } : { tone: "err", text: r.error });
    } else if (f.fix === "orphan_ip_release" && f.ipId) {
      const reason = window.prompt(`Release this IP back to the free pool? Reason (audit log):`);
      if (!reason) return;
      setWorking(key);
      const r = await startOrphanIpRelease(f.ipId, reason);
      setWorking(null);
      setMsg(r.ok ? { tone: "ok", text: `Release queued (job ${r.jobId}).` } : { tone: "err", text: r.error });
    } else if (f.fix === "reconcile_status" && f.serverId) {
      setWorking(key);
      const r = await applyFix(f.serverId, "reconcile_status");
      setWorking(null);
      setMsg(r.ok ? { tone: "ok", text: r.message } : { tone: "err", text: r.error });
    } else if (f.fix === "diagnose" && f.serverId) {
      router.push(`/admin/ops/servers/${f.serverId}`);
    }
  };

  return (
    <div className="card" data-testid="drift-panel">
      <SectionTitle
        title="Drift & orphans"
        sub="Every node's VM list vs the database: orphan/unmanaged VMs, missing or misplaced VMs, status mismatches, stranded servers, IP pool conflicts, missing templates."
        right={
          <button className="btn-primary py-1.5 text-sm" onClick={scan} disabled={busy}>
            {busy ? "Scanning…" : "Run drift scan"}
          </button>
        }
      />
      <JobProgress job={job} busy={busy} />
      {msg && <div className="mt-3"><Notice tone={msg.tone}>{msg.text}</Notice></div>}
      {result && !busy && (
        <div className="mt-3 space-y-2">
          <div className="flex flex-wrap items-center justify-between gap-2 text-xs text-slate-400">
            <span>
              Scanned {result.scannedNodes?.map((n) => `${n.name} (${n.vms ?? "unreachable"})`).join(", ")} · {job ? new Date(job.updatedAt).toLocaleString() : ""}
            </span>
            <label className="flex items-center gap-2">
              <input type="checkbox" checked={showInfo} onChange={(e) => setShowInfo(e.target.checked)} /> show unmanaged/internal VMs
            </label>
          </div>
          {findings.length === 0 && <Notice tone="ok">No drift found.</Notice>}
          {findings.map((f, i) => (
            <div key={i} className="flex flex-wrap items-start justify-between gap-3 rounded-lg border border-white/10 bg-white/[0.02] p-3">
              <div className="min-w-0 flex-1">
                <div className="flex flex-wrap items-center gap-2">
                  <span className={`rounded-full border px-2 py-0.5 text-[10px] uppercase ${SEV[f.severity]}`}>{f.severity}</span>
                  <span className="text-sm font-medium">{f.title}</span>
                </div>
                <p className="mt-1 text-xs text-slate-400">{f.detail}</p>
                {f.serverId && (
                  <Link className="mt-1 inline-block text-xs text-brand-300 hover:underline" href={`/admin/ops/servers/${f.serverId}`}>
                    {f.hostname ?? "server"} →
                  </Link>
                )}
              </div>
              {f.fix && (
                <button className={f.fix === "orphan_vm_destroy" ? "btn-danger py-1 text-xs" : "btn-secondary py-1 text-xs"} disabled={!!working} onClick={() => fix(f, i)}>
                  {working === `${i}` ? "…" : f.fix === "orphan_vm_destroy" ? "Destroy VM" : f.fix === "orphan_ip_release" ? "Release IP" : f.fix === "reconcile_status" ? "Reconcile" : "Diagnose"}
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

