"use client";

import { useMemo, useState } from "react";
import { startBulkPower } from "@/lib/admin-ops/actions";
import { useOpJob, JobProgress, Notice, ReasonInput, SectionTitle } from "./shared";

export type BulkRow = {
  id: string;
  hostname: string;
  status: string;
  node: string;
  owner: string;
  isGame: boolean;
  testAccount: boolean;
};

const ACTIONS = [
  { key: "reboot", label: "Reboot VM" },
  { key: "start", label: "Start VM" },
  { key: "stop", label: "Stop VM" },
  { key: "game_restart", label: "Restart game service" },
  { key: "delete", label: "Delete (test accounts only)" },
] as const;

/**
 * Bulk power / teardown with a concurrency cap. The worker job releases the
 * next server only when one of the in-flight ones finishes; ineligible
 * servers (wrong state, busy, real customer for delete) are skipped and
 * reported, never forced.
 */
export function BulkPowerPanel({ rows }: { rows: BulkRow[] }) {
  const [filter, setFilter] = useState("");
  const [testOnly, setTestOnly] = useState(false);
  const [sel, setSel] = useState<Set<string>>(new Set());
  const [action, setAction] = useState<(typeof ACTIONS)[number]["key"]>("reboot");
  const [concurrency, setConcurrency] = useState(2);
  const [reason, setReason] = useState("");
  const [confirm, setConfirm] = useState("");
  const [msg, setMsg] = useState<{ tone: "ok" | "err"; text: string } | null>(null);
  const [jobId, setJobId] = useState<string | null>(null);
  const { job, busy } = useOpJob(jobId);

  const visible = useMemo(() => {
    const q = filter.trim().toLowerCase();
    return rows.filter((r) => (!testOnly || r.testAccount) && (!q || `${r.hostname} ${r.owner} ${r.node} ${r.status}`.toLowerCase().includes(q)));
  }, [rows, filter, testOnly]);
  const expected = `${action.toUpperCase()} ${sel.size}`;
  const toggle = (id: string) => setSel((s) => { const n = new Set(s); n.has(id) ? n.delete(id) : n.add(id); return n; });
  const summary = job?.result as { done?: number; failed?: number; skipped?: number; children?: { serverId: string; status?: string; skipped?: string }[] } | null;

  const go = async () => {
    setMsg(null);
    const r = await startBulkPower(action, [...sel], concurrency, reason, confirm);
    if (!r.ok) return setMsg({ tone: "err", text: r.error });
    setJobId(r.jobId);
    setMsg({ tone: "ok", text: "Bulk run started." });
  };

  return (
    <div className="card" data-testid="bulk-panel">
      <SectionTitle title="Bulk actions" sub="Select servers, pick an action and a concurrency limit. Delete only ever applies to staff/test accounts." />
      <div className="mb-2 flex flex-wrap items-center gap-2">
        <input className="input min-w-0 flex-1 py-1.5 text-sm" placeholder="Filter by hostname, owner, node, status…" value={filter} onChange={(e) => setFilter(e.target.value)} />
        <label className="flex items-center gap-2 text-xs text-slate-300"><input type="checkbox" checked={testOnly} onChange={(e) => setTestOnly(e.target.checked)} /> test/staff accounts only</label>
        <button className="btn-ghost py-1 text-xs" onClick={() => setSel(new Set(visible.map((r) => r.id)))}>Select shown ({visible.length})</button>
        <button className="btn-ghost py-1 text-xs" onClick={() => setSel(new Set())}>Clear</button>
      </div>
      <div className="max-h-72 overflow-auto rounded-lg border border-white/10">
        <table className="w-full text-xs">
          <tbody>
            {visible.map((r) => (
              <tr key={r.id} className="border-b border-white/[0.05]">
                <td className="w-8 px-2 py-1.5"><input type="checkbox" aria-label={`select ${r.hostname}`} checked={sel.has(r.id)} onChange={() => toggle(r.id)} /></td>
                <td className="px-2 py-1.5 font-medium">{r.hostname}{r.isGame && <span className="ml-1 text-slate-500">game</span>}</td>
                <td className="px-2 py-1.5 text-slate-400">{r.status.toLowerCase()}</td>
                <td className="px-2 py-1.5 text-slate-400">{r.node}</td>
                <td className="px-2 py-1.5 text-slate-400">{r.owner}{r.testAccount && <span className="ml-1 text-emerald-400">test</span>}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="mt-3 flex flex-wrap items-center gap-2">
        <select className="input py-1.5 text-sm" value={action} onChange={(e) => setAction(e.target.value as typeof action)}>
          {ACTIONS.map((a) => <option key={a.key} value={a.key}>{a.label}</option>)}
        </select>
        <label className="flex items-center gap-2 text-xs text-slate-400">
          Concurrency
          <input className="input w-16 py-1.5 text-sm" type="number" min={1} max={8} value={concurrency} onChange={(e) => setConcurrency(Number(e.target.value))} />
        </label>
        <span className="text-xs text-slate-400">{sel.size} selected</span>
      </div>
      <div className="mt-2 space-y-2">
        <ReasonInput value={reason} onChange={setReason} />
        <div className="flex flex-wrap items-center gap-2">
          <input className="input w-48 py-1.5 font-mono text-xs" placeholder={`type ${expected}`} value={confirm} onChange={(e) => setConfirm(e.target.value)} />
          <button className="btn-danger py-1.5 text-sm" disabled={busy || sel.size === 0 || confirm.trim().toUpperCase() !== expected} onClick={go}>
            {busy ? "Running…" : `Run on ${sel.size}`}
          </button>
        </div>
        {msg && <Notice tone={msg.tone}>{msg.text}</Notice>}
        <JobProgress job={job} busy={busy} />
        {summary?.children && (
          <p className="text-xs text-slate-400">
            done {summary.children.filter((c) => c.status === "DONE").length} · failed {summary.children.filter((c) => c.status === "FAILED").length} · skipped {summary.children.filter((c) => c.skipped).length}
            {summary.children.filter((c) => c.skipped).slice(0, 5).map((c) => (
              <span key={c.serverId} className="block text-slate-500">{rows.find((r) => r.id === c.serverId)?.hostname ?? c.serverId}: {c.skipped}</span>
            ))}
          </p>
        )}
      </div>
    </div>
  );
}

