"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { previewDrain, setNodeDraining, requestServerMove } from "@/lib/admin-ops/actions";
import type { DrainPlan } from "@/lib/admin-ops/drain-planner";
import { Notice, ReasonInput, SectionTitle } from "./shared";

/**
 * Node drain / rebalance planner. Plans only — executing moves calls the VM
 * move engine (vm-node-migration branch) one server at a time; the planner
 * never moves anything by itself.
 */
export function DrainPlanner({ nodes }: { nodes: { id: string; name: string; region: string; acceptsProvisions: boolean }[] }) {
  const router = useRouter();
  const [nodeId, setNodeId] = useState(nodes[0]?.id ?? "");
  const [mode, setMode] = useState<"drain" | "rebalance">("rebalance");
  const [targetPct, setTargetPct] = useState(75);
  const [cross, setCross] = useState(false);
  const [plan, setPlan] = useState<DrainPlan | null>(null);
  const [reason, setReason] = useState("");
  const [msg, setMsg] = useState<{ tone: "ok" | "err" | "info"; text: string } | null>(null);
  const node = nodes.find((n) => n.id === nodeId);

  const preview = async () => {
    setMsg(null);
    const r = await previewDrain(nodeId, mode, targetPct, cross);
    if (!r.ok) return setMsg({ tone: "err", text: r.error });
    setPlan(r.plan);
  };
  const toggleDrain = async () => {
    if (!node) return;
    const r = await setNodeDraining(node.id, node.acceptsProvisions, reason);
    setMsg(r.ok ? { tone: "ok", text: node.acceptsProvisions ? `${node.name} no longer accepts new provisions.` : `${node.name} accepts provisions again.` } : { tone: "err", text: r.error });
    if (r.ok) router.refresh();
  };
  const move = async (serverId: string, toNodeId: string) => {
    const r = await requestServerMove(serverId, toNodeId, false, reason);
    setMsg(r.ok ? { tone: "ok", text: `Move requested${r.jobId ? ` (job ${r.jobId})` : ""}.` } : { tone: r.engineMissing ? "info" : "err", text: r.error });
  };

  return (
    <div className="card" data-testid="drain-planner">
      <SectionTitle title="Drain / rebalance planner" sub="Same-region first, committed RAM, largest servers first, 10% headroom kept on every target. Plans only." />
      <div className="flex flex-wrap items-end gap-2">
        <select className="input py-1.5 text-sm" value={nodeId} onChange={(e) => { setNodeId(e.target.value); setPlan(null); }}>
          {nodes.map((n) => <option key={n.id} value={n.id}>{n.name} · {n.region}{n.acceptsProvisions ? "" : " (draining)"}</option>)}
        </select>
        <select className="input py-1.5 text-sm" value={mode} onChange={(e) => setMode(e.target.value as "drain" | "rebalance")}>
          <option value="rebalance">Rebalance to target</option>
          <option value="drain">Drain completely</option>
        </select>
        {mode === "rebalance" && (
          <label className="flex items-center gap-2 text-xs text-slate-400">
            target %
            <input className="input w-16 py-1.5 text-sm" type="number" min={10} max={100} value={targetPct} onChange={(e) => setTargetPct(Number(e.target.value))} />
          </label>
        )}
        <label className="flex items-center gap-2 text-xs text-slate-300"><input type="checkbox" checked={cross} onChange={(e) => setCross(e.target.checked)} /> allow other regions</label>
        <button className="btn-secondary py-1.5 text-sm" onClick={preview}>Plan</button>
      </div>
      <div className="mt-2"><ReasonInput value={reason} onChange={setReason} /></div>
      {node && (
        <button className="btn-ghost mt-2 py-1 text-xs" onClick={toggleDrain}>
          {node.acceptsProvisions ? `Stop new provisions on ${node.name}` : `Resume provisions on ${node.name}`}
        </button>
      )}
      {msg && <div className="mt-2"><Notice tone={msg.tone}>{msg.text}</Notice></div>}
      {plan && (
        <div className="mt-3 space-y-3 text-xs">
          <div className="flex flex-wrap gap-3">
            {plan.after.map((a) => (
              <span key={a.nodeId} className="rounded-lg border border-white/10 px-2 py-1 text-slate-300">
                {a.name}: {a.beforePct}% → <span className={a.afterPct > 90 ? "text-red-300" : a.afterPct > 80 ? "text-amber-300" : "text-emerald-300"}>{a.afterPct}%</span>
              </span>
            ))}
          </div>
          {plan.moves.length === 0 && <Notice tone="info">Nothing to move.</Notice>}
          {plan.moves.length > 0 && (
            <table className="w-full">
              <thead className="text-left text-slate-500"><tr><th className="py-1">Server</th><th>RAM</th><th>To</th><th>Notes</th><th /></tr></thead>
              <tbody>
                {plan.moves.map((m) => (
                  <tr key={m.serverId} className="border-t border-white/[0.06]">
                    <td className="py-1.5">{m.hostname}</td>
                    <td>{(m.ramMB / 1024).toFixed(1)} GB</td>
                    <td>{m.toNodeName}</td>
                    <td className="text-amber-300">{[m.crossRegion && "cross-region", m.needsIpWork && "dedicated IP must be re-routed"].filter(Boolean).join(" · ")}</td>
                    <td className="text-right"><button className="btn-secondary py-0.5 text-xs" onClick={() => move(m.serverId, m.toNodeId)}>Move</button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
          {plan.unplaceable.length > 0 && (
            <div className="text-red-300">
              {plan.unplaceable.map((u) => <p key={u.serverId}>{u.hostname} ({(u.ramMB / 1024).toFixed(1)} GB): {u.reason}</p>)}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

