import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader } from "@/components/ui/primitives";
import { OpsNav } from "@/components/admin/ops/OpsNav";
import { DriftPanel } from "@/components/admin/ops/DriftPanel";
import { BulkPowerPanel, type BulkRow } from "@/components/admin/ops/BulkPowerPanel";
import { DrainPlanner } from "@/components/admin/ops/DrainPlanner";
import { latestDriftScan } from "@/lib/admin-ops/actions";

export const dynamic = "force-dynamic";

export default async function OpsFleet() {
  await requireArea("fleet");
  const [initial, nodes, servers] = await Promise.all([
    latestDriftScan(),
    db.node.findMany({ where: { enabled: true }, orderBy: { createdAt: "asc" }, select: { id: true, name: true, region: true, acceptsProvisions: true, isPrimary: true } }),
    db.server.findMany({
      where: { status: { notIn: ["DELETING"] } },
      orderBy: { hostname: "asc" },
      take: 1000,
      select: { id: true, hostname: true, status: true, gamePlanId: true, nodeId: true, user: { select: { email: true, role: true, excludeFromRevenue: true } } },
