import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatusDot, fmtMoney } from "@/components/ui/primitives";
import { OpsNav } from "@/components/admin/ops/OpsNav";
import { CustomerOpsPanel } from "@/components/admin/ops/CustomerOpsPanel";

export const dynamic = "force-dynamic";

export default async function OpsCustomers({ searchParams }: { searchParams: Promise<{ q?: string; user?: string }> }) {
  await requireArea("billing");
  const sp = await searchParams;
  const q = String(sp.q ?? "").trim().slice(0, 120);
  const users = q
    ? await db.user.findMany({
        where: { OR: [{ email: { contains: q, mode: "insensitive" } }, { name: { contains: q, mode: "insensitive" } }, { id: q }] },
        take: 20,
        orderBy: { createdAt: "desc" },
        select: { id: true, email: true, name: true },
      })
    : [];
  const userId = sp.user && /^[a-z0-9]{8,40}$/i.test(sp.user) ? sp.user : users.length === 1 ? users[0].id : null;
  const user = userId
    ? await db.user.findUnique({
        where: { id: userId },
        select: {
          id: true,
          email: true,
          name: true,
          balanceCents: true,
          suspended: true,
          servers: { orderBy: { createdAt: "desc" }, select: { id: true, hostname: true, status: true, isFree: true, expiresAt: true, gamePlan: { select: { gameFamily: true } } } },
          walletTransactions: { orderBy: { createdAt: "desc" }, take: 8, select: { id: true, amountCents: true, description: true, createdAt: true } },
        },
      })
    : null;

  return (
    <div>
      <PageHeader title="Customer ops" sub="Credit, refund, extend, make free and transfer — reason, audit and optional notification on every action." />
      <OpsNav active="/admin/ops/customers" />
      <form action="/admin/ops/customers" method="get" className="mb-4 flex flex-wrap gap-2">
        <input name="q" defaultValue={q} className="input min-w-0 flex-1 py-2 text-sm" placeholder="Customer email, name or id" aria-label="Search customers" />
        <button className="btn-primary py-2 text-sm">Search</button>
      </form>
      {users.length > 1 && !user && (
        <div className="card mb-4 p-0">
          {users.map((u) => (
            <Link key={u.id} href={`/admin/ops/customers?user=${u.id}`} className="block border-b border-white/[0.06] px-4 py-2.5 text-sm hover:bg-white/[0.02]">
              {u.email} <span className="text-slate-500">{u.name}</span>
            </Link>
          ))}
        </div>
      )}
      {q && users.length === 0 && <p className="text-sm text-slate-500">No customer matches.</p>}
      {user && (
        <div className="grid gap-4 xl:grid-cols-2">
          <div className="space-y-4">
            <div className="card">
              <h2 className="font-semibold">{user.email}</h2>
              <p className="mt-1 text-sm text-slate-400">
                Wallet {fmtMoney(user.balanceCents)}
                {user.suspended && <span className="ml-2 text-red-400">suspended</span>} ·{" "}
                <Link className="text-brand-300 hover:underline" href={`/admin/users/${user.id}`}>
                  profile
                </Link>
              </p>
              <ul className="mt-3 divide-y divide-white/[0.06] text-sm">
                {user.servers.map((s) => (
                  <li key={s.id} className="flex items-center justify-between gap-2 py-2">
                    <Link className="hover:text-brand-300" href={`/admin/ops/servers/${s.id}`}>
                      {s.hostname} <span className="text-xs text-slate-500">{s.gamePlan?.gameFamily ?? "vps"}{s.isFree ? " · free" : ""}</span>
                    </Link>
                    <StatusDot status={s.status} />
                  </li>
                ))}
                {user.servers.length === 0 && <li className="py-2 text-slate-500">No servers.</li>}
              </ul>
            </div>
            <div className="card">
              <h3 className="mb-2 text-sm font-semibold">Recent wallet activity</h3>
              <ul className="space-y-1 text-xs">
                {user.walletTransactions.map((t) => (
                  <li key={t.id} className="flex justify-between gap-2">
                    <span className="truncate text-slate-400">{t.description}</span>
                    <span className={t.amountCents >= 0 ? "text-emerald-300" : "text-slate-300"}>{fmtMoney(t.amountCents)}</span>
                  </li>
                ))}
              </ul>
            </div>
          </div>
          <CustomerOpsPanel serverId={null} hostname="" ownerId={user.id} ownerEmail={user.email} isFree={false} expiresAt={null} />
        </div>
      )}
    </div>
  );
}

