    const head = SRC.slice(index, index + 2000);
    const bodyMatch = /\)\s*:\s*[\s\S]*?\{\s*\n([\s\S]{0,200})/.exec(head) ?? /\)\s*\{\s*\n([\s\S]{0,200})/.exec(head);
    const first = bodyMatch?.[1]?.trim() ?? SRC.slice(i, i + 200);
    if (!/^(const\s+\w+\s*=\s*)?await gate\(/.test(first)) offenders.push(name);
  }
  assert.deepEqual(offenders, [], "these admin-ops endpoints do not open with gate()");
});

test("money ops gate on the billing area, everything else on fleet", () => {
  for (const name of ["customerCredit", "customerRefund", "customerExtend", "customerSetFree"]) {
    const at = SRC.indexOf(`export async function ${name}(`);
    assert.ok(at > 0, name);
    assert.match(SRC.slice(at, at + 400), /await gate\("billing"\)/, `${name} must gate on billing`);
  }
});

test("destructive ops demand typed confirmation server-side", () => {
  const must = {
    startIpReassign: /confirm\.trim\(\) !== src\.dedicatedIp\.address/,
    startIpRelease: /confirm\.trim\(\) !== s\.dedicatedIp\.address/,
    startOrphanVmDestroy: /confirm\.trim\(\) !== String\(vmid\)/,
    startBulkPower: /confirm\.trim\(\)\.toUpperCase\(\) !== expected/,
    customerTransferServer: /confirm\.trim\(\) !== s\.hostname/,
  } as const;
  for (const [name, re] of Object.entries(must)) {
    const at = SRC.indexOf(`export async function ${name}(`);
    const next = SRC.indexOf("export async function", at + 10);
    assert.match(SRC.slice(at, next < 0 ? undefined : next), re, `${name} confirmation`);
  }
});

