async function run(payload: any, serverId: string | null = null) {
  const job = await db.job.create({ data: { type: "ADMIN_OPS", serverId, payload, status: "RUNNING", attempts: 1 } });
  let err: string | null = null;
  try { await adminOps(job); } catch (e: any) { err = e.message; }
  const after = await db.job.findUnique({ where: { id: job.id } });
  return { err, attempts: after!.attempts, result: (after!.payload as any).result, lock: adminOpsLockKey(job) };
}

async function main() {
  const node = await db.node.upsert({ where: { name: "sbx-primary" }, update: {}, create: { name: "sbx-primary", pveNode: "sbx", apiUrl: "https://127.0.0.1:1", tokenId: "x", tokenSecret: "x", publicIp: "198.51.100.1", isPrimary: true, subnetPrefix: "10.20.0." } });
  const plan = await db.plan.upsert({ where: { slug: "sbx-plan" }, update: {}, create: { slug: "sbx-plan", name: "SBX", cpuCores: 2, ramMB: 4096, diskGB: 40, priceCents: 899 } });
  const os = await db.osTemplate.upsert({ where: { slug: "sbx-ubuntu" }, update: {}, create: { slug: "sbx-ubuntu", name: "Ubuntu", vmid: 9000 } });
  const admin = await db.user.upsert({ where: { email: "admin@sbx.test" }, update: {}, create: { email: "admin@sbx.test", passwordHash: "x", name: "Admin", role: "ADMIN" } });
  const cust = await db.user.upsert({ where: { email: "cust@sbx.test" }, update: {}, create: { email: "cust@sbx.test", passwordHash: "x", name: "Cust" } });
  const mk = (h: string, vmid: number, data: any = {}) => db.server.upsert({ where: { hostname: h }, update: {}, create: { name: h, hostname: h, userId: cust.id, planId: plan.id, osTemplateId: os.id, nodeId: node.id, vmid, status: "RUNNING", ...data } });
  const a = await mk("sbx-a", 501, { ipAddress: "198.51.100.50" });
  const b = await mk("sbx-b", 502, { ipAddress: "10.20.0.102", sshPort: 20102 });
  await db.dedicatedIp.upsert({ where: { address: "198.51.100.50" }, update: { status: "ASSIGNED", serverId: a.id }, create: { address: "198.51.100.50", ovhBlock: "", nodeId: node.id, status: "ASSIGNED", serverId: a.id } });
  await db.dedicatedIp.upsert({ where: { address: "198.51.100.77" }, update: {}, create: { address: "198.51.100.77", ovhBlock: "", nodeId: node.id, status: "ASSIGNED", serverId: null } }); // orphan

  console.log("diagnose:", JSON.stringify((await run({ op: "diagnose", requestedBy: admin.id, serverId: b.id })).result?.diagnosis?.verdict));
  const g = await run({ op: "guest_cmd", requestedBy: admin.id, serverId: b.id, command: "journal_unit", params: { unit: "x; rm -rf /" } });
  console.log("guest_cmd hostile:", g.err, "attempts", g.attempts);
  const g2 = await run({ op: "guest_cmd", requestedBy: admin.id, serverId: b.id, command: "overview" });
  console.log("guest_cmd ok:", g2.err, (g2.result?.output ?? "").slice(0, 40));
  const r = await run({ op: "ip_reassign", requestedBy: admin.id, reason: "sandbox test", sourceServerId: a.id, targetServerId: b.id }, a.id);
  console.log("reassign:", r.err, JSON.stringify(r.result));
  const [a2, b2] = await Promise.all([db.server.findUnique({ where: { id: a.id }, include: { dedicatedIp: true } }), db.server.findUnique({ where: { id: b.id }, include: { dedicatedIp: true } })]);
  console.log("after: a", a2!.ipAddress, a2!.sshPort, a2!.dedicatedIp?.address ?? null, "| b", b2!.ipAddress, b2!.sshPort, b2!.dedicatedIp?.address, b2!.wantsDedicatedIp);
  const again = await run({ op: "ip_reassign", requestedBy: admin.id, reason: "sandbox test", sourceServerId: a.id, targetServerId: b.id }, a.id);
  console.log("reassign again (must refuse):", again.err, "attempts", again.attempts);
  const rel = await run({ op: "ip_release", requestedBy: admin.id, reason: "sandbox", serverId: b.id }, b.id);
  console.log("release:", rel.err, JSON.stringify(rel.result));
  const asg = await run({ op: "ip_assign", requestedBy: admin.id, reason: "sandbox", serverId: a.id, address: "198.51.100.50", billable: false }, a.id);
  console.log("assign:", asg.err, JSON.stringify(asg.result));
  const drift = await run({ op: "drift_scan", requestedBy: admin.id });
  console.log("drift:", drift.err, (drift.result?.findings ?? []).map((f: any) => `${f.kind}:${f.fix ?? "-"}`).join(", "));
  const orphan = (drift.result?.findings ?? []).find((f: any) => f.kind === "ip_orphan");
  if (orphan) console.log("orphan ip release:", (await run({ op: "orphan_ip_release", requestedBy: admin.id, reason: "sandbox", ipId: orphan.ipId })).result);
  const vmd = await run({ op: "orphan_vm_destroy", requestedBy: admin.id, reason: "sandbox", nodeId: node.id, vmid: 501 });
  console.log("destroy owned vm (must refuse):", vmd.err);
  const bulk = await run({ op: "bulk_power", requestedBy: admin.id, reason: "sbx", action: "delete", serverIds: [a.id, b.id], concurrency: 2 });
  console.log("bulk delete on customer servers (all skipped):", JSON.stringify(bulk.result?.children?.map((c: any) => c.skipped)));
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });

